window.REPORTS=[{"date": "2026-11-27", "edition": "10条 · 国内7条／海外3条", "updated": "10:18", "intro": "硬件供应商正把集成工作前移：钛虎优化含线缆安装空间，一目整合手臂、灵巧手与技能工具，选型需要比较整套安装和开发流程。工厂端，西门子送料验证与沃尔沃自有团队训练给出了更具体的推进步骤；两者仍需跨过现场试验到正式生产这一关。", "items": [{"title": "供应链｜国内｜钛虎Lite-1压缩关节轴向安装空间", "date": "11月26日发布", "body": "钛虎推出新一代Lite-1，将驱控板与编码器融合。公司称，同外径下轴向长度较上一代最多缩短22.5%；采用侧出线后，含线缆的轴向安装空间最多减少30%。产品覆盖40—80毫米五档外径，面向头部、手臂、腰部等位置。这次改进主要节省装机空间，选型时可将线缆弯折和安装余量一起比较；不能仅凭外径推断整关节的中孔尺寸。", "analysis": "", "sources": [{"label": "机器之心新品详文", "url": "https://jigou.jiqizhixin.com/articles/2026-11-26-10"}]}, {"title": "产品生态｜国内｜一目xEco向手臂与灵巧手一体化延伸", "date": "11月26日披露", "body": "一目在十周年公开信中公布xEco路线：以手臂与灵巧手集成的上肢硬件，配合xStudio技能软件、开发工具，以及xWorld社区和云端遥操作，减少开发者分别采购后再做安装、电气与算法适配的工作。公司明确不自研通用大脑，将通过接口接入第三方模型。本次公布的是生态与产品路线，具体工具开放及交付节奏仍待后续发布。", "analysis": "", "sources": [{"label": "量子位署名详文", "url": "https://www.sohu.com/a/1106801941_610300"}]}, {"title": "客户试点｜海外｜PIA用智元I-Bot 2.0验证西门子产线送料", "date": "11月26日官方案例", "body": "PIA披露西门子安贝格继电器工厂的概念验证：采用智元硬件的I-Bot 2.0搬运料箱，把接触件或塑料壳倒入数米外的送料装置，再送回空箱。机器人仍需逐台编程，视觉识别模块可小幅修改后复用。下一步将接入产线物料需求信号，目标2027年上半年具备部署条件；现场验证正在从搬运动作推进到生产线如何呼叫和管理机器人。", "analysis": "", "sources": [{"label": "PIA集成商官方案例", "url": "https://www.piagroup.com/en/news/2026-11-26-humanoid-robots-make-their-way-onto-the-factory-floor/"}]}, {"title": "客户试点｜海外｜沃尔沃用自有团队训练轮式AEON", "date": "11月26日买方公告", "body": "沃尔沃宣布在比利时根特工厂首次尝试人形机器人，由自有团队与Hexagon共同通过模仿学习训练轮式AEON。首个任务是向两个工装夹具放置零件，计划2027年上半年扩大试点，目标年中用于真实生产。买方正把现场训练能力纳入部署流程，接下来再扩展零件种类及生产系统交互，当前还不是正式生产上线。", "analysis": "", "sources": [{"label": "沃尔沃买方公告", "url": "https://www.volvocars.com/intl/media/press-releases/CC9EB8A9723DD536/"}]}, {"title": "开发套件｜中国台湾｜华擎RBK-100串联示教、训练与执行", "date": "11月24日｜近期补充", "body": "华擎工业发布RBK-100，组合NUC BOX-358H计算机、RGB-D彩色深度相机与六自由度主从机械臂，主从分别用于示教和跟随。AiRoboStarter串联数据采集、数据集检查、训练和技能运行；进阶版另提供语音、大语言模型等接口。套件面向具身开发与原型验证，ACT、π0.5、SmolVLA策略支持仍属于后续版本计划。", "analysis": "", "sources": [{"label": "华擎工业官方新品", "url": "https://www.asrockind.com/en-gb/article/326"}]}, {"title": "新品演示｜国内｜中联重科展示指令驱动挖掘与RobotOps", "date": "11月24—25日展会｜近期补充", "body": "中联重科在bauma CHINA展示由ZEBrain拆解指令、结合环境和物料执行挖掘、装载、削坡或夹取的方案，覆盖智慧矿山、城建及林业模拟场景。同期披露RobotOps作业平台，并展示轮式人形机器人的分拣作业。这批展示把任务理解与动作执行延伸到不同设备，后续能否跨场景复用，需要看连续作业和异常处理，而非仅看展会动作。", "analysis": "", "sources": [{"label": "财联社现场报道", "url": "https://api3.cls.cn/share/article/2543728?app=&os=ios&sv=855"}]}, {"title": "产业基础设施｜国内｜亦庄把数据采集、打样与小批试产连起来", "date": "11月25日发布；26日报道", "body": "亦庄在E-Bot Day公布“未来机域”建设计划，覆盖数据、制造、场景和人才。计划逐步开放近千个真实数据采集点位及50余个数采场所，并通过开源物料清单、开发者工坊与供应链平台支持打样、小批试产。面向九大场景的万台、近50亿元应用需求同属后续释放计划，不能视为已签订单；实际接入条件将影响团队能否用上这些资源。", "analysis": "", "sources": [{"label": "北京科创中心官网／亦庄官微", "url": "https://www.ncsti.gov.cn/kjdt/scyq/bjjjjskfq/jkdt/202611/t20261126_265719.html"}]}, {"title": "模型研究｜国内｜SPIRE 2.0把基础动作组合成连续作业", "date": "11月25日技术发布｜近期补充", "body": "浙江人形升级SPIRE 2.0，贯通数据、任务表示、动作策略和技能库：把何时抓稳、何时松手与物体位置关联，再将插拔、按压等技能组合成服装处理、物流和实验室流程。团队披露已积累22万余条精细标注真机作业数据，并展示服装分片、移片及对齐应用。相较孤立技能，改进重点是连续流程的复用；所报效果仍主要来自公司测试。", "analysis": "", "sources": [{"label": "机器之心技术详文", "url": "https://jigou.jiqizhixin.com/articles/2026-11-25-11"}]}, {"title": "模型研究｜国内｜RoboRSI-27B检查动作，再用代码修正", "date": "11月25日技术博客｜近期补充", "body": "商汤RoboRSI-27B将高层模型、视觉语言动作策略和代码工具结合，检查候选动作，必要时修正夹爪目标。团队每模型每任务测试10次，Piper抓放完成6次、PiperX叠块9次。高层模型的具身后训练在仿真完成，但底层动作策略仍用真实机器人数据。代码仓库与27B模型入口已提供；这展示了执行监督与纠错路径，十次样本尚不足以判断长期可靠性。", "analysis": "", "sources": [{"label": "商汤技术博客", "url": "https://huggingface.co/blog/sensenova/roborsi"}, {"label": "官方代码仓库", "url": "https://github.com/OpenSenseNova/SenseNova-RoboRSI"}]}, {"title": "算法研究｜海外｜HeadLight用少量参数更新适配新工序", "date": "11月25日预印本｜近期补充", "body": "HeadLight面向同时预测未来画面与动作的世界动作模型，选择负责抓放目标和运动跟踪的模块微调。Zero-WAM仅更新1.1%参数，在RoboTwin六项未见任务上平均成功率62.3%，全参数微调为57.9%；另做了Franka真机四项未见任务、每项20次验证。这为减少新工序适配时的参数更新提供路径，但初次筛选仍需交互位置标注，不能直接推算总体费用节省。", "analysis": "", "sources": [{"label": "HeadLight论文原文", "url": "https://arxiv.org/html/2611.33963v1"}]}], "followups": ["PIA接入补料信号、沃尔沃扩大试点后，复查实际节拍、接管频次与换件表现。", "Lite-1安装图与热曲线、xEco开发工具开放后，核对装机条件和接口可用性；WALL-OSS 1.0正式权重或第三方复现出现新证据时再跟进。"], "coverage": "主检索窗口：11月26日10:18至11月27日10:18（UTC+8）；补充未报道的11月24—25日进展。部分公众号原文与列表仍有访问、更新滞后缺口。"}, {"date": "2026-11-26", "edition": "9条 · 国内7条／海外2条", "updated": "10:18", "intro": "机器人新品开始把任务入口、异常处理和开发支持一起打包：小鹏公布门店助手路线，众擎补充巡检工作流程，选型需要比较整套系统如何运行。客户侧，杭州邮政的多台供包项目与Bleckmann的小批采购展示了两种推进方式：具体工序持续调试，以及先入场积累训练经验。", "items": [{"title": "新品｜国内｜小鹏IRON明年进店训练，公布任务与运维功能", "date": "11月25日发布", "body": "小鹏在科技日公布IRON的新功能：自主导航、语音或App创建任务、自主充电、异常报告及运行健康监测。整机具备76个自由度、1500多个触觉感知点，搭载3颗图灵芯片。官网给出的安排是2027年一季度进入小鹏门店训练，二季度正式对外发布。公司还在开发能力包下载、功能定制和技能验证平台，将硬件销售与软件订阅结合。相比此前步态展示，这次披露更接近门店工作所需的任务入口和运维流程。", "analysis": "", "sources": [{"label": "小鹏官方发布", "url": "https://www.xpeng.com/news/01a212b0d830a1e838d68a02a2110174"}]}, {"title": "产品与生态｜国内｜众擎发布智慧巡检方案和开发者支持计划", "date": "11月25日发布会；11月26日详细报道", "body": "众擎在开发者大会发布智慧巡检方案，将工厂自主导航、云端协同乘梯、巡检操作、异常识别和数据回传串成工作流程。配套“引擎计划”提供教程、工具包、训练示例及项目评估，并规划设备借用、联合实验室和商业概念验证支持。公司同时提出不少于10亿元的产业支持计划。此前仅有简短发布配文的全身遥操，也出现在PM01、T800现场体验中；本期主要新增信息是巡检方案和开发者合作机制。", "analysis": "", "sources": [{"label": "CSDN资讯发布会详文", "url": "https://damodev.csdn.net/6b077a77e5f4ca4eff93cc7c.html"}]}, {"title": "商业落地｜国内｜星动纪元披露杭州邮政45台M7供包项目", "date": "11月25日披露；9月初部署投测", "body": "据北京商报记者转述星动纪元披露，杭州邮政、星动纪元与我能具身合作，45台M7进驻杭州邮区中心，承接小件供包。方案于9月初完成部署投测，近期继续优化供件效率。此前已报道的是广东八城十一节点布局，本次增加了杭州单个项目的规模与投测进展。对物流机器人而言，观察对象已从单次抓包展示转向同一业务节点上的多台部署及持续调试。", "analysis": "", "sources": [{"label": "北京商报原文", "url": "https://www.bbtnews.com.cn/2026/1125/612229.shtml"}]}, {"title": "新品与价格｜国内｜Boomy启动海外众筹，区分标准版与开发版", "date": "11月24日｜近期补充", "body": "松延动力NOETIX宣布Boomy上线Kickstarter，标准版超级早鸟价3599美元，EDU版5999美元。机器人有21个主动关节，支持手动示教、预设动作、App控制和语音交互。标准版面向核心体验与高层开发；EDU版增加Jetson计算、RealSense D435i深度相机和底层开发权限，便于继续开发视觉与控制应用。这是面向创客、教育和研发用户的海外众筹销售，尚非交付完成。", "analysis": "", "sources": [{"label": "Boomy官方产品页", "url": "https://boomy.noetixrobotics.com/"}]}, {"title": "基础设施｜国内｜九章云极推出物理AI工厂服务体系", "date": "11月25日发布", "body": "九章云极推出Physical AI Factory，把异构算力调度、弹性训练推理、强化学习环境和多阶段任务编排组成研发服务体系，仿真、合成数据及软件／硬件在环验证由生态伙伴共同提供。公司公布资源调度与开发任务两层接口的开放路线图、试点接入机制，并与深圳龙华工信局、清程智汇、怡亚通签署战略合作协议。这套服务希望减少团队分别搭建算力、仿真和验证环境的集成工作，目前进入合作与试点接入阶段。", "analysis": "", "sources": [{"label": "九章云极供稿／量子位转载", "url": "https://www.qbitai.com/2026/11/512582.html"}]}, {"title": "客户试点｜海外｜Bleckmann购入两台人形机器人，先做仓储训练", "date": "11月24日｜近期补充", "body": "物流企业Bleckmann披露已购入两台人形机器人，预计未来数周交付欧洲选定配送中心，探索搬运、拣选等工作。接下来数月先用于任务训练、人机协作学习和数据积累，公司明确不期待投用第一天就提升效率。买方正在为后续应用积累现场经验，这也给出了较具体的试点路径：先让机器人与仓库团队共同学习，再评估可以承担哪些重复工序。", "analysis": "", "sources": [{"label": "Bleckmann买方公告", "url": "https://www.bleckmann.com/press/bleckmann-humanoid-robots-warehouses"}]}, {"title": "算法研究｜国内｜G0.7：记住数分钟过程，直接生成下一段动作", "date": "11月24日预印本｜近期补充", "body": "星海图团队发布G0.7，沿用Fast-WAM，可读取最多5分钟真实相机历史，并把人的示范视频作为上下文。训练时联合学习视频与动作，部署时省去未来画面生成，直接输出16步动作块；团队报告，单RTX5090、FP8计算配置下每块耗时60毫秒。这为长流程记忆和示范引导操作提供了路径。论文已做真机抓放、记忆和分拣测试，其中示范分拣与记忆任务经过专门后训练，仍需验证换到新工作流程后的适配成本。", "analysis": "", "sources": [{"label": "星海图研究预印本", "url": "https://arxiv.org/html/2611.31822v1"}]}, {"title": "算法研究｜国内｜Motubrain 2.0：把操作、检查和失败恢复接起来", "date": "11月24日官方博客｜近期补充", "body": "生数科技将200亿参数世界动作模型与任务编排系统Harness结合：模型根据图像和指令预测画面与动作，Harness负责拆任务、选动作模型或几何工具、安排导航，并在每步操作后看图检查结果，失败时换工具或调整指令。公司在相同10项家庭任务中报告，两个版本各测试71次，完成率由44%升至63%。这轮改进修改的是工具、技能和指令，动作模型及高层规划模型的权重保持不变。它提示长流程的改善也可以来自执行系统；代码和权重入口仍预告下周开放。", "analysis": "", "sources": [{"label": "生数科技官方技术博客", "url": "https://www.motubrain.com/en/blog/motubrain-2/"}]}, {"title": "算法研究｜海外｜OmniAct：换机械臂后，按身体结构选择抓取方式", "date": "11月24日UTC预印本；11月25日进入论文列表", "body": "华盛顿大学等团队的OmniAct，把机械臂关节位置、转轴和连接关系与相机看到的场景一起输入策略，让机器人按自身臂长和关节结构选择动作，而非照搬一种抓取姿势。团队在大量程序生成的机械臂仿真中训练；换到未见过的OpenYAM及新夹爪后，真实抓放20次完成13次，对照MolmoAct2为7次。这为减少换硬件后的示范重采和重训提供了思路，但实机验证仍是小规模抓放，双臂与人形全身控制尚待扩展；仓库目前也仍在准备代码和权重。", "analysis": "", "sources": [{"label": "论文预印本", "url": "https://arxiv.org/html/2611.33158v1"}]}], "followups": ["小鹏门店训练公布任务清单、接管频率和收费版本后，复查IRON可承担的实际工作。", "众擎巡检或杭州M7项目披露连续运行和现场验收结果时，核对异常处理与人工介入情况。", "Motubrain代码、权重按预告开放后核对复现条件；继续跟踪WALL-OSS 1.0正式权重及第三方结果。"], "coverage": "主检索窗口：11月25日10:15至11月26日10:18（UTC+8）；补充未报道的11月24日进展。部分公众号原文仍有访问缺口，已用公开分发与原始资料交叉核查。"}, {"date": "2026-11-25", "edition": "8条 · 国内5条／海外3条", "updated": "10:15", "intro": "今天的产业进展更贴近具体工序：智元G2接入芯片测试线，Bigwave把移动搬运与机床信号连起来，整机能力开始接受现场流程的检验。模型侧，小鹏WorldGPT探索跨本体共享能力，智源REAL则把评测推进到物流、零售等业务任务；选型时需要同时看模型能力和工序表现。", "items": [{"title": "商业落地｜国内｜智元G2进入长电芯片测试线试运行", "date": "11月23日披露，11月24日采访补充", "body": "据证券日报采访，首批G2已在长电科技上海临港芯片测试线完成工艺适配、现场调试和产线并行试运行。机器人对接MES制造执行系统与EAP设备自动化程序，负责测试前料盘上料、测试后下料，并将良品与不良品分流。相比此前蓝思手机测试场景，此次新增的是半导体工序适配及与既有系统联动。公司称这条作业链无需人工干预，目前进展仍是产线试运行。", "analysis": "", "sources": [{"label": "证券日报记者采访", "url": "https://finance.sina.com.cn/jjxw/2026-11-24/doc-inizvqth9048119.shtml"}]}, {"title": "新品与落地｜国内｜网易灵动发布灵掘2.0，携柳工推进智能挖掘机", "date": "11月24日展会，11月25日采访刊发", "body": "网易灵动在bauma CHINA发布灵掘2.0，并与柳工签约推进智能挖掘机规模量产和出海。证券时报记者现场看到，922FE收到指令后完成导航、避障、挖掘与装车，过程中无需人工接管。新系统结合视觉、语言和激光雷达信息预判作业，让动臂、斗杆、铲斗与回转连续配合。此次变化是控制系统升级及主机厂合作深化，922FE本体并非首次亮相，量产与出口仍属后续计划。", "analysis": "", "sources": [{"label": "证券时报展会现场采访", "url": "https://finance.sina.com.cn/stock/t/2026-11-25/doc-inizwwnp9652090.shtml"}]}, {"title": "算法研究｜国内｜WorldGPT：让不同机器人共享对未来动作的预测", "date": "11月24日发布", "body": "小鹏WorldGPT用同一套权重联合学习汽车、船、无人机、单臂、双臂和人形六类本体，从短视频与指令预测后续画面和动作，拟将云端能力蒸馏到各类端侧模型。官方在Meta-World MT50的50项单臂仿真任务上报告95.2%成功率。项目页的对照视频在首秒之后展示的是模型生成预测，不能当作完整真机执行录像；跨本体迁移还需看后续技术报告与实际控制结果。", "analysis": "", "sources": [{"label": "小鹏WorldGPT官方项目页", "url": "https://worldgpt-1.github.io/"}]}, {"title": "模型评测｜国内｜智源REAL把具身评测推向具体业务任务", "date": "11月24日发布", "body": "智源发布REAL具身评测体系及首批四个排行榜、四个基准，并推出具身智能奥赛，场景对接顺丰物流、吉利汽车零售、海尔家居和TCL工业。评测关注时间、成本、效率与安全，让机器人能力更接近业务流程的要求。对部署选型而言，这类任务可以补充单项抓取成功率，帮助判断一套系统能否完成实际工作，后续可结合公开任务流程与测评报告做同口径比较。", "analysis": "", "sources": [{"label": "新浪科技发布会现场报道", "url": "https://finance.sina.com.cn/tech/shenji/2026-11-24/doc-inizvkmk9003785.shtml"}]}, {"title": "商业落地｜海外｜Bigwave用双足机器人串起汽车零件矫直工序", "date": "11月24日披露", "body": "Bigwave介绍了韩国一家汽车零部件工厂的产线试点：双足人形机器人先将发动机零件放入矫直设备，再步行约10米到出料端，把加工好的零件取出并堆放至转运车。系统与PLC可编程逻辑控制器交换作业信号，配合既有机床节奏；行走在仿真中训练，物料处理采用模仿学习。这里的实质进展是把上下料、步行搬运和设备联动接成流程，让机器人进入固定自动化设备之间的空缺环节。", "analysis": "", "sources": [{"label": "Bigwave官方产线说明", "url": "https://us.bigwaverobotics.com/investors/news/RKGuvR96jlmIkTbVccTq"}]}, {"title": "客户验证｜海外｜KG Steel为钢卷包装工序设定机器人验收目标", "date": "11月24日披露；10月引入设备", "body": "KG Steel在唐津工厂试验AeiRobot的ALICE M2，任务是抓取、搬运并堆叠钢卷包装用的内径环。零件位置和堆放状态不固定，是这项自动化需要解决的问题。公司设定的验收目标包括作业成功率达到90%以上、连续完成至少50次作业；这些是目标，尚非已达成绩。团队通过工人动作视频和头戴设备遥操作采集示范，继续开发导航与堆叠功能。买方开始明确验收条件，提供了比单次演示更具体的落地观察点。", "analysis": "", "sources": [{"label": "韩联社企业验证报道", "url": "https://www.yna.co.kr/amp/view/AKR20261124110600003"}]}, {"title": "新品｜海外｜YYForce发布酒店礼宾人形机器人Six Seven", "date": "11月24日发布", "body": "YYForce发布Six Seven酒店礼宾人形机器人，首个拟部署地点为Novotel Singapore on Stevens。它面向住客问询，可回答设施位置、餐厅开放时间、菜单与活动安排，也提供新加坡旅行信息及对话互动。产品将酒店资料接入WorkforceOS，采用NVIDIA Jetson边缘计算和Isaac Sim仿真训练。服务范围围绕信息咨询展开，接下来要看酒店资料更新、住客实际使用及异常问询如何处理。", "analysis": "", "sources": [{"label": "YYForce官方新闻稿", "url": "https://www.globenewswire.com/news-release/2026/11/24/3409160/0/en/YYForce-NASDAQ-YFOR-Launches-Trained-Humanoid-Robot-for-Hotel-Concierge-Service-Using-NVIDIA-Jetson-and-Isaac-Sim.html"}]}, {"title": "算法研究｜国内｜RoboUniverse-10K：把操作视频变成可重复训练的仿真任务", "date": "11月23日UTC预印本，11月24日传播｜近期补充", "body": "团队从真实操作视频构建10,807个可重置的物理仿真环境，留下500项未见任务评测。模型通过编写程序观察和控制机器人，评分逻辑与执行环境隔离，减少依赖隐藏答案的空间。作者对Qwen模型做监督微调后，仿真成功率由0.8%升至21.2%，代码已开放。这为训练提供了更多可重复试错的场景，但任务仍以短操作为主，复杂接触物理与长流程尚待完善。", "analysis": "", "sources": [{"label": "论文预印本", "url": "https://arxiv.org/abs/2611.31002"}, {"label": "作者代码", "url": "https://github.com/Einsia/RoboUniverse-10K"}]}], "followups": ["小鹏今天14:00科技日及众擎开发者大会后，核查IRON新功能、WorldGPT技术材料，以及众擎遥操平台的实质说明；预告不作为正式结果。", "G2、Bigwave和KG Steel公布运行记录时，复查节拍、接管情况及连续作业是否达到买方目标；Six Seven则跟踪酒店正式上线与住客使用。", "WALL-OSS-1.0出现正式权重或外部真机结果时再更新，避免重复昨天的发布内容。"], "coverage": "主检索窗口：2026-11-24 10:20至2026-11-25 10:15（UTC+8）。部分公众号原文及新论文尚有覆盖缺口；RoboUniverse按实际论文日期作为近期补充。"}, {"date": "2026-11-24", "edition": "8条 · 国内6条／海外2条 · 已更正", "updated": "14:12", "intro": "今天最值得看的是自变量 WALL-OSS-1.0：动作开始与图像、语言共同预训练，目标是减少每个新任务的专门训练。产品端，“小唯”将面部表达与触觉互动结合，XROGO则用免租和远程协同推进进厂试用；两条路线分别在探索交互体验与工位使用成本。通用模型真机评测也有进展，但任务完成速度仍值得单独考察。", "items": [{"title": "算法研究｜国内｜WALL-OSS-1.0：减少新任务的专门训练", "date": "2026-11-23", "body": "自变量以Qwen3.5为起点，让机器人动作和图像、文字一起学习，再训练动作专家输出连续动作，并加入动作描述、判断与人工纠错。直观地说，是先把“看到什么、要做什么、怎么动”一起学，再练精细操作，减少逐项教新任务的需求。公司内部开放式真机评测覆盖312个独立任务，未经任务专属微调的零样本成功率为55.1%。", "analysis": "这一变化主要面向任务多变的操作场景，仍需观察外部机器人上的表现。当前可申请API接入；已公开的Lite轻量版预览权重并不等同于本次正式版本，不能理解为正式全系权重均已开放。", "sources": [{"label": "自变量官方技术博客", "url": "https://x2robot.com/blog/wall-oss-1"}, {"label": "官方API接入文档", "url": "https://x2robot.com/docs/quantax1pro/v1/model-development/wallx-api/api-usage-instruction"}]}, {"title": "新品｜国内｜光锥交互发布“小唯”，把表情与触觉放进同一张脸", "date": "2026-11-21｜周末重要进展", "body": "光锥交互发布仿生情感机器人“小唯”与硅胶电子皮肤，半身版预售6.98万元起。北京日报记者现场看到机器人配合对话张合嘴唇、做手臂动作；半身共84个自由度，面部采用线驱为主、电驱为辅的方案。电子皮肤利用接触产生的电信号识别触碰，并采用柔性电极适应表情引起的反复形变。", "analysis": "产品重点落在陪伴、服务中的近距离交流，后续使用体验将取决于表情、语音和触觉响应能否长期协调。", "sources": [{"label": "北京日报发布会现场报道", "url": "https://news.bjd.com.cn/2026/11/21/12038984.shtml"}]}, {"title": "供应链｜国内｜元触万物电子皮肤开始向机器人与灵巧手企业送样", "date": "2026-11-23报道", "body": "据硬氪采访，元触万物已完成样机和灵巧手皮肤动态感知演示，并向本体及灵巧手企业送样，先从手指推进到全掌、全身。其薄膜晶体管柔性阵列把部分信号判断和第一层特征提取放在皮肤端，再向后端传输压缩特征，以减轻密集触点的布线、带宽和处理压力。", "analysis": "这让电子皮肤兼顾感知与前端处理，目前进展是送样和协同开发，下一步看客户集成结果。", "sources": [{"label": "硬氪采访（页面标注商业策划）", "url": "https://www.36kr.com/p/4081842109830016"}]}, {"title": "商业落地｜国内｜XROGO推出工位免租试用和远程协同方案", "date": "2026-11-23披露", "body": "XROGO介绍“机器人到岗计划”：首批50台免4个月租金，支持购机、订阅或按月租。方案采用远程协同和遥操作兜底，工人可用自然语言指导，也可通过遥操作传授技能、积累训练数据。公司希望让工厂先在单个工位试用，再决定是否扩展。", "analysis": "试用降低了前期投入，比较持续使用成本时还需计入远程人工与免租期后的费用。", "sources": [{"label": "XROGO供稿／量子位刊发", "url": "https://www.qbitai.com/2026/11/512179.html"}]}, {"title": "数据产业｜国内｜中汽创智筹备10万小时级汽车产线操作数据", "date": "2026-11-20发言｜11月23日官方披露", "body": "中汽创智正与股东方策划生产线真实数据采集项目，拟收集超过10万小时工人第一视角作业数据。公司已建小型采集中心，配备真机与第一视角采集系统，验证从采集、训练到模型应用的链路。汽车行业已有的标注、评测和数据回流工具链，有机会迁移到具身智能。", "analysis": "10万小时是项目目标；生产线视频要形成可用的机器人训练数据，仍需要解决动作对齐与质量筛选。", "sources": [{"label": "中汽创智官方大会回顾", "url": "https://www.t3caic.com/list_8/719.html"}, {"label": "盖世具身智能现场报道", "url": "https://auto.gasgoo.com/news/202611/23I70478830C601.shtml"}]}, {"title": "竞品｜海外｜安川计划2030年推出AI人形机器人", "date": "2026-11-20｜近期补充", "body": "安川方面接受共同社采访时表示，计划2030年推出正在开发的AI人形机器人，若客户有需求可提前。项目将利用2025年收购Tokyo Robotics获得的技术，面向农业等需要在狭窄空间灵活动作的领域。受访者指出，自主学习尚不成熟，逐项教任务耗时，公司正与富士通、英伟达探索解决方案。", "analysis": "传统自动化厂商的切入时间和目标场景更清晰了，目前披露仍是研发及市场计划。", "sources": [{"label": "共同社原始采访／47NEWS", "url": "https://www.47news.jp/15261225.html"}]}, {"title": "产业政策｜海外｜美国NIOSH征集人形机器人工作场所安全研究需求", "date": "2026-11-23", "body": "美国国家职业安全与健康研究所（NIOSH）征集人形机器人工作场所研究重点，意见截止2027年2月22日。内容包括伤害与险情数据、真实工况测试、人机交互及安全控制；本次征询不提出新法规或新要求。", "analysis": "从征询方向看，近距离人机协作的验证将更加重视连续运行中的险情记录和恢复机制，设备选型时可提前积累这些数据。", "sources": [{"label": "美国联邦公报原文", "url": "https://www.federalregister.gov/documents/2026/11/23/2026-23799/national-institute-for-occupational-safety-and-health-niosh-center-for-occupational-robotics"}]}, {"title": "算法研究｜国内｜RoboChallenge Zero：通用模型能操作真机，速度仍是瓶颈", "date": "2026-11-23｜近期补充", "body": "主办方让11个多模态模型在两类真机、6项任务上测试，通过统一工具接口指定末端位姿和夹爪动作，再由控制器执行。GPT-6.2 Astra成功率为70%，但成功的积木放置和玩偶抓取平均仍需13—14分钟。它检验的是视觉推理与工具调用能力，并非模型直接高频控制关节。", "analysis": "这有助于判断通用模型能承担哪些操作任务；与视觉—语言—动作模型（VLA）比较时，还需要统一任务和时间预算。", "sources": [{"label": "RoboChallenge主办方原稿／量子位", "url": "https://www.qbitai.com/2026/11/511978.html"}]}], "followups": ["WALL公布正式权重或外部真机结果时，复查开放范围、跨任务表现与接入要求；RoboChallenge增加统一时间预算后，再比较速度与成功率。", "“小唯”开始交付、电子皮肤出现客户验证结果或XROGO免租期结束时，分别跟进交互耐久性、批量供货与续租情况。", "中汽创智披露采集进度时，核对实际数据量、可用率及动作对齐方式。"], "coverage": "更正（11月24日14:12）：撤下原第5条众擎“平行时空”。原阅读链接仅有发布配文，未提供实质正文；追查到的微博视频本次无法播放，尚不足以形成完整报道。其发布线索保留跟踪，已发群消息未改写。主检索窗口仍为2026-11-23 11:31至2026-11-24 10:20（UTC+8）；另补入11月20日安川、11月21日小唯及11月23日较早发布的RoboChallenge进展。公众号原文及部分最新论文仍有检索缺口。"}, {"date": "2026-11-23", "edition": "7条 · 国内4条／海外3条", "updated": "11:31", "intro": "从蓝思手机测试到邮政分拣，新增证据开始落到具体工序、部署数量和跨站点复制；相比单次演示，后续更值得看持续运行与现场适配。通用模型真机工具调用成绩提升，仿真长任务仍暴露组合执行难点，两者需要结合耗时与失败恢复来理解。Foundation的资金压力报道也提醒我们，扩产目标要与履约条件一起看。", "items": [{"title": "产业落地｜国内｜数十台精灵G2进入蓝思手机测试产线", "date": "2026-11-20", "body": "每日经济新闻引界面新闻报道，智元与蓝思科技达成战略合作，数十台精灵G2进入手机生产测试产线，承担自动上下料与设备交互，覆盖人机交互、天线、相机等测试工序。此次进展落到了成批设备与具体工序，后续仍需跑通全面工艺适配和产线联调，才能形成可复制的交付方案。", "analysis": "", "sources": [{"label": "每日经济新闻（引界面新闻）", "url": "https://www.nbd.com.cn/articles/2026-11-20/4653942.html"}]}, {"title": "供应链｜国内｜灵掌展示9款灵巧手，重载与空间应用分线推进", "date": "2026-11-19—21展会｜11-20报道", "body": "雷峰网采访报道，灵掌在南京世界智能制造大会展示9款二指至五指灵巧手，演示双臂搬物料箱及航空插头识别、插接和旋紧。公司称LZ-Pro最大抓取力30kg；面向空间应用的LZ-Space完成了搭载及地面振动、热真空、辐射测试，后续才进行飞行验证。产品选型开始更具体地区分工业重载、精细操作和特殊环境。", "analysis": "", "sources": [{"label": "雷峰网采访", "url": "https://m.leiphone.com/category/industrynews/leaIWtsEkg58zaCy.html"}]}, {"title": "商业落地｜国内｜星动M7扩至广东八市11个邮区节点", "date": "2026-11-17｜近期补充", "body": "澎湃新闻报道，M7已部署至广东八市11个邮区中心节点，据介绍常态平均分拣效率超过每小时1500件，支持异形包裹剔除、动态速率匹配和柔性翻包，无需改变现有产线。此前本报报道的是大促峰值，此次新增的是跨城市部署范围与常态平均口径；这让产线适配和跨站点复制更值得关注。", "analysis": "", "sources": [{"label": "澎湃新闻", "url": "https://www.thepaper.cn/newsDetail_forward_34492516"}]}, {"title": "工厂试点｜海外｜Bleu披露Novares连续包装试验", "date": "2026-11-20报告更新｜试验日未披露", "body": "Bleu Robotics披露，团队在Novares工厂使用固定工位的Unitree G1-D轮式双臂，以11段有效示教训练包装任务。最终97分钟试验包装252/253件，完成率99.6%；按抓取次数计为252/258，即97.7%，期间有一次人工转动物料。团队还处理了肩部电机过热问题。连续运行记录把重试和热管理带到了台前，仍需更长班次验证。", "analysis": "", "sources": [{"label": "Bleu Robotics现场报告", "url": "https://bleu-robotics.com/blog/novares-packing-1-hour-trial"}]}, {"title": "产业动态｜海外｜Foundation出现工资福利付款压力", "date": "2026-11-22美国报道｜UTC+8为11-23", "body": "CNBC根据取得的员工邮件及福利服务商Rippling回应报道，Foundation员工医保被追溯至10月终止，公司正寻求过桥融资，Base Group潜在1.5亿美元投资尚未最终敲定。公司邮件称将安排延续医保、报销保费并更换服务商。这为此前Phantom MKII新品及2027年扩产计划补充了经营风险信息，履约能力需结合资金与人员稳定性判断。", "analysis": "", "sources": [{"label": "CNBC原始报道", "url": "https://www.cnbc.com/2026/11/22/foundation-future-industries-health-benefits-payroll-base-group.html"}]}, {"title": "算法研究｜海外｜Ember-0真机评测：通用模型通过工具操纵双臂", "date": "2026-11-21报道｜11-23复核榜单", "body": "XDOF原始榜单显示，在16项共享真机任务、每任务30次重复的协议下，Astra 6.2各任务等权平均成功率41.2%，Astra 6为19.6%。模型看相机图像、调用运动工具操纵双臂，属于任务层决策，未直接输出高频关节动作。单任务上限30分钟，因此成绩提升更适合用于评估通用模型的规划与纠错能力，还不能等同工业作业节拍。", "analysis": "", "sources": [{"label": "XDOF原始真机榜单", "url": "https://benchmarks.xdof.ai/"}, {"label": "XDOF评测方法", "url": "https://www.xdof.ai/blog/evaluating-llms"}]}, {"title": "算法研究｜国内｜Mind2Act World拆解推理与操作组合后的失败", "date": "2026-11-20（UTC+8）｜预印本补充", "body": "清华、人大等与海外机构合作推出Mind2Act World预印本，用30个双臂仿真任务分别测试推理、动作及二者组合。GPT-6 Astra在推理组成功率52.7%，组合组为12%；不同任务组呈现出长任务的难度，不能直接作因果比较。评测按阶段定位首次失败，可帮助判断应补规划数据还是改动作策略。代码已公开，但模型思考时仿真暂停，尚未验证真机实时运行。", "analysis": "", "sources": [{"label": "论文原文", "url": "https://arxiv.org/html/2611.26444v1"}, {"label": "项目代码", "url": "https://github.com/Mind2Act/Mind2Act_World"}]}], "followups": ["智元／蓝思或M7披露整班运行、接管率和客户验收时，复查跨工序、跨节点复制效果。", "Foundation出现融资到账或11月30日薪资节点的公开新证据时，复查交付及扩产计划是否调整。", "XDOF更新成本与耗时数据、Mind2Act出现真机验证时，复查通用模型在实际作业中的可用性。"], "coverage": "主检索窗口：2026-11-20 10:10至2026-11-23 11:31（UTC+8），覆盖周末；另补充11月17日M7部署及11月20日凌晨Mind2Act预印本。研究2/7；国内4/7。部分公众号原文和当前文章列表未能完整取得，缺口已留存审计。"}, {"date": "2026-11-20", "edition": "9条 · 国内6条／海外3条", "updated": "10:10", "intro": "全家的饮料补货推广由买方给出明确起步时间，大晓则把便利店技能训练前移到基地；据此判断，零售项目更值得比较的是完整作业流程和现场运维。国内新标准与CloudRobo合作，进一步细化了部件测试、数据管理和部署接口。两项真机研究也提醒我们：接触操作的改善取决于触觉如何表达、力控工具如何接入，比较时应看完整系统。", "items": [{"title": "行业标准｜国内｜训练、关节和灵巧手有了新的行业规范", "date": "2026-11-16｜近期补充", "body": "工信部公布的标准覆盖训练场构建、训练数据管理、智能化能力分级、一体化关节和灵巧手，另有具身智能数据生成系统技术要求，相关六项自发布之日起实施。其中，关节规范涉及结构、接口、性能、安全及试验方法，灵巧手另行规定感知、抓取和操作测试。这些具体项目可作为采购和研发制定验收方案的参考。", "analysis": "", "sources": [{"label": "工信部公告", "url": "https://www.miit.gov.cn/jgsj/kjs/wjfb/art/2026/art_1ecfcc7030e949c79254b6fafa01f0fa.html"}, {"label": "标准附件第34—36页", "url": "https://www.miit.gov.cn/cms_files/filemanager/1226211233/attach/202611/6d2b9d84f80c435fb9c2feff84529863.pdf"}]}, {"title": "场景合作｜国内｜大晓与快客达建立便利店技能训练基地", "date": "2026-11-18披露｜近期补充", "body": "大晓披露，双方在德清建立联合基地，让数十台机器人同步学习食品取用、打包整理和透明小物抓取等零售技能。方案由通用模型理解和规划任务，开悟世界模型预测动作后果，再用真机反馈迭代技能。公司提出2027年推动数千台机器人进入便利零售网络的目标。基地训练如何转成门店可复用的作业流程，是这次合作值得追踪的环节。", "analysis": "", "sources": [{"label": "大晓机器人公众号原稿转载（我的钢铁网）", "url": "https://news.mysteel.com/a/26111817/405BE9C3829373AE.html"}]}, {"title": "现场应用｜国内｜爱宝与椰仔在APEC新闻中心提供服务", "date": "2026-11-17现场｜11-18报道", "body": "中新社记者在APEC新闻中心看到，智平方七台爱宝同时制作咖啡、冰淇淋和果汁，自变量椰仔递送零食、饮水，并在人离开后清理桌面杂物。前者把制作与递送串起来，后者处理服务后的收拾工作，两类机器人在同一会场承担不同工序。这为观察真实人流下的交互和操作提供了现场案例，长期运行情况还需后续跟踪。", "analysis": "", "sources": [{"label": "中新社记者现场报道（国际在线转载）", "url": "https://big5.cri.cn/gate/big5/ge.cri.cn/20261118/1e315a54-83d9-47f2-9725-d38fbe11e756.html"}]}, {"title": "开发平台｜国内｜CloudRobo扩展接入工程与高校实训合作", "date": "2026-11-18论坛｜11-20报道", "body": "量子位报道，华为云在上海论坛介绍CloudRobo通过统一接入协议和开发工具包，连接数据处理、训练、仿真与真机部署，并支持导入机器人结构文件。华为云与福建小状智能签署备忘录，拟将平台和昇腾算力用于高校实训；上海交大团队分享了30名学生从仿真到真机的训练营实践。这里新增的是工程合作与使用案例，能够帮助观察平台如何减少重复搭环境的工作。", "analysis": "", "sources": [{"label": "量子位论坛报道", "url": "https://www.qbitai.com/2026/11/511426.html"}]}, {"title": "新品本体｜海外｜Phantom MKII强调重载与现场维修", "date": "2026-11-18｜近期补充", "body": "Foundation向Fast Company介绍Phantom MKII，面向制造、建筑等环境，采用耐候关节和可现场更换的模块化结构。首席执行官称，机器人行走负载从上一代约50—60磅提升至200磅，约91公斤。公司计划2027年初生产数百台、年底扩大至数千台。除了负载，模块更换是否方便也会影响客户的停机时间和维护方式。", "analysis": "", "sources": [{"label": "Fast Company原始采访", "url": "https://www.fastcompany.com/91643258/foundation-future-industries-humanoid-robot-war"}]}, {"title": "客户部署｜海外｜全家确认明年1月起推广饮料补货机器人", "date": "2026-11-19", "body": "全家公告，2027年1月起在日本门店分阶段推广TX GHOST及数字库存架Smart Shelf。先行门店的饮料库存管理与补货相关作业时间每天约减少70%；员工向库存架装货，再由机器人补至销售货架。Telexistence说明，瓶子倒下等异常仍由远程操作员协助。此次由买方明确推广时间，后续可比较节省的工时与远程维护投入。", "analysis": "", "sources": [{"label": "全家买方公告", "url": "https://www.family.co.jp/company/news_releases/2026/20261119_02.html"}, {"label": "Telexistence公告", "url": "https://tx-inc.com/en/blog/2026/11/19/12836/"}]}, {"title": "数据研究｜国内｜灵御开放139.4小时真实双臂操作数据", "date": "2026-11-19", "body": "灵御公开13,263条、共139.4小时的真机示范，使用TA2双臂机器人，通过虚拟现实遥操作同步采集本体第一视角视频、关节状态与动作，覆盖折袜、折毛巾、积木和螺母分类等任务。文件已在官方仓库列出，支持LeRobot数据格式，可供双臂操作学习使用。许可为CC BY-NC-SA 4.0，限定非商业用途；零售场景数据另行申请，不在此次公开包内。", "analysis": "", "sources": [{"label": "官方数据集与文件目录", "url": "https://huggingface.co/datasets/LingYu-Robotics/lingyu-realworld-robotics-dataset"}]}, {"title": "算法研究｜国内｜3DTouch让模型知道“哪里碰到了物体”", "date": "2026-11-18｜预印本补充", "body": "中科大3DTouch把五指触觉的位置、受力方向与场景统一到同一空间坐标，再告诉视觉语言动作模型（VLA）手和物体如何对齐。在UR7e机械臂与XHand上，五项真机任务各测试20次，平均成功率65%，同表最强基线为45%。方法有助于插装、按压等接触操作，但仍依赖相机标定、物体几何及位姿估计，换物体后的适配值得检验。", "analysis": "", "sources": [{"label": "论文原文（预印本）", "url": "https://arxiv.org/html/2611.23961v1"}]}, {"title": "算法研究｜海外｜ForceHarness把力控动作变成通用模型可调用的工具", "date": "2026-11-16｜近期专题·预印本", "body": "新加坡国立大学团队让GPT-6 Astra调用插入、按压等力控片段，底层控制器执行，再把重量、接触高度等信息返回模型。FR3真机六任务各测试10次，完整方案成功54/60次，移除力工具及相关反馈后为2/60次。它展示了工具接口的作用，仍依赖手写动作库与任务提示，秒级模型延迟适合较慢的接触任务。代码已公开，公开版部分接口改动尚待重新进行硬件验证。", "analysis": "", "sources": [{"label": "论文原文（预印本）", "url": "https://arxiv.org/html/2611.21099v1"}, {"label": "作者代码仓库", "url": "https://github.com/showlab/ForceHarness"}]}], "followups": ["全家明年1月启动推广或大晓披露门店运行记录时，复查实际部署数、日常作业时长和远程接管频率。", "CloudRobo-WM1.2计划11月30日开放、ForceHarness更新硬件验证时，检查资源是否可用；3DTouch出现新物体或跨平台结果后，复查适配成本。"], "coverage": "主检索窗口：2026-11-19 10:18至2026-11-20 10:10（UTC+8）；另含11月16—18日未报的重要进展。部分公众号完整原文列表未能取得，覆盖缺口已留存审计。研究3/9；国内6/9。"}, {"date": "2026-11-19", "edition": "9条 · 国内进展7条／海外2条", "updated": "10:18", "intro": "纽娲把社区配送的起步场景从老旧楼梯房转向更适合现阶段技术的高端小区，产品形态随客户反馈重新取舍。数采方面，龙旗补充了量产后的收入占比，智元则用真机实验说明“示范做成功”仍可能遗漏模型需要的信息：评估数据业务，应同时看商业贡献和训练后的任务效果。", "items": [{"title": "产品进展｜国内｜纽娲重新评估轮式配送，先进入合适的小区", "date": "2026-11-18｜创始人采访", "body": "纽娲创始人杨睿刚在雷峰网采访中表示，公司最初瞄准无电梯老旧小区、优先考虑爬楼梯；客户反馈后，开始转向付费意愿更强、环境条件更合适的高端小区，并重新评估轮式底盘。配送需要串起门禁、开门、乘电梯和包裹交接，重防火门也可考虑加装开门器，避免为单个动作不断加重本体。目前公司在少数小区运行，已有项目及概念验证收入。", "analysis": "", "sources": [{"label": "雷峰网原始采访", "url": "https://www.leiphone.com/category/transportation/GLv3yGaPGK64teuS.html"}]}, {"title": "双足人形｜国内｜视比特W1计划年底进入船厂验证", "date": "2026-11-04发布｜11-17现场采访", "body": "长沙晚报走访视比特实验室，披露双足人形焊接机器人W1的后续计划：年底进入船厂，在真实工况中验证。技术负责人介绍，W1面向船舱狭窄、有台阶及工件位置变化的环境，设计上串联自主导航、扫描焊缝、生成轨迹和焊接，并以大小脑分层协调感知规划与执行。记者现场看到的设备仍在测试校准；这一阶段的重点是把移动能力与焊缝操作连成可工作的流程。", "analysis": "", "sources": [{"label": "长沙晚报实验室现场采访", "url": "https://android.icswb.com/h/168/20261117/1004408.html"}]}, {"title": "数据产业｜国内｜龙旗披露数采业务收入占比不超过1%", "date": "2026-11-18", "body": "龙旗科技在第三季度业绩说明会上表示，具身机器人数采设备已实现量产交付，截至10月底，该业务收入占比不超过1%。本次新增的是量产后的收入占比口径，量产本身此前已有披露。它让外界能把机器人新业务放回公司整体业务规模中衡量；不过，收入占比还不能回答具体交付台数、单机售价和利润率，后续财报中的独立业务披露会更有判断价值。", "analysis": "", "sources": [{"label": "第一财经业绩说明会快讯", "url": "https://www.yicai.com/brief/103444842.html"}]}, {"title": "数据与融资｜国内｜柏川完成5000万元Pre-A轮，星海图参与", "date": "2026-11-18", "body": "柏川数据宣布完成5000万元人民币Pre-A轮融资，投资方包括元禾厚望、毅峰资本，以及星海图等两家具身智能产业投资方。公司由汽车数据业务延伸至具身智能，围绕真机遥操和无本体采集，以“山海”平台衔接标注质检、数据管理、评测仿真和真实任务验证。资金将用于具身数据、算法、数据集及场景机器人研发；整机企业参与投资，使数据供给与机器人任务需求的结合更值得跟踪。", "analysis": "", "sources": [{"label": "投资界融资报道", "url": "https://news.pedaily.cn/202611/572047.shtml"}]}, {"title": "场景方案｜国内｜库卡在长沙展示抓取与搬运协同工站", "date": "2026-11-13—15演示｜11-18披露", "body": "库卡移动机器人在长沙现代物流展展示具身自主移动机器人工站：美罗结合三维视觉和力觉识别料箱、托盘，完成柔性抓取与拆码垛；KMP600i/APT负责转运、对接和空托盘回流，由系统调度串联工序。相比只展示一次抓取，这套方案把关注点放在仓储到产线的衔接，包括物料流转及空载具回收。本次披露来自厂商供稿和展会演示，尚未提供客户现场连续运行指标。", "analysis": "", "sources": [{"label": "具身之家完整图文（库卡移动机器人供稿）", "url": "https://www.jushenhome.com/news/2472"}]}, {"title": "供应链｜海外｜微芯介绍48V机器人关节参考设计", "date": "2026-11-17｜近期补充", "body": "Microchip微芯公开面向工业及协作机器人关节的48V参考设计，将氮化镓功率级、数字信号控制器、电机控制、通信和安全接口放在同一开发方案中。阻抗控制可组合位置、速度和力矩指令，以调节关节面对外力时的响应；方案还支持安全扭矩关断、安全抱闸及多种工业通信。它提供的是关节电子与控制部分的开发起点，电机、减速器和整机适配仍需由开发者完成。", "analysis": "", "sources": [{"label": "Microchip微芯官方账号全文", "url": "https://www.eet-china.com/mp/a539879.html"}]}, {"title": "数据研究｜国内｜智元检验：示范成功，为何模型仍学不好", "date": "2026-11-17｜近期预印本补充", "body": "智元Maniformer团队的技术报告检查了本体、遥操和数据质量如何影响学习。一个真机实验让机器人搬运初始视野外的方块：示范加入“先探身看清位置，再选择手臂”后，微调策略的完整搬运成功率由40%升至60%，每组测试30次。关键在于把操作者做决定所依赖的观察也录入数据。这为数采验收增加了具体检查项，而不只是累计成功示范和时长。", "analysis": "", "sources": [{"label": "论文原文（预印本）", "url": "https://arxiv.org/html/2611.22388v1"}]}, {"title": "算法研究｜国内｜InteractVLA让通用模型看懂轨迹并纠偏", "date": "2026-11-17｜近期预印本补充", "body": "中国人民大学与美团研究者提出InteractVLA：通用模型给视觉语言动作模型（VLA）指定末端位置、姿态和夹爪状态，再根据轨迹及相机投影纠偏，连续动作仍由VLA生成。Dexmal真机倒水测试中，各方法评估30次，相比只用语言调用VLA，任务评分由38.5升至79.2。这个分数不是成功率；研究的实质是让高层规划能更具体地干预操作过程。", "analysis": "", "sources": [{"label": "论文原文（预印本）", "url": "https://arxiv.org/html/2611.22584v1"}]}, {"title": "采集研究｜海外｜HandUMI用手戴夹爪记录双手操作", "date": "2026-11-17｜近期预印本补充", "body": "HandUMI让采集者戴着平行夹爪直接操作物品，通过可换指尖匹配机器人夹爪，并用头显控制器记录运动，采集现场无需摆放机器人。研究用562条示范训练动作模仿策略，在PiPER双臂真机叠毛巾测试中成功12次、共20次。软件已公开，包含标定、质检和动作重定向；七类机械臂的迁移展示属于仿真，真机结果目前集中于这一折叠任务。", "analysis": "", "sources": [{"label": "论文原文（预印本）", "url": "https://arxiv.org/html/2611.22146v1"}, {"label": "作者软件仓库", "url": "https://github.com/murobotics-ai/handumi-sw"}]}], "followups": ["纽娲公布新增小区或W1年底进入船厂时，复查现场改造量、实际任务流程和人工接管；库卡出现客户连续运行数据后，再核对工站节拍。", "龙旗下次财报披露数采收入、客户或台数时复查商业贡献；智元、HandUMI出现更多任务及独立复现后，比较相同采集预算下的真实训练收益。"], "coverage": "检索窗口：2026-11-18 10:15至2026-11-19 10:18（UTC+8）；含11月17日采访、参考设计与研究补充，以及13—15日展会后续报道。W1发布于11月4日，新增为17日现场采访和年底入厂计划。研究3/9，国内进展含库卡中国长沙展示。"}, {"date": "2026-11-18", "edition": "8条 · 国内6条／海外2条", "updated": "10:15", "intro": "Mantis Ultra把新品升级集中在负载、腰部旋转与换电，XHAND 1 Pro-U则围绕人手数据采集调整结构并开放订购：本体作业能力与训练数据接口都出现了具体产品变化。XHAND与Genesis采用人机手部结构对应，BWM-Forge尝试复用场景程序；本期共同指向如何减少数据转换和重复制作工作，实际训练收益仍需分别验证。", "items": [{"title": "新品｜国内｜Mantis Ultra增加自主换电，单臂最大负载15公斤", "date": "2026-11-17｜报道日期", "body": "蓝虫具身最新旗舰Mantis Ultra沿用轮式双臂架构。机器人大讲堂完整图文披露，新型号单臂末端最大负载15公斤，新增腰部旋转、四全向轮毂电机、双电池自主换电与腕部快换接口，面向工业操作及定制科研。大臂电机集中布置在胸部，以降低手臂末端惯量。这一组合把升级重点放在重载操作、工位覆盖和连续作业配置，Ultra售价及供货时间尚未公布。", "analysis": "", "sources": [{"label": "机器人大讲堂完整图文", "url": "https://www.leaderobot.com/news/10831"}]}, {"title": "新品｜国内｜XHAND 1 Pro-U开放订购，适配人手操作数据采集", "date": "2026-11-16（近期补充）", "body": "星动纪元宣布16自由度XHAND 1 Pro-U商业发布，开放订购，首批计划限量供应40只。新型号与英伟达GEAR实验室DexUMI外骨骼的关节结构对应，并调整拇指位置、掌部触觉和关节活动方式。采集时，人戴着外骨骼直接操作实物，记录手部运动与指尖力，再用于GR00T 2训练；设计重点是减少人手动作向机器人手映射时的信息损失。", "analysis": "", "sources": [{"label": "星动纪元官方发布（美通社）", "url": "https://www.prnewswire.com/news-releases/robotera-launches-xhand-1-pro-u-featured-in-nvidias-gr00t-2-dexumi-demonstration-302940288.html"}]}, {"title": "供应链｜国内｜英孚推出51毫米轴向高度的内嵌式摆线关节", "date": "2026-11-17", "body": "英孚机器人供稿披露，新模组将电机与摆线减速器紧密集成，轴向高度51毫米，目标是承载15—20公斤负载的中型四足机器人。它采用壳体散热槽、驱动器件导热路径等被动散热设计，并预留液冷替换方案。作为足式机器人执行器的新方案，变化集中在减速器、电机与散热的整体布局；目前披露的应用对象是四足，未见人形机器人采用信息。", "analysis": "", "sources": [{"label": "具身之家图文（英孚机器人供稿）", "url": "https://www.jushenhome.com/news/2448"}]}, {"title": "融资｜国内｜蓝点触控完成数亿元D3轮融资", "date": "2026-11-17", "body": "第一财经原始采访报道，机器人力传感器企业蓝点触控宣布完成数亿元人民币D3轮融资，半年累计融资已超过10亿元。创始人刘吴月表示，地方产业投资方更看重产品落地空间及产业协同。力传感器把腕、踝和关节受到的接触力转为控制反馈，是精细装配、抓取和接触操作的重要输入。这笔融资使上游感知部件成为本期除整机新品外的另一项产业进展。", "analysis": "", "sources": [{"label": "第一财经原创采访", "url": "https://www.yicai.com/news/103443693.html"}]}, {"title": "双足人形｜海外｜Atlas新增格芯客户，计划明年初现场测试", "date": "2026-11-17", "body": "波士顿动力与GlobalFoundries（格芯）扩大合作，格芯成为Atlas首个非汽车行业早期客户，计划2027年初开始现场测试，评估具体用例、系统集成和技能训练。双方同时扩大Spot在美国、德国、新加坡工厂的巡检合作。此次Atlas的增量是试点场景从汽车制造延伸至半导体制造；已运行的Spot与尚待测试的Atlas处于不同阶段，不能用前者成绩代替后者验证。", "analysis": "", "sources": [{"label": "波士顿动力官方公告", "url": "https://bostondynamics.com/news/boston-dynamics-globalfoundries-expand-robotics-collaboration/"}]}, {"title": "融资与数据｜海外｜Genesis AI获5亿美元，扩展操作数据采集", "date": "2026-11-17", "body": "Genesis AI宣布完成5亿美元A轮融资，投后估值35亿美元，由Premji Invest、Khosla Ventures和Eclipse共同领投。公司计划扩展数据采集、模型训练及Eno客户部署，其采集路线强调人手、数据手套、机器人手的结构对应：工人在正常操作时佩戴手套，记录的数据用于机器人学习，并结合仿真训练。与XHAND新品对照，人机手部结构匹配正成为降低数据转换难度的一条具体路线。", "analysis": "", "sources": [{"label": "Genesis AI官方发布（美通社）", "url": "https://www.prnewswire.com/news-releases/genesis-ai-raises-500m-series-a-at-3-5b-valuation-to-master-human-level-dexterity-in-general-purpose-robots-and-deploy-at-scale-302941249.html"}]}, {"title": "算法研究｜国内｜ScaleVLA：用大模型表征学习连续动作", "date": "2026-11-17（UTC+8）", "body": "清华、北大、上海交大与银河通用研究者提出ScaleVLA：冻结大规模视觉语言骨干，训练动作生成部分，从图像和指令的内部表征直接输出连续动作，省去每步生成推理文字。预印本中，真机插充电器在10个参考起点成功9次，π0.5加动作头对照为8次。结果提示大模型知识可用于底层操作，但测试规模仍小，推理使用4张H200，工程取舍需同时考虑算力成本。", "analysis": "", "sources": [{"label": "论文原文（预印本）", "url": "https://arxiv.org/html/2611.21607v1"}]}, {"title": "数据研究｜国内｜BWM-Forge：先编程搭场景，再生成机器人视频", "date": "2026-11-12（近期研究补充）", "body": "同济大学与考拉悠然的BWM-Forge，让智能体先编写Blender场景程序，明确物体位置、机器人动作和相机，再渲染结构视频，由视频模型补充材质与光影。这样可以改变场景外观、拍摄角度并复用动作，减少每次从头制作数据的工作。项目已公开代码；论文在15项任务、5类机器人上评估视频质量与指令一致性，尚未证明生成视频能提高机器人策略的训练效果。", "analysis": "", "sources": [{"label": "论文原文（预印本）", "url": "https://arxiv.org/html/2611.16221v1"}, {"label": "作者代码仓库", "url": "https://github.com/Lcixs/BWM-Forge"}]}], "followups": ["Mantis Ultra公布售价、供货安排，或XHAND首批客户收货后，复查实际配置与商业可用性。", "Atlas现场测试启动后核对具体工序；BWM-Forge公布下游策略训练结果时，再评估合成视频是否带来可量化收益。"], "coverage": "窗口：2026-11-17 10:33至2026-11-18 10:15（UTC+8）；含11月16日新品与11月12日研究补充。研究2/8，国内6/8。"}, {"date": "2026-11-17", "edition": "7条 · 国内5条／海外2条 · 延迟发送", "updated": "10:33", "intro": "Beni把地面跟拍机器人带进线下体验店，IRON则把门店试用列入明年计划：产品比较需要分别看当前可用体验和下一阶段验证。蔚建的工人操作门槛、RealBOT的远程介入方案共同提示，部署评估应把易用性和异常处理纳入成本，而不只看动作演示；这是本期证据支持的编辑判断。", "items": [{"title": "新品｜国内｜Beni进入线下零售，地面跟拍4999元起", "date": "2026-11-14｜近期补充", "body": "妙动科技的双轮足跟拍机器人Beni在深圳INNO100举行线下首发，标准套装4999元、探索套装5799元，可现场体验购买；此前已于11月10日开启全球现货销售。产品面向运动、亲子和宠物拍摄，支持后方、平行与环绕跟拍及跌倒起身。这次变化是从线上视频展示进入线下体验，用户可以直接检查跟随、构图和恢复动作是否满足自己的拍摄习惯。", "analysis": "", "sources": [{"label": "雷峰网完整图文", "url": "https://www.leiphone.com/category/weiwu/nFSVApZT1GmSFH9T.html"}]}, {"title": "双足人形｜国内｜小鹏明确IRON门店试用和外部发布节奏", "date": "2026-11-16", "body": "何小鹏在第三季度财报电话会上表示，计划2027年第一季度让首批量产机器人进入部分小鹏门店试用，第二季度面向外部商业客户正式发布IRON。最新版本将在接下来的科技日和广州车展亮相，并强调多人识别与身份记忆。门店试用将成为观察交互能力的具体入口：不仅要认出人，还要在多轮服务中正确使用记忆；目前仍是计划，尚非外部交付。", "analysis": "", "sources": [{"label": "IT之家转述电话会", "url": "https://www.ithome.com/1/027/964.htm"}]}, {"title": "落地｜国内｜RealBOT进入爱安特常州产线", "date": "2026-11-16", "body": "睿尔曼与爱安特（常州）精密机械签署合作。企业供稿称，RealBOT轮式人形机器人已在爱安特真实产线承担上下料、物料转运，并将作业数据用于模型迭代。方案采用自主作业与远程人工介入的组合，而非完全无人值守。相比单次展台演示，这次给出了具体客户和工序；经济性仍要看接管频次、持续运行时间与产线节拍的匹配。", "analysis": "", "sources": [{"label": "量子位图文（睿尔曼供稿）", "url": "https://www.qbitai.com/2026/11/510542.html"}]}, {"title": "融资｜国内｜蔚建获超亿元投资，补施工机器人的易用性", "date": "2026-11-15｜近期补充", "body": "硬氪采访披露，蔚建科技完成第五轮超亿元融资，投资方为财通资本，资金用于制造、海外拓展及产品和具身研发。公司已有抹灰、喷涂等产品，“天工”系统分别处理运动工艺与环境理解。创始人指出，现场工人输入坐标、设置参数的门槛阻碍推广，转向具身的重要目的就是降低使用难度。这为产品迭代提出了具体问题：已有施工能力，怎样才能让普通工人用起来。", "analysis": "", "sources": [{"label": "硬氪原创采访及产品图", "url": "https://www.36kr.com/p/4070571639067782?f=rss"}]}, {"title": "模型研究｜国内｜华为云WM1.2正式发布，连接世界理解与动作生成", "date": "2026-11-16", "body": "华为云发布昇腾原生具身世界模型CloudRobo-WM1.2，并宣布开源模型及配套训练框架。发布介绍把环境预测与动作生成结合起来，提供可按算力和响应需求组合的推理模式，让模型既判断环境如何变化，也生成下一步动作。第一财经同时报道，华为云与福龙马合作的新一代清扫机器人启动预售。本次尚未核实WM1.2权重及许可证的实际下载入口，宣布开源与可直接复用仍需区分。", "analysis": "", "sources": [{"label": "IT之家发布会图文", "url": "https://www.ithome.com/1/027/684.htm"}, {"label": "第一财经报道", "url": "https://www.yicai.com/news/103442130.html"}]}, {"title": "数据工具｜海外｜下载前先检查机器人数据是否齐全", "date": "2026-11-16｜社区介绍", "body": "开发者公开介绍phys-ai-dataprofiler，帮助团队在下载大体量数据前检查相机流、采样频率、时间间隙和文件完整性。它只读取必要的文件头与索引，支持ROS记录和LeRobot等格式，还可按需求输出通过、失败或未知。作者示例中，检查5.8GB记录仅读取533KB，代码采用MIT许可。这适合数据采购或训练前的结构筛查，但不分析视频画面，不能代替对动作示范质量的检查。", "analysis": "", "sources": [{"label": "作者代码及说明", "url": "https://github.com/akrishni/phys-ai-dataprofiler"}]}, {"title": "算法研究｜海外｜PEAR让推理模型在仿真中练习操作，再迁移真机", "date": "2026-11-14（UTC+8）｜近期研究", "body": "MIT等团队发布预印本，通过纯仿真强化学习训练27B推理模型，让它看图、推理并给出机械臂下一步末端位姿。在未见过的双臂YAM真机上，两项与仿真训练对应的任务共30次试验成功18次，原模型为0次。增量是把操作能力纳入推理模型后训练，不必先采集这些任务的真机示范。不过，完整RoboDojo测试540次仅成功21次，长任务常耗尽上下文；局部迁移进展尚不能外推为通用操作能力。", "analysis": "", "sources": [{"label": "论文全文与逐次实验表", "url": "https://arxiv.org/html/2611.18562v1"}]}], "followups": ["IRON新版亮相及门店试用时，复查交互流程、实际售价和客户交付条件；RealBOT出现买方反馈时，补接管率与持续运行时间。", "WM1.2实际开放下载后核对权重、代码和许可；PEAR若开放复现资源，优先复测更长任务、单任务耗时与推理成本。"], "coverage": "检索窗口：2026-11-16 11:38至2026-11-17 10:33（UTC+8）；另含标明日期的近期补充。部分公众号与原始入口覆盖仍有缺口。"}, {"date": "2026-11-16", "edition": "9条 · 新品产业6条／研究3条 · 延迟发送", "updated": "11:38", "intro": "本期重点是新品如何进入具体工位：华硕披露包装机器人路线，步科更新关节电机系列；国内服务侧则出现展演模板复用、机器人集群履约和物流现场数据回流。交互研究也开始把说话、表情与指向动作一起建模，值得与单纯语音问答功能区分。", "items": [{"title": "新品｜中国台湾｜华硕披露Gallop工厂机器人路线", "date": "2026-11-13", "body": "华硕披露Gallop当前以固定底座双臂在自家主板附件包装工位测试，轮式版本仍在规划。任务涉及15种小零件和透明包装袋，训练结合人类第一视角演示、仿真与遥操作，算力采用Jetson AGX Thor。公司把99.5%准确率、20秒节拍设为目标，并计划2027年试点、2028年下半年供应。这条路线从现有工位要求定义产品，当前尚处测试阶段。", "analysis": "", "sources": [{"label": "华硕官方（含图与视频）", "url": "https://press.asus.com/blog/factory-proven-physical-ai-asus-gallop-humanoid-robot"}]}, {"title": "供应链｜国内｜步科发布FMH无框力矩电机", "date": "2026-11-12｜近期补充", "body": "步科发布新一代FMH无框力矩电机，采用大中空设计，官方规格图给出38—120毫米外径范围，面向腕、肘、腰、髋、膝、踝等关节。对整机开发而言，同一产品家族覆盖不同关节尺寸，有助于统一选型与集成思路；下一步值得看实际关节模组中的热表现与安装适配。", "analysis": "", "sources": [{"label": "步科官方新品", "url": "https://www.kinco.cn/news/New%20product/179"}]}, {"title": "新功能｜国内｜慧思开物把展演做成可分发模板", "date": "2026-11-11｜近期补充", "body": "北京人形为慧思开物应用商店新增固定点位展演流程。输入文本后，系统从动作库匹配、组合动作，与语音及配乐同步；运营人员可以拖拽编排、保存复制模板，再公开或私密分发并遥控触发。已在4S店交车仪式和展厅开展应用探索，变化是把一次性脚本做成可重复分发的整套内容，减少每家门店重新编排的工作。", "analysis": "", "sources": [{"label": "北京人形官方", "url": "https://www.x-humanoid.com/news-view-364.html"}]}, {"title": "融资与服务｜国内｜擎天租完成数亿元融资并升级服务模式", "date": "2026-11-13", "body": "新京报报道，擎天租完成数亿元战略融资交割，和达投资、芒果产业投资方厚为资本、中联即送等参投。公司同时由机器人租赁转向“机器人生产力服务”，从设备对接延伸至任务组织、集群调度、本地部署和持续运营。资金用于应用研发、Worken实训体系与履约网络，投资方还将带入演艺内容、末端配送及园区场景。", "analysis": "", "sources": [{"label": "新京报", "url": "https://www.bjnews.com.cn/detail/1794542845129362.html"}]}, {"title": "落地｜国内｜昆腾动力披露双十一物流作业进展", "date": "2026-11-12｜近期补充", "body": "昆腾动力披露，其机器人首次参与菜鸟供应链双十一作业，并在称重量方、分拣供包、固定拣选等岗位形成跨仓复制和客户复购。公司称累计获得近5000台批量订单，这一数字对应订单而非实际交付。现场失败、人工介入和恢复记录回流训练，使业务部署同时成为数据来源；公司另计划12月底发布新构型产品。", "analysis": "", "sources": [{"label": "凤凰网（公司披露）", "url": "https://news.ifeng.com/c/8xzqaxr0Hss"}]}, {"title": "商业部署｜海外｜GXO与Apptronik扩大Apollo试验", "date": "2026-11-12｜近期补充", "body": "GXO与Apptronik签署意向书，将从2027年扩大Apollo仓内试验，覆盖拣选、箱筐搬运、包装与分拣。双方计划在未来四年推进最多1000台全球部署，北美首批计划在2027年底，前提是达到约定的安全、性能和运营指标。预期采用机器人即服务模式，这为双足人形进入物流提供了客户侧路线，但尚非确定采购订单。", "analysis": "", "sources": [{"label": "Forbes报道／Yahoo转载", "url": "https://finance.yahoo.com/technology/ai/articles/gxo-doubles-down-humanoids-plan-125439517.html"}]}, {"title": "交互研究｜国内｜XBot-Omni让语音与身体表达同步", "date": "2026-11-13（UTC+8）｜近期补充", "body": "智元AGIBOT X-Lab发布XBot-Omni预印本，把音视频理解、语音生成与身体表达连接起来：动作模块共享对话和语音模块的内部状态，让指向动作、表情与说到的内容对齐。论文在PrimeBOT Q1和AGIBOT X2展示协调表达、方向手势和看物指物。它解决的是机器人交流时“说什么、指哪里、何时动”的配合问题，适合关注导览和面对面互动的团队。", "analysis": "", "sources": [{"label": "arXiv论文全文", "url": "https://arxiv.org/html/2611.17160v1"}]}, {"title": "数据研究｜Ropedia Xperience 2连接场景扫描与第一视角行为", "date": "2026-11-13（UTC+8）｜近期补充", "body": "Ropedia Xperience 2把激光雷达场景扫描与人类第一视角行为结合，为空间理解、仿真和动作迁移提供数据。预印本介绍的完整研究覆盖131小时行为记录；Hugging Face当前首批开放126个场景，暂不含行为录制与场景扫描的配准文件。数据采用非商业许可，商业使用需另行授权，因此评估接入时应以首批文件和许可为准。", "analysis": "", "sources": [{"label": "项目演示", "url": "https://ropedia.com/xperience/2-research/"}, {"label": "数据集与许可", "url": "https://huggingface.co/datasets/ropedia-ai/Ropedia-Xperience-2"}]}, {"title": "运动控制研究｜BlinkMimic压缩人形动作跟踪训练时间", "date": "2026-11-12｜近期补充", "body": "BlinkMimic预印本通过随训练进度减小优化步长、集中重练失败状态及GPU计算优化，缩短人形动作跟踪策略训练时间。在模拟G1和40段LAFAN1动作上，单张RTX 4090平均约3.4分钟达到作者指定的稳定跟踪阈值，统计来自三个随机种子。代码与逐次结果已公开，可用于更快迭代动作策略；目前结果限于该仿真动作集。", "analysis": "", "sources": [{"label": "arXiv论文", "url": "https://arxiv.org/abs/2611.16422"}, {"label": "作者代码", "url": "https://github.com/fuyichen0725/blinkmimic"}]}], "followups": ["华为云预告今天14:00—15:30发布CloudRobo WM1.2，本期截止尚未举行；下期核对实际产品能力、开发者接口和合作名单。", "昆腾计划12月底发布新构型，届时复核实物、规格、价格与交付安排；GXO试验进入下一阶段时核对客户侧运营指标。", "Ropedia后续批次和配准文件上线后，再评估数据能否直接用于动作迁移。"], "coverage": "检索窗口为11月13日10:25至11月16日11:38（UTC+8），覆盖周末；窗口之前尚未报过的重要进展标为近期补充。"}, {"date": "2026-11-13", "edition": "7条 · 国内4条／海外2条／近7日研究1条 · 延迟发送至小群", "updated": "12:55", "intro": "国内进展集中在芯片研发投入、物流运营和消费端兴趣，几者分别对应不同商业化阶段，不能混为整机规模交付。海外保留Agile Robots融资扩产和Google DeepMind新模型工厂试点；研究侧补入一篇近7日全身控制工作。", "items": [{"title": "国内融资｜曦选创智完成5亿元天使轮，机器人端侧芯片仍在研发规划", "date": "2026-11-12", "body": "中国证券报援引优必选披露，曦选创智完成5亿元人民币天使轮，投后估值40亿元。公司计划开发机器人大小脑一体SoC，目标是2027年提供开发验证平台、2028年推出首款芯片及方案。目前属于研发规划，尚无芯片性能、客户验证或量产供货信息。", "analysis": "若时间表兑现，机器人端侧算力将成为产业链新的投入方向。", "sources": [{"label": "中国证券报", "url": "https://www.cs.com.cn/ssgs/01/2026/11/12/detail_2026111210051774.html"}]}, {"title": "国内落地｜星动纪元分拣机器人进入邮政、顺丰十余个物流中心", "date": "2026-11-12", "body": "界面新闻报道，星动纪元具身分拣机器人已在中国邮政、顺丰集团十余个物流中心投入运营。公司称现场峰值达到每小时1500件；初入产线时约为800至900件，经采集一线操作数据并迭代模型后有所提升。峰值数据未说明持续时长、平均效率和人工干预情况。", "analysis": "这提供了从实验室指标走向物流现场运营的具体案例，后续要看高峰节拍能否变成稳定日均产出。", "sources": [{"label": "界面新闻", "url": "https://m.jiemian.com/article/15324897.html"}]}, {"title": "国内市场｜京东双十一人形机器人销量同比增长，松延小布米Lite定价9998元", "date": "2026-11-13", "body": "财联社报道，京东智能人形机器人品类销量同比增长700%；松延动力在10月9日至11月11日的品类销量和销售额均列第一，公司称小布米Lite销量较上一周期增长142.3%。该机标价9998元，订单仍在交付。平台未披露绝对销量，增长率和排名也不能说明长期使用与退货情况。", "analysis": "万元以内价格让消费级双足机器人出现了更明确的市场信号，后续需看交付和用户持续使用。", "sources": [{"label": "财联社（东方财富转载）", "url": "https://finance.eastmoney.com/a/202611133930451931.html"}]}, {"title": "国内融资与供应链｜纬钛机器人完成A轮融资，视触觉方案进入精密装配场景", "date": "2026-11-12", "body": "投资界报道纬钛机器人完成A轮融资，由中车资本、永鑫方舟联合领投，金额未披露。报道还称其视触觉方案已用于小米手机产线精密零部件装配，并经历500万次压力循环测试；相关产线与测试信息来自公司披露。", "analysis": "融资显示资本继续关注触觉供应链；更关键的是后续能否形成可复制的客户交付和机器人场景适配。", "sources": [{"label": "投资界", "url": "https://news.pedaily.cn/202611/571744.shtml"}]}, {"title": "海外融资与扩产｜Agile Robots完成5亿美元F轮融资", "date": "2026-11-12", "body": "Agile Robots宣布完成5亿美元F轮融资，投后估值85亿美元，SoftBank领投，NVIDIA、Hitachi等参与。公司称资金将用于美国业务扩张、德国扩产和进入新市场；德国新厂规划年产能上限为1万台腿式与轮式人形机器人。公司公布的全球部署2万套包含多类工业机器人解决方案，并非人形机器人交付量。", "analysis": "融资规模突出，扩产计划仍需后续订单和产能利用率验证。", "sources": [{"label": "Agile Robots官方公告", "url": "https://www.agile-robots.com/en/news/detail/physical-ai-leader-agile-robots-raises-500-million-series-f-funding/"}]}, {"title": "海外新品与工厂试点｜Google DeepMind发布Gemini Robotics 2.5", "date": "2026-11-10（近期新品补充）", "body": "Google DeepMind于11月10日发布Gemini Robotics 2.5，并称模型在200多项任务中较前代提升成功率、缩短耗时。公告还介绍与Apptronik、奔驰在匈牙利和德国工厂开展概念验证：Apollo 2执行汽车零件拣选与套件分拣，披露成功率96%。目前没有公开试点规模、持续时长和人工接管数据。", "analysis": "模型新品与真实工厂任务结合值得关注，但概念验证还不能说明已进入产线常态运行。", "sources": [{"label": "Google DeepMind官方公告", "url": "https://deepmind.google/blog/gemini-robotics-2-5-accelerates-real-world-physical-intelligence/"}]}, {"title": "近7日研究｜DKWBC将动作跟踪与平衡控制拆开学习", "date": "2026-11-06（arXiv预印本）", "body": "论文把机器人动力学模型算出的基础跟踪力矩，与学习策略补上的平衡修正分开，降低同一策略同时追动作、抗扰动的难度。作者在Unitree G1真机展示负载下深蹲和行走；仿真中对217段动作施加手部外力，最高强度下上身跟踪误差为24.68毫米、成功率99.54%。", "analysis": "该思路有助于把模仿动作和抗扰控制分别优化；真机材料仍是展示性验证，没有大规模重复测试统计，且结果不等同于日常任务能力。", "sources": [{"label": "arXiv论文", "url": "https://arxiv.org/abs/2611.09605"}]}], "followups": ["曦选创智后续公布芯片架构、验证平台或客户测试时，核对研发计划兑现情况。", "星动纪元披露物流中心运行时长、日均处理量和人工介入后，复核1500件/小时峰值能否转化为稳定节拍；松延动力出现交付和用户数据后，再判断低价产品的持续需求。", "Agile Robots公布新厂建设、实际产能或订单，或Gemini Robotics 2.5试点进入常态化应用时，复查两项海外进展的兑现程度。", "DKWBC代码或更完整真机重复测试公开后，复查其跨动作和抗扰能力是否可复现。"], "coverage": "检索窗口从2026-11-12 10:25至2026-11-13 10:25（UTC+8）；Gemini Robotics 2.5于11月10日发布，作为近期新品补充，标注真实日期。飞书消息延迟，先发3人小群。"}, {"date": "2026-11-12", "edition": "8条 · 国内6条／海外2条 · 产业与新品优先", "updated": "10:25", "intro": "国内新品、订单、政策和供应链证据构成本期主线；新品发布、订单、首台发出和模组出货分别说明，不合并成规模交付。海外保留移动安防新品与一项明确标注为内部仿真的模型评测。", "items": [{"title": "第五代贡嘎人形机器人发布，能力差异待任务验证", "date": "2026-11-11", "body": "盖世汽车报道第五代贡嘎人形机器人正式发布，介绍了具身系统、记忆规划及世界模型等能力。 新一代本体发布应作为独立产品进展跟踪。判断其相较前代的实质变化，需要把能力描述落到具体任务、失败恢复和连续运行表现上。 局限：现有能力描述来自发布方及报道，资料未提供独立基准、完整规格或规模化用户部署数据，不能据此判断其领先程度。", "analysis": "新一代本体发布应作为独立产品进展跟踪。判断其相较前代的实质变化，需要把能力描述落到具体任务、失败恢复和连续运行表现上。", "sources": [{"label": "来源1", "url": "https://www.gasgoo.com/robot/news/70477622-%E7%AC%AC%E4%BA%94%E4%BB%A3%E8%B4%A1%E5%98%8E%E4%BA%BA%E5%BD%A2%E6%9C%BA%E5%99%A8%E4%BA%BA%E6%AD%A3%E5%BC%8F%E5%8F%91%E5%B8%83/"}]}, {"title": "优必选与永达签署400台U1 Pro采购订单", "date": "2026-11-11", "body": "新浪财经报道，双方签订首批400台U1 Pro采购订单，计划年底交付，应用设想包括汽车展厅导览、销售和客服。 若按期落地，这批订单将为人形机器人进入汽车零售服务场景提供较大批量的验证机会。关键不只是机器人到店，还包括能否完成真实服务流程、遇到异常时如何转人工。 局限：当前阶段是采购订单及计划交付，不是400台已交付，也没有稳定运营、接管率或服务效果数据。", "analysis": "若按期落地，这批订单将为人形机器人进入汽车零售服务场景提供较大批量的验证机会。关键不只是机器人到店，还包括能否完成真实服务流程、遇到异常时如何转人工。", "sources": [{"label": "来源1", "url": "https://www.yicai.com/brief/103436827.html"}]}, {"title": "均胜电子首台机器人高算力背包交付宇树", "date": "2026-11-11", "body": "盖世具身智能报道，均胜电子首台机器人高算力背包已交付宇树；报道还称均胜的高算力控制器累计向一家未具名头部机器人公司交付超2,000套、峰值算力2,070 TOPS，但未说明是否与此次背包为同一产品或同一客户。外置计算可能缓解本体内部空间与散热约束，但也可能增加重量、供电和连接管理负担，价值应结合整机任务评估。局限：这次背包仍是首台交付，不等于该背包已批量供货或客户验收。报道中的2,000套和2,070 TOPS属于另一项未具名控制器信息；背包本身的芯片型号、算力、功耗、电池容量及后续订单规模尚未披露。", "analysis": "外置计算可能缓解本体内部空间与散热约束，但也可能增加重量、供电和连接管理负担，价值应结合整机任务评估。", "sources": [{"label": "来源1", "url": "https://www.gasgoo.com/apps/e060bad9eca91db7f01403fc7120041f/robot/news/70477653-%E5%9D%87%E8%83%9C%E7%BB%99%E5%AE%87%E6%A0%91%E5%81%9A%E4%BA%86%E4%B8%AA-%E8%83%8C%E5%8C%85-%E9%87%8C%E9%9D%A2%E8%A3%85%E7%9D%80%E6%9C%BA%E5%99%A8%E4%BA%BA%E7%9A%84-%E5%A4%A7%E8%84%91/"}]}, {"title": "禾赛披露Q3执行器模组出货23,405套", "date": "2026-11-10｜补充窗口", "body": "禾赛未经审计的第三季度业绩披露，机器人执行器模组出货23,405套，环比增长97%；前三季度累计35,295套，月产能达到10,000套。公司称全身模组与灵巧手模组均进入量产，并预计2027年年出货达到六位数。 相较笼统的合作或扩产表述，这些数据提供了更具体的上游出货信号，后续可结合收入贡献和客户结构判断增长质量。 局限：数据及预测均为公司披露；模组套数不是机器人销量，月产能不是实际月出货，2027年数字仍属预测。", "analysis": "相较笼统的合作或扩产表述，这些数据提供了更具体的上游出货信号，后续可结合收入贡献和客户结构判断增长质量。", "sources": [{"label": "SEC备案：禾赛6-K Exhibit 99.1（HTML）", "url": "https://www.sec.gov/Archives/edgar/data/1861737/000110465926125142/tm2629463d1_ex99-1.htm"}, {"label": "港交所：未经审计Q3业绩公告（PDF）", "url": "https://www1.hkexnews.hk/listedco/listconews/sehk/2026/1110/2026111001053.pdf"}]}, {"title": "RoboCap-LiDAR-100公开首批操作数据，复用条件仍待确认", "date": "2026-11-11", "body": "盖世汽车报道，速腾聚创与BitRobot合作发布RoboCap-LiDAR-100，拟总规模100小时；首批为50小时、1,964段、37类任务，包含激光雷达深度、RGB图像与惯性测量单元（IMU）等数据。 多模态深度信息可为操作训练补充空间结构线索，但能否直接用于研发，取决于任务分布、标注质量和传感器同步情况。 局限：第二批仍属计划，不能将100小时写成已全部公开；数据卡、许可及实际可下载性需进一步核验。本条按数据基础设施进展编排，不视为已验证的算法突破。", "analysis": "多模态深度信息可为操作训练补充空间结构线索，但能否直接用于研发，取决于任务分布、标注质量和传感器同步情况。", "sources": [{"label": "来源1", "url": "https://www.gasgoo.com/apps/e060bad9eca91db7f01403fc7120041f/robot/news/70477668-%E9%80%9F%E8%85%BE%E8%81%9A%E5%88%9B%E4%B8%8Ebitrobot%E8%BE%BE%E6%88%90%E6%88%98%E7%95%A5%E5%90%88%E4%BD%9C/"}]}, {"title": "北京发布2026—2028年人形机器人行动计划", "date": "2026-11-11", "body": "北京市经信局发布行动计划，提出到2028年培育不少于5家国际领先、10家国内领先整机企业，并提出京津冀产能占全国25%、零部件本地配套率超过60%等目标。 政策将整机企业培育、区域产能和本地供应链配套列为明确指标，后续应关注实施措施及项目兑现情况，而非只看目标规模。 局限：上述均为政策目标，不是当前企业数量、已建产能或已实现配套率。", "analysis": "政策将整机企业培育、区域产能和本地供应链配套列为明确指标，后续应关注实施措施及项目兑现情况，而非只看目标规模。", "sources": [{"label": "来源1", "url": "https://jxj.beijing.gov.cn/zwgk/2024zcwj/202611/t20261111_4941527.html"}]}, {"title": "Ring推出Rover Cam，移动安防延伸至巡逻与告警响应", "date": "2026-11-10｜补充窗口", "body": "Amazon宣布Ring Robotics产品，其中Rover Cam面向商用安防，宣称可自主巡逻、响应告警并提供最高4K视频。美国计划于2026年12月16日发货，售价999.99美元。 相比固定摄像头，移动平台增加了主动巡检与告警联动能力，实际价值取决于复杂环境通行、异常恢复和隐私体验。 局限：这是轮式安防机器人，不是人形机器人；自主能力为官方描述，发货日期是计划，资料未提供真实部署的可靠性数据。", "analysis": "相比固定摄像头，移动平台增加了主动巡检与告警联动能力，实际价值取决于复杂环境通行、异常恢复和隐私体验。", "sources": [{"label": "来源1", "url": "https://www.aboutamazon.com/news/devices/ring-drone-cam-rover-cam-security-robot"}]}, {"title": "Claude Fable 5.2内部仿真得分提升，尚不能外推真机", "date": "2026-11-09｜主窗口外研究补充", "body": "Anthropic公布内部RoboDojo Sim评测：Fable 5.2在最高可用推理强度下得分64.9%，Fable 5.1为27.6%，GPT-6 Astra为29.8%。 该评测用模拟双臂操作任务观察通用模型的任务表现，而非直接验证实体机器人。它提供了模型参与操作任务的进展信号，可能对任务规划或操作系统研发有参考价值，但具体动作接口与模型角色尚不明确。 局限：这是厂商内部仿真评测，不是真机部署。资料未提供样本量、耗时、人工介入及成本；跨厂商设置的可比性有限，不能据此形成真实机器人能力排名。", "analysis": "该评测用模拟双臂操作任务观察通用模型的任务表现，而非直接验证实体机器人。它提供了模型参与操作任务的进展信号，可能对任务规划或操作系统研发有参考价值，但具体动作接口与模型角色尚不明确。", "sources": [{"label": "来源1", "url": "https://www.anthropic.com/claude-fable-and-mythos-5-2"}]}], "followups": ["在年底交付节点复核U1 Pro实际交付数量、买方确认及门店运营、接管情况。", "出现验收或财报更新时，复查算力背包供货、执行器收入贡献以及RoboCap数据下载和许可。", "贡嘎完整演示、Ring Rover发货或RoboDojo真机评测出现时，检查连续运行、失败恢复、人工接管与成本。"]}, {"date": "2026-11-11", "edition": "8条 · 国内产业/技术优先5条／海外1条／研究3条", "updated": "10:25", "intro": "国内新品、触觉数据开放、精密制造融资与酒店服务试点是本期主线；海外保留Gemini Robotics 2.5在汽车零件拣选上的概念验证。研究侧关注人机交互和失败恢复，证据仍处实验或预印本阶段。", "items": [{"title": "蚂蚁灵波开源触觉基础模型LingBot-Touch", "date": "2026-11-10", "body": "官方技术页称预训练数据共4,983小时、464,431段交互、约13.3亿帧，覆盖压阻、磁触觉、视触觉。；官方称在Sharpa Wave、XHand两款灵巧手上做26项真机任务，每项20次试验；模型使用冻结触觉特征接入后训练策略。；官方GitHub已提供推理代码及Tiny/Small模型下载入口；新传感器仍需几何校准及数据适配。 局限：数据量、任务效果来自公司团队自报；独立复现未见。该项目是触觉表征模型，不等同于人形机器人整机或通用操作策略。", "analysis": "数据量、任务效果来自公司团队自报；独立复现未见。该项目是触觉表征模型，不等同于人形机器人整机或通用操作策略。", "sources": [{"label": "官方技术页", "url": "https://technology.robbyant.com/lingbot-touch"}, {"label": "官方代码", "url": "https://github.com/Robbyant/lingbot-touch"}]}, {"title": "Galaxea推出LEMO桌面双臂开发平台", "date": "2026-11-09", "body": "公司官网称LEMO整合两条A1Z机械臂、夹爪、腕部与顶部相机、CCU控制器，标准款售价7,699美元（税费运费另计），11月9日起官方店销售及发货。；定位为双臂具身研发平台，提供数据采集、模型训练和真实部署验证硬件；非双足人形产品。 局限：规格、上市和售价均为厂商页面信息；未获独立到货/测试反馈。", "analysis": "规格、上市和售价均为厂商页面信息；未获独立到货/测试反馈。", "sources": [{"label": "Galaxea官方新品页", "url": "https://galaxea-dynamics.com/blogs/robotics-insights-news/two-arms-one-platform-galaxea-launches-lemo"}]}, {"title": "智蜂创元完成8,000万元天使轮，披露精密插拔产线部署", "date": "2026-11-09", "body": "投资界单篇报道，公司融资8,000万元，首个场景为光电精密制造插拔，并称视触觉融合方案已在真实产线部署；已推出Z100轮式双臂机器人，Z700在研发。 局限：投资方仅称亚洲头部私募，未具名；产线客户、任务分母、节拍、良率、验收和持续运行数据均未披露，部署事实和能力为报道/公司口径。", "analysis": "投资方仅称亚洲头部私募，未具名；产线客户、任务分母、节拍、良率、验收和持续运行数据均未披露，部署事实和能力为报道/公司口径。", "sources": [{"label": "投资界单篇报道", "url": "https://news.pedaily.cn/202611/571555.shtml"}]}, {"title": "大晓机器人披露酒店洗衣多步骤作业试点", "date": "2026-11-10", "body": "亿邦动力11月10日报道其机器人在酒店执行取衣、过廊、洗烘、装篮、送回的连续流程。报道称烘干机取衣技能约57小时完成165轮改进，牛仔裤未取尽比例从均值48%降至32%，最佳单次19%。 局限：报道具有企业宣传性质，数据由公司提供；未披露酒店名称、独立客户验证、完整成功/失败分母、运营天数、人工接管与成本，不应写为规模商用。", "analysis": "报道具有企业宣传性质，数据由公司提供；未披露酒店名称、独立客户验证、完整成功/失败分母、运营天数、人工接管与成本，不应写为规模商用。", "sources": [{"label": "亿邦动力单篇报道", "url": "https://www.ebrun.com/20261110/718764.shtml"}]}, {"title": "物原科技披露天使及天使+轮融资合计超1亿美元", "date": "2026-11-10", "body": "36氪11月10日人物报道回溯公司7月成立后一个月内完成天使和天使+轮，累计超1亿美元，投资方包括红杉中国、IDG、蚂蚁、美团战投等。公司方向为物理AI/物理基础模型，报道提及GeoPT等学术路线。 局限：该条为11月5日前后披露的近期重要进展而非11月10日新融资；采用36氪文章陈述，未见公司公告或投资方逐一确认。融资金额、公司演示不代表已有机器人产品或商业交付。", "analysis": "该条为11月5日前后披露的近期重要进展而非11月10日新融资；采用36氪文章陈述，未见公司公告或投资方逐一确认。融资金额、公司演示不代表已有机器人产品或商业交付。", "sources": [{"label": "36氪单篇报道", "url": "https://www.36kr.com/p/4063823787561861"}]}, {"title": "Google发布Gemini Robotics 2.5，披露Apollo 2汽车产线验证", "date": "2026-11-10", "body": "DeepMind称模型已在合作伙伴中推广；在匈牙利、德国Mercedes-Benz产线概念验证中，Apptronik Apollo 2执行汽车零件拣选与装箱，报告96%成功率。；官方另称覆盖200类任务，相对旧基线各任务成功率高30%至100%、快20%至30%。 局限：数据均为DeepMind披露，未披露测试周期、任务总数、人工接管、节拍或梅赛德斯独立评价；概念验证不是量产部署。", "analysis": "数据均为DeepMind披露，未披露测试周期、任务总数、人工接管、节拍或梅赛德斯独立评价；概念验证不是量产部署。", "sources": [{"label": "Google DeepMind官方发布", "url": "https://deepmind.google/blog/gemini-robotics-2-5-accelerates-real-world-physical-intelligence/"}]}, {"title": "Social Humanoid让宇树G1根据人的动作生成全身交互", "date": "2026-11-05", "body": "CoRL 2026论文/预印本在29自由度Unitree G1上，将人和机器人动作序列共同建模，使用分层策略生成响应动作并在遮挡时预测人类伙伴运动；作者构建了260小时的人-人形互动数据集。；论文包含仿真与真机实验；项目关注握手、击掌等有身体接触的交互。 局限：尚属论文/研究验证，不能据此推断社交适切性、舒适度或安全已解决；没有长期用户研究及真实商业部署证据。", "analysis": "尚属论文/研究验证，不能据此推断社交适切性、舒适度或安全已解决；没有长期用户研究及真实商业部署证据。", "sources": [{"label": "arXiv论文", "url": "https://arxiv.org/abs/2611.08407"}]}, {"title": "A2-MEAS以纠错代码和执行历史支持具身任务失败恢复", "date": "2026-11-06", "body": "arXiv预印本提出A2-MEAS多智能体框架：将纠错语言、空间证据、执行历史和动作提案编码为部署时可更新的纠正代码，A2-WLA在视觉-语言-动作策略中增加运动历史与潜在世界模型。；作者在100项BEHAVIOR公开任务报告45.40%任务成功率；在12项真机任务、5类家庭环境报告57.92%，对照pi0.5为26.67%。 局限：预印本作者报告，非独立复现；基准、机器、任务预算及人工介入口径仍须阅读全文核对；不可用不同版本榜单直接比较。", "analysis": "预印本作者报告，非独立复现；基准、机器、任务预算及人工介入口径仍须阅读全文核对；不可用不同版本榜单直接比较。", "sources": [{"label": "arXiv预印本", "url": "https://arxiv.org/abs/2611.09124"}]}], "followups": ["LingBot-Touch外部复现/更多硬件适配及LEMO首批交付反馈。", "智蜂创元、大晓机器人出现客户验收、任务分母、接管和连续运行数据；物原公布模型及真机验证。", "Social Humanoid公开代码/用户评估，A2-MEAS公开代码或独立复现。"]}, {"date": "2026-11-10", "edition": "9条 · 中国内地6条／香港1条／海外2条 · 产品产业6条／技术研究3条", "updated": "10:25", "intro": "国内新增信息集中在数据采集、市场渠道和融资：简智推出灵巧手采集手套，Noitom公布手部动作数据，电信终端渠道与优必选签约，但目标规模不能当作订单。技术侧出现Hi-WBC多机长程演示和NVIDIA新模型评测，仍缺少统一任务下的独立复测与长期运行数据。昨天已报道的拓斯达STAR等不重复刊登；海外只保留Atlas工程测试和GR00T 2两项。", "items": [{"title": "国内融资｜优理奇完成5亿元Pre-A轮融资", "date": "2026-11-09", "body": "新京报贝壳财经报道，优理奇宣布完成5亿元Pre-A轮融资，绿地集团、柯力传感等产业投资者加入。公司称稳定月出货超过百台，并在安保、酒店和零售形成客户订单；这些运营数字来自企业口径。优理奇现有产品以轮式双臂平台为主，本条是融资与服务机器人商业化进展，不是双足新品。", "analysis": "产业投资者可能带来场景和供应链协同，但投资不等于采购；月出货、订单与客户验收仍应分开核对。", "sources": [{"label": "新京报贝壳财经（新浪财经刊载）", "url": "https://finance.sina.com.cn/jjxw/2026-11-09/doc-iniycmty6530337.shtml"}]}, {"title": "国内产业｜中国电信终端公司与优必选签署战略合作", "date": "2026-11-09", "body": "双方建立联合创新实验室，并提出未来三年共同推动家庭陪伴机器人行业规模超过百万台、超仿生及轮式人形机器人终端行业规模超过10万台；还将探索集采、营销、租赁和营业厅体验。上述数字是行业规模目标，不是双方采购承诺或已签销量。", "analysis": "渠道、体验和租赁探索可能降低用户接触产品的门槛；后续要看具体采购计划、合同及实际交付。", "sources": [{"label": "IT之家：战略合作报道", "url": "https://m.ithome.com/html/1024340.htm"}]}, {"title": "国内新品｜简智发布DASDex 2.0灵巧数据采集手套", "date": "2026-11-08，CoRL 2026期间", "body": "简智发布的新款手套采用约60克侧置外骨骼结构，厂商称可记录21自由度手部动作，集成980个触觉单元、最小检测力0.1牛；结合第一人称及腕部相机记录动作和接触，支持人类示范采集及适配后的遥操作。指标尚无独立耐久、精度或跨手型测试。", "analysis": "动作、视觉与接触信号同步采集，有望补充灵巧操作数据；规格本身还不能证明能提升策略成功率。", "sources": [{"label": "简智机器人官方微博发布", "url": "https://m.weibo.cn/2/detail/5362919879213559"}]}, {"title": "国内数据｜Noitom公布11小时HiPHI-Hand手部动作数据", "date": "2026-11-09", "body": "Noitom公告称将在Hugging Face发布11小时同步第一人称双鱼眼视频、相机外参和光学动捕手部三维关节真值，并称其曾作为NVIDIA EgoHand训练来源之一。公告标注研究许可；本次未能独立打开该数据集页面，因此只确认发布公告与规格，未确认实际下载权限及商用许可。", "analysis": "视频与高精度动作真值配对，可用于手部重建研究；其对机器人操作策略的训练价值还取决于数据任务覆盖和许可。", "sources": [{"label": "Noitom新闻稿（GlobeNewswire分发）", "url": "https://www.globenewswire.com/news-release/2026/11/09/3398459/0/en/noitom-robotics-releases-hiphi-hand-precision-hand-capture-data-used-to-train-nvidia-egohand-and-demonstrates-real-time-hand-reconstruction-at-corl-2026.html"}, {"label": "HiPHI-Hand数据页（本次访问未确认）", "url": "https://huggingface.co/datasets/noitomrobotics/HiPHI-Hand"}]}, {"title": "国内市场数据｜IDC预计2026年全球灵巧手出货约2.5万台", "date": "2026-11-09", "body": "IDC在11月9日发布的文章预计，2026年全球灵巧手出货约2.5万台，不含厂商向自有机器人内部配套出货；中国厂商占比预计超过85%。IDC称当前需求集中在人形配套、科研教育和数据采集，工业规模应用仍处探索阶段。数字为全年预测，并非已实现销量。", "analysis": "该口径可观察外部供货市场，但不代表全部灵巧手需求，也不能据预测推断工业部署已经普及。", "sources": [{"label": "IDC原文：灵巧手的下一战怎么打？", "url": "https://www.idc.com/resource-center/blog/%E7%81%B5%E5%B7%A7%E6%89%8B%E7%9A%84%E4%B8%8B%E4%B8%80%E6%88%98%E6%80%8E%E4%B9%88%E6%89%93%EF%BC%9F%E7%A1%AC%E4%BB%B6%E5%8F%AA%E6%98%AF%E5%85%A5%E5%9C%BA%E5%88%B8%EF%BC%8C%E8%BD%AF%E7%A1%AC%E5%8D%8F%E5%90%8C/"}]}, {"title": "国内技术｜北京人形补充Hi-WBC多机长程整理演示", "date": "模型11月2日发布；新增演示于11月9日披露", "body": "北京日报披露的新增真机样本中，多台机器人一镜到底完成搬椅、拾物、搬运垃圾袋及分工接续。Hi-WBC将人体动作作为意图参考，再按负载、外力和地形调整姿态。报道未披露任务成功分母、持续时长和人工介入；这是对既有模型发布的新增演示信息，不等于家庭部署。", "analysis": "新增材料展示了从单动作控制向多机生活化任务衔接的尝试；稳定性仍需按任务次数、异常恢复和人工接管量化。", "sources": [{"label": "北京日报报道（北京市政府网站刊载）", "url": "https://www.beijing.gov.cn/fuwu/lqfw/gggs/202611/t20261109_4938923.html"}]}, {"title": "香港新品｜Somnia Lab公布亲密陪伴型仿生机器人Model L规格", "date": "2026-11-09报道；首批交付计划为2027年", "body": "36氪报道，香港初创Somnia Lab公布Model L基础款规格，身高约165厘米、体重约22公斤，面向亲密陪伴交互，并计划2027年首批交付。目前可核信息来自媒体报道，尚未见可访问的原始产品页、原型测试、定价或实际交付证据。", "analysis": "这类产品把交互体验、隐私、同意机制与安全设计推到前台；目前应视为产品计划，不能写作已上市。", "sources": [{"label": "36氪：Somnia Lab产品计划报道", "url": "https://www.36kr.com/p/4062169952851589"}]}, {"title": "海外研究｜波士顿动力用轮式Atlas压测执行器与控制模型", "date": "2026-11-09", "body": "Boston Dynamics工程师介绍，团队在Atlas踝部安装轮子，以持续高扭矩、高转速测试执行器及全身强化学习控制。360度跳转采用人类动捕轨迹跟踪，公司称首次尝试成功；侧滑展示控制器学会利用轮子滚动。公司明确称这是研究测试平台，不是新品，也不代表双足行走能力。", "analysis": "价值在于将真实执行器响应与仿真模型对齐，推动sim-to-real调试；单次成功不能代表重复成功率或产品性能。", "sources": [{"label": "Boston Dynamics官方工程文章", "url": "https://bostondynamics.com/blog/atlas-on-a-roll/"}]}, {"title": "海外技术｜NVIDIA发布GR00T 2世界动作模型与仿真工具", "date": "2026-11-09，CoRL期间", "body": "NVIDIA发布GR00T 2并展示Isaac Lab 3.0。厂商称该模型利用人类与机器人数据训练，在50项任务中40项至少成功一次；每项任务提供1次示范时平均成功率71%，5次时95%。指标为厂商公布的任务集评测；作者项目页称论文与代码计划12月开放，目前不能写成已开源。", "analysis": "少量示范后的适配表现值得关注，但还需看任务定义、人工介入、耗时成本和独立复现，不能直接外推到工厂部署。", "sources": [{"label": "NVIDIA官方发布：模型与仿真工具", "url": "https://blogs.nvidia.com/blog/robotics-simulation-advancements-corl/"}, {"label": "GR00T 2作者项目页", "url": "https://research.nvidia.com/labs/gear/gr00t-2/"}]}], "followups": ["Noitom数据页和许可文本可访问后，核对实际下载权限、数据字段及商业限制；简智若公布独立测试，再复查触觉精度、耐久与跨手型适配。", "优理奇客户或投资方公布采购、验收后，分别核对投资关系、订单、交付和持续运行；优必选合作出现具体采购计划时，复查行业目标是否转成业务。", "Hi-WBC发布完整评测，或GR00T 2按计划开放论文代码后，核对任务分母、人工介入和复现结果。拓斯达STAR仅在规格或交付出现实质新证据时再更新。"], "coverage": "检索窗口：2026-11-09 10:16至2026-11-10 10:25（UTC+8）。本期主选近24小时新增证据，并将11月8日简智新品纳入72小时窗口。对照11月9日报告后排除拓斯达STAR、智元G2、它石安波福等已报事项；Hi-WBC只写11月9日新增演示信息。重点来源检索状态和缺口见当期source-audit。"}, {"date": "2026-11-09", "edition": "10条 · 国内7条／海外3条 · 产品产业7条／研究3条", "updated": "10:16", "intro": "拓斯达同时发布工业双足机器人和面向人形零件加工的五轴设备，供给侧的更新已延伸到制造环节；智元X2焕新版则区分商业互动与研发配置。它石与安波福合作已有首批入线，百台级仍是年底目标，判断规模化还需看实际验收与连续作业数据。研究方面，程序改写与合成数据提供了两种改进路径，但验证仍限于特定任务。", "items": [{"title": "国内新品｜拓斯达发布工业双足Star，埃弗米推出S400五轴机", "date": "2026-11-07发布，11-08报道；周末重要进展", "body": "东莞广播电视台图文报道，拓斯达在TOPSDAY发布工业双足机器人Star，面向搬运、分拣；子公司埃弗米推出S400五轴机，面向人形关节壳体等精密加工。拓斯达还与凯航签署人形机器人采购协议，数量、金额未披露。Star具体作业参数与批量交付情况仍待补充。", "analysis": "整机与加工装备同时更新，连接了应用端和零部件制造端。后续需分别验证机器人作业能力与机床加工、验收数据。", "sources": [{"label": "东莞广播电视台：杨涛图文报道", "url": "https://webzdg.sun0769.com/web/news/content/939797"}]}, {"title": "国内新品｜智元X2焕新版更新商业互动与研发配置", "date": "2026-11-06晚", "body": "智元发布X2焕新版，青春版为30自由度，旗舰版为31自由度，配置不能混用。旗舰版配备Orin计算平台及雷达等研发配置，面向文旅商业互动、表演和二次开发。现有资料未披露价格、交付规模及真实环境下连续交互可靠性。", "analysis": "版本区分便于比较互动展示与开发需求；实际效果仍需在噪声、人流和长时间运行条件下验证。", "sources": [{"label": "IT之家：X2焕新版报道", "url": "https://www.ithome.com/1/023/497.htm"}, {"label": "北京商报王天逸｜同花顺刊载", "url": "https://news.10jqka.com.cn/20261106/c681566852.shtml"}]}, {"title": "国内产业｜它石智航与安波福推进产线应用，百台级仍属目标", "date": "进博会期间，2026-11-07报道", "body": "新浪科技图文报道，它石智航计划年底前让百台级A系列机器人进入安波福的8类工艺、33个场景。首批已进入产线，但数量未披露。现场A3插接演示不能替代长期生产验收，作业节拍、人工接管率及连续运行表现尚未公开。", "analysis": "已有入线事实比合作意向更进一步，但不能把目标规模记作实际交付；商业化判断应以买方确认和持续作业数据为准。", "sources": [{"label": "新浪科技：它石智航与安波福合作图文", "url": "https://finance.sina.com.cn/tob/2026-11-07/doc-inixwhsk8404468.shtml"}]}, {"title": "国内数据｜光轮与宇树合作串联数据、仿真和训练反馈", "date": "2026-11-05披露，11-06早报道；近期补充", "body": "据盖世具身智能图文，光轮与宇树合作，按照本体自由度、负载和传感器匹配人类视频及合成数据，以SimFoundry、RoboFinals进行仿真验证，再由RoboStack提供反馈，形成训练链。合作规模、金额及训练收益均未披露。", "analysis": "增量在于让数据供给适配具体机器人，而非只增加数据量；是否减少真机采集成本、改善任务表现仍待验证。", "sources": [{"label": "盖世具身智能：光轮与宇树合作图文", "url": "https://auto.gasgoo.com/news/202611/6I70477066C601.shtml"}]}, {"title": "国内交互｜新华社与优必选推出“新言”“新语”实体主播", "date": "2026-11-05；近期补充", "body": "新华社原始图文显示，第七届世界媒体峰会推出“新言”“新语”实体仿生具身主播，接入新华语典，张艺谋参与形象设计。实体出镜区别于屏幕数字人，但资料未给出无脚本交互时延、长期自主运行或销售数据，不能据展示推断任务可靠性。", "analysis": "实体交互进入媒体场景，但展示效果与开放式交流能力需要分开评估，尤其应观察打断、误解和失败恢复。", "sources": [{"label": "新华社：实体仿生具身主播原始图文", "url": "https://www.xinhuanet.com/politics/20261105/d0e241b2d41646ffaf437b19c0274a7b/c.html"}]}, {"title": "海外新品｜Embodied AI发布轮式双臂AIR，采用遥操作学习路线", "date": "2026-11-06", "body": "瑞士公司Embodied AI在慕尼黑发布轮式双臂AIR，将重执行器置于躯干，以腱绳传动减轻手臂重量。公司计划先通过人工遥操作积累经验，再学习自动化，并保留人工回退。新品的价格、交付数量及独立安全验证尚未披露。", "analysis": "轻量手臂与人工回退可能降低工厂导入难度，但轮式移动、接触安全和长期自主率仍需现场测试。", "sources": [{"label": "Humanoids Daily：AIR产品报道", "url": "https://www.humanoidsdaily.com/news/embodied-ai-air-wheeled-humanoid-factory-humanoid-europe"}, {"label": "Business Wire企业发布稿／FinancialContent分发", "url": "https://markets.financialcontent.com/wss/article/bizwire-2026-11-6-embodied-ai-unveils-air-a-physically-safe-humanoid-robot-that-learns-on-the-job"}]}, {"title": "海外产业｜软银披露收购ABB中国机器人业务受阻", "date": "2026-11-04收到通知，11-06公告", "body": "软银官方公告称，收到中国外商投资安全审查通知，禁止其收购ABB机器人业务在中国的业务；软银仍与ABB讨论后续安排。公告所指是中国业务收购受阻，不等于全球交易已经取消，也没有证据表明ABB在中国供货停止。", "analysis": "交易结构和区域业务安排出现不确定性。供应链判断应跟踪后续正式方案，不能从收购受阻直接推导客户断供。", "sources": [{"label": "软银集团：官方公告", "url": "https://group.softbank/news/press/20261106"}]}, {"title": "国内研究｜眸深发布深悟、深枢与家庭世界模型，验证仍待补齐", "date": "2026-11-07发布，11-08报道；周末重要进展", "body": "上海证券报记者宋薇萍报道，眸深在进博会发布深悟原生具身模型、深枢基础设施及家庭世界模型FWM，提出将动作生成与数据、仿真、模型及硬件整合。家庭服务是拟面向用途，目前尚未核验可复现的技术报告、代码和可比评测，联盟合作也不等于订单。", "analysis": "这次发布把模型和工程基础设施放在一起，实际价值要看能否在同一任务与预算下稳定提升表现。", "sources": [{"label": "上海证券报：宋薇萍报道／东方财富刊载", "url": "https://finance.eastmoney.com/a/202611083925579953.html"}]}, {"title": "国内研究｜PyRUA-REAL让智能体改写程序，减少执行时在线决策", "date": "2026-11-04 UTC／11-05 UTC+8预印本；近期补充", "body": "北大、众擎、新加坡国立等团队固定基础模型参数，让智能体根据执行反馈改写程序。双Franka机械臂8项真机任务中，7项得到无需在线智能体决策的程序，首次成功耗时1.5至45小时；网线插接仍需在线辅助。论文为预印本，作者项目页提供演示视频。", "analysis": "方法可能将推理负担转移到开发阶段，但非人形验证，不证明替代视觉—语言—动作模型；仍需固定程序独立复测与成本比较。", "sources": [{"label": "PyRUA-REAL：作者项目页", "url": "https://dagroup-pku.github.io/PyRUA-Lean/real/"}, {"label": "arXiv：PyRUA-REAL预印本", "url": "https://arxiv.org/abs/2611.06768"}]}, {"title": "海外研究｜苹果HALO用合成数据训练双足室内动作", "date": "2026-11-04 UTC／11-05 UTC+8预印本；近期补充", "body": "苹果HALO通过合成数据学习行走、坐下、开门、蹲下、爬行、推物6类技能。作者报告G1在6个房间、360次真机测试中成功率为91%。这项预印本研究依赖人类运动先验、人工关键帧、高算力数据生成及改装机载计算；目前未核验到可用代码入口。", "analysis": "结果支持限定室内技能的可行性；接触、遮挡和失败恢复仍是边界，距离通用家务还有验证缺口。", "sources": [{"label": "苹果研究团队：HALO项目页", "url": "https://apple-aiml-research.github.io/ml-halo/"}, {"label": "arXiv：HALO预印本", "url": "https://arxiv.org/abs/2611.06908"}]}], "followups": ["在新品规格或销售公告更新后，复查Star、X2、AIR的价格、交付阶段及连续作业证据。", "它石智航年底目标到期或买方披露后，核对实际入线数量、验收、节拍与接管率；实绩将改变部署判断。", "研究技术报告或代码可访问后，复查眸深验证条件、PyRUA固定程序复测及HALO失败恢复表现。"], "coverage": "检索窗口：11月6日10:27—11月9日10:16（UTC+8），覆盖周末停发期间；较早重要进展已标近期补充。部分公众号访问仍有缺口。"}, {"date": "2026-11-06", "edition": "6条 · 产品产业5条／研究1条", "updated": "10:27", "intro": "启元T1首次OTA公告把跟随、远程控制和家庭交互列为更新内容，但截止时尚未确认用户收到升级，功能发布与实际可用仍需分开判断。Noitom采集产品、菜鸟场景合作与MOVIN融资显示，动作数据采集和真实环境训练正在形成不同的产业供给路径；其成本、数据质量与训练收益仍缺少独立验证。", "items": [{"title": "国内新功能｜启元T1首次OTA计划推送，增加楼梯跟随与家庭交互", "date": "2026-11-05公告；计划2026-11-06推送，近期补充", "body": "据IT之家报道，启元公布T1首次OTA：跟随时识别楼梯并切换四足上下楼，支持App远程音视频及移动控制，加入有道HiEcho口语练习、儿童模式和指定用户提醒。Prime Toolkit支持二次开发技能部署。这是相较9月发布的功能更新，不是新整机；截止时未核实用户实际收到升级。", "analysis": "交互与移动功能组合有望扩大家庭使用范围；楼梯成功率、安全边界和长期表现仍待用户验证。", "sources": [{"label": "IT之家｜署名图文报道", "url": "https://www.ithome.com/1/022/530.htm"}]}, {"title": "数据新品｜Noitom发布ITW-Ego Plus，将第一视角与全身动作配对", "date": "2026-11-05（美国）；计划2026-11-09至12日CoRL演示", "body": "Noitom公司新闻稿宣布，将在CoRL展示ITW-Ego Plus数据采集产品，把第一视角视频与全身动作配对，并可选腕部视角、第三视角、手部压力和声音。拟展示的Body组合使用Sol头戴设备与Jupiter少量穿戴传感器，无需完整动捕服。价格及此次新增数据规模未披露。", "analysis": "轻量穿戴可能减轻真实环境采集负担，但尚无独立成本或迁移收益证据；计划开放数据的实际获取与许可条件也需复查。", "sources": [{"label": "Noitom Robotics｜GlobeNewswire企业新闻稿分发", "url": "https://business.thepilotnews.com/thepilotnews/article/gnwcq-2026-11-5-noitom-robotics-introduces-itw-ego-plus-at-corl-2026-in-the-wild-egocentric-data-with-full-body-motion"}]}, {"title": "国内产业｜菜鸟开放仓储场景，拟建设具身真实训练网络", "date": "2026-11-06公告", "body": "菜鸟企业新闻稿宣布产业合作，开放全球仓储及合作伙伴场景，拟建设具身智能真实训练网络，概念验证涉及数十类场景，包括拣选、配送和巡检。公司称已在快递、电商、快消及汽配推进规模化试点，涉及上料、贴标、分拣和复杂拆垛；各类机器人数量、自主率、人工接管及买方验收情况未披露。", "analysis": "真实仓库可提供异常与失败数据，但训练网络仍处于建设计划口径，不能据企业宣传认定已是全球最大。", "sources": [{"label": "菜鸟｜PR Newswire企业新闻稿", "url": "https://en.prnasia.com/releases/global/cainiao-launches-ai-and-embodied-intelligence-industry-partnership-touts-world-s-largest-real-world-training-network-554992.shtml"}]}, {"title": "海外数据｜MOVIN披露约750万美元A轮，扩展动作采集业务", "date": "2026-11-03（近期补充）", "body": "MOVIN官网披露约750万美元A轮融资，由IMM领投，累计融资超过1000万美元，资金用于全球业务、物理AI动作数据技术及韩国研发中心。其TRACIN融合激光雷达、相机和端侧AI，无需动捕服采集全身动作。公司自述产品上市一年营收约75万美元、售出200余台至20多个国家，属于采集工具而非人形整机销量。", "analysis": "融资与工具销售为动作数据供给提供商业化线索，但销量属公司自述，机器人业务占比和训练收益尚未披露。", "sources": [{"label": "MOVIN｜公司官网公告", "url": "https://www.movin3d.com/discover/movin-raises-7-5-million-in-series-a-funding-bringing-total-funding-to-over-10-million"}]}, {"title": "国内供应链｜因时科技与北邮共建仿人灵巧操作联合实验室", "date": "2026-11-04活动；2026-11-05 22:08报道", "body": "每日经济新闻现场报道显示，北邮与因时科技共建的仿人灵巧操作联合实验室于11月4日在首钢园活动中揭牌，推进手眼脑协同，面向制造装配、插接检测和柔性物体操作等任务。公司称锂电与3C领域出现新订单，但未披露客户、数量及验收。报道同时讨论了灵巧手接口与可靠性障碍。", "analysis": "高校控制算法与末端硬件协同有助于推进操作验证，但仍需实际节拍和寿命证据，不能据订单表述推定量产。", "sources": [{"label": "每日经济新闻｜记者郑欣蔚现场图文", "url": "https://www.nbd.com.cn/articles/2026-11-05/4639985.html"}]}, {"title": "海外研究｜减少复杂地形想象失真：TGI开源双足训练方法", "date": "近期研究补充：2026-11-06核验代码；精确首发日未标明", "body": "ETH苏黎世机器人系统实验室的TGI以MIT许可开源，引用信息标为未发表。方法让世界模型学习运动，按预测落脚位置直接读取高度图，支撑不足时截断不可靠梯度，减少沟壑边缘失真。研究在IsaacLab 3/PhysX中以Unitree G1仿真测试13种地形、5个随机种子，成功率81.8±2.5%，没有真机验证。", "analysis": "方法可能用于楼梯及不连续落脚训练，但真实感知误差与迁移仍待验证；仓库分项口径存在不一致，需作者澄清。", "sources": [{"label": "作者原始GitHub｜README与CITATION", "url": "https://github.com/leggedrobotics/terrain-grounded-imagination"}]}], "followups": ["启元出现用户升级记录后复查实际开放范围；楼梯连续测试、失败恢复或安全限制披露将改变可用性判断。", "CoRL 11月9—12日演示后复查Noitom采集流程与数据开放；菜鸟出现买方确认、接管及数据质量口径时更新产业判断。", "MOVIN披露客户验证、联合实验室给出节拍与寿命测试，或TGI补充真机及分项解释后复查，分别检验商业化、可靠性和迁移能力。"], "coverage": "检索窗口：11月5日11:14—11月6日10:27（UTC+8），补充此前待核近期事件并保留原日期。部分公众号及新品原文访问仍有缺口。"}, {"date": "2026-11-05", "edition": "6条 · 产品产业4条／研究2条", "updated": "11:14", "intro": "Agility合并已完成，接下来要验证的是挂牌和附条件订单兑现。Sidekick新增团队开发套餐，京东披露真实作业任务采集进展，说明竞争也在延伸到开发工具与数据供给。研究侧，Liber-0与GUILD分别探索人类经验迁移和采集预算分配；真机实验显示潜力，也暴露多步骤成功率和采集成本的限制。", "items": [{"title": "海外产业｜Agility完成合并，Digit订单与后续试点成为挂牌后的验证重点", "date": "2026-11-04（美国当地）", "body": "Agility Robotics宣布与Churchill Capital Corp XI完成业务合并，预计美国11月5日以AGLT挂牌；截至本期截止尚未开盘，不能称已上市交易。公司自述Digit累计运行6.5万小时，Digit 5订单超过3亿美元，但订单附带合同里程碑。RoboFab的1万台为设计产能，并非实际产量。", "analysis": "资本渠道扩大后，仍需看订单里程碑、收入确认与客户验收。GXO两个新站点及AGCO试点预计2027年推进，不能写成已部署。", "sources": [{"label": "Agility Robotics官方公告", "url": "https://www.agilityrobotics.com/content/agility-robotics-and-churchill-capital-corp-xi-complete-business-combination"}]}, {"title": "海外新品｜Sidekick推出Team协作套餐，把实机反馈纳入团队开发工作流", "date": "2026-11-04", "body": "Sidekick Robotics推出开发平台Team协作套餐测试版，定价为每人每周12美元，最多支持10名成员和10台机器人。功能包括共享模型工作区、多机管理，以及依据实机在线强化学习中逐回合成功或失败反馈调整模型。此次发布是开发平台更新，不是新机器人整机。", "analysis": "共享模型与反馈可能减少团队重复工作，但尚无独立效率评测；Flywheel持续学习仍在内部alpha调试，不能当作已开放功能。", "sources": [{"label": "Sidekick Robotics官方发布", "url": "https://www.sidekickrobotics.ai/news/introducing-team"}]}, {"title": "国内数据｜京东披露超10万项真实作业任务，数据基础设施覆盖生产与服务场景", "date": "2026-11-04", "body": "京东曹鹏在乌镇演讲中披露，其数据采集已覆盖100余个细分生产和服务场景，形成超过10万项真实作业任务；智元机器人已进入智狼仓，验证实际仓储流程。物理AI加速计划覆盖数据、基地、制造、销售、物流和服务环节，显示平台正在连接数据采集与场景验证。", "analysis": "任务数不等于小时数，数据去重、质量和人工接管口径尚未披露。此前的千万视频小时、百万本体小时是两年计划，不是本次完成量。", "sources": [{"label": "IT之家署名新浪图文报道", "url": "https://finance.sina.com.cn/tech/digi/2026-11-04/doc-inixqhks9413630.shtml"}]}, {"title": "海外供应链｜KAPEX展示韩国本土部件协同，90%口径仍需进一步拆解", "date": "2026-11-04（采访及获奖公布）", "body": "韩国科学技术研究院KIST在采访中展示双足平台KAPEX，称核心部件超过90%由韩国本土制造，并演示载物行走和握力调节；执行器、关节与触觉感知被纳入协同设计。LG等机构分别参与平台、人工智能、电池和制造，家庭生活实验室已建立，后续拟扩展至医院及公共空间。", "analysis": "这次是供应链采访，非本体首次发布；向LG技术转移发生于2025年9月。90%按数量还是成本未知，合作分工也不代表量产供货。", "sources": [{"label": "首尔经济日报英文版采访", "url": "https://en.sedaily.com/technology/2026/11/04/kist-builds-humanoid-robot-with-90-percent-local-parts"}]}, {"title": "国内研究｜Liber-0用人类视频连接机器人动作，困难多步骤任务成功率仍低", "date": "2026-11-04（媒体报道；官网未标精确首发时间）", "body": "LiberAI技术报告提出世界动作模型Liber-0，同时预测未来画面与动作：用手套测得的动作连接人类视频与机器人控制，并通过LEO的身体和视角设计减少迁移差异。60项新任务、600次真机试验中，在没有这些任务专属机器人示范的条件下，整体成功率36%，困难多步骤为10.5%。", "analysis": "人类经验可能降低特定任务的采集负担，但并非完全不用机器人训练数据。报告尚非已确认同行评审论文，也未证明工业长时可靠性。", "sources": [{"label": "LiberAI官方技术报告", "url": "https://www.liberai.com/blog/liber0/"}]}, {"title": "海外研究｜GUILD按目标贡献选择采集任务，用算力换取更有针对性的数据", "date": "2026-11-03 UTC提交，11月4日进入arXiv列表", "body": "得克萨斯大学奥斯汀分校团队的GUILD预印本先让视觉语言模型提出采集任务，再估算数据对目标任务的贡献，迭代分配示范预算。研究包含仿真和6个受控真机布景；闭集真机对照涵盖4个目标任务，每种策略对每项任务测试20次，同预算下表现较优。", "analysis": "它有助于回答“下一批该采什么”，但真人仍需示范；单轮归因用4张A5000需10至15分钟。实验优势尚不能换算为商业数采成本下降。", "sources": [{"label": "arXiv预印本摘要页", "url": "https://arxiv.org/abs/2611.05368"}, {"label": "arXiv预印本全文", "url": "https://arxiv.org/html/2611.05368v1"}]}], "followups": ["Agility挂牌后复核实际开盘状态、监管文件，以及Digit 5订单的里程碑、收入确认和客户验收。", "跟踪Sidekick Team支持的机器人范围、Flywheel开放时间及团队开发效率的可重复量化结果。", "继续核查京东数据的小时数、质量控制与接管口径，并观察Liber-0和GUILD是否开放可复现资源或增加非受控真机验证。"], "coverage": "检索窗口：11月4日10:10—11月5日11:14（UTC+8）。部分公众号原文及新品单篇访问存在缺口，未将聚合摘要当作已核验事实。本期延迟发送。"}, {"date": "2026-11-04", "edition": "9条 · 产品产业6条／研究3条", "updated": "10:10", "intro": "小米与李宁物流中心的进展把验证从单动作展示推进到连续工作流程，极智嘉则把重点放在整仓设备协同；这些现场与展会案例仍需接管率、节拍和买方验收来判断能否复制。GGII同时下调全年出货预测，提醒我们将项目进展与规模兑现分开观察。研究侧，Auriga验证通用模型的仿真执行闭环，Pixel与PanoTac分别给出人体示范迁移和触觉操作的真机实验，证据阶段并不相同。", "items": [{"title": "国内产业｜小米机器人进入工厂连续作业与公寓试运营", "date": "2026-11-03", "body": "据IT之家转述小米技术公众号，人形机器人在中控台侧盖板排序工站首次进行8小时作业，包含异常纠偏和产线协同。Xiaomi-Robotics-1也在自有青年公寓试运营，演示跨房间整理、清扫归位和巡检；两者均属初步验证。", "analysis": "连续流程比单动作演示更接近真实需求，但8小时不能视为单机续航或量产交付证明。", "sources": [{"label": "IT之家：工厂作业报道", "url": "https://www.ithome.com/1/021/525.htm"}, {"label": "IT之家：青年公寓试运营报道", "url": "https://www.ithome.com/1/021/602.htm"}]}, {"title": "国内产业｜极智嘉发布24/7自主智能仓计划", "date": "2026-11-03", "body": "极智嘉宣布24/7自主智能仓计划，将机器人作业与仓库软件协同作为下一阶段方向。方案结合Gravity具身智能框架与仓库大脑，覆盖物理操作、任务调度及异常处理，目标是让仓库全天候自主运行；这是发展计划，尚非已验收的无人整仓项目。", "analysis": "能否替代整段流程，取决于订单系统、异常处理和设备协同，而非单台机器人动作能力。", "sources": [{"label": "京报网｜完整图文（页面注明来源：网络）", "url": "https://www.bjd.com.cn/news/2026/11/03/12016110.shtml"}]}, {"title": "国内产业｜灵初机器人进入李宁物流中心试运行", "date": "2026-11-02（近期补充）", "body": "观点网报道，灵初智能、恒岩与李宁合作，搭载自研模型的整机进入李宁华东智慧物流中心试运行。机器人面向混装周转箱识别、抓取和分拨鞋盒，箱满后推箱，并接入现有仓储管理系统。报道未披露台数、拣选量、接管率及买方验收。", "analysis": "真实订单与异常摆放比单次抓取更有验证价值，但扩站判断仍需连续运营数据支持。", "sources": [{"label": "观点网报道", "url": "https://www.guandian.cn/article/20261102/621892.html"}]}, {"title": "国内产业｜飒智披露六臂工业具身机器人的工位定位", "date": "2026-11-03 10:06采访（近期补充）", "body": "硬氪采访显示，飒智已形成单、双、四、六臂工业具身产品矩阵。六臂“玄甲”将机械臂布置在前腰、后腰和肩部，目标是完成双工位并行、拿取工件、组装、锁附及涂胶。这是产品定位和场景披露，并非六臂产品当天首次发布。", "analysis": "多臂可能减少换工具和等待，但碰撞规划复杂度与实际节拍收益需要逐工位验证。", "sources": [{"label": "硬氪采访", "url": "https://www.36kr.com/p/4053394503603076"}]}, {"title": "国内产业｜GGII下调中国人形机器人全年出货预测", "date": "2026-11-03", "body": "第一财经报道，高工机器人产业研究所（GGII）郑利瑶将2026年中国人形机器人出货预测由年初超过6万台调整为超过5万台，原因包括落地推进较慢、基础作业能力和碎片化需求难题。两项数字均为全年预测，不是实际交付统计。", "analysis": "公司动作增多不等于行业规模同步兑现，判断拐点应观察客户验收与持续使用情况。", "sources": [{"label": "第一财经报道", "url": "https://www.yicai.com/news/103423873.html"}]}, {"title": "海外产业｜1X用NEO头部原型演示语音控制电视", "date": "2026-11-02（近期补充）", "body": "HumanoidsDaily报道，1X员工将工厂瑕疵NEO头部制作成Dexter演示原型，用户语音提出看电影后，电视完成选片播放。这是头部与家居设备集成演示，并非完整机器人用手操作遥控器；具体接口、响应延迟、设备范围和开放日期均未公开。", "analysis": "对话连接设备动作具有交互价值，但不能外推为全部NEO用户已可用的正式功能。", "sources": [{"label": "HumanoidsDaily署名报道", "url": "https://www.humanoidsdaily.com/news/1x-neo-head-dexter-tv-home-integration"}]}, {"title": "国内研究｜让通用模型预演并纠正机器人动作：Auriga", "date": "2026-10-31 UTC提交；11-01媒体报道；11-03 arXiv列表（近期研究补充）", "body": "星衍智能的Auriga预印本为GPT-6 Astra加入三维测量、轨迹预演和执行检查，失败后再纠正动作，通过工具或生成程序驱动机器人执行网关。在RoboDojo的42项仿真任务中，五维平均成功率57.7%，单次任务平均耗时18.8分钟，仿真可暂停思考。", "analysis": "方法拓展了通用模型的动作接口，但尚未证明真实产线实时性，也不能视为取代视觉语言动作模型。", "sources": [{"label": "Auriga预印本", "url": "https://arxiv.org/abs/2611.01112"}, {"label": "Auriga代码仓库", "url": "https://github.com/lose4578/Auriga"}]}, {"title": "海外研究｜让人体示范更易迁移到移动操作：Pixel", "date": "2026-11-02 UTC提交；11-03 arXiv列表", "body": "卡内基梅隆大学的Pixel将轮式人形硬件、人体穿戴式数据采集与全身控制共同设计，用人的示范训练机器人移动操作。三个真机任务的平均任务完成进度为82%，每项任务、每种条件测试20次。该指标并非完整任务成功率，高层技能组合也未系统验证。", "analysis": "软硬件协同有助于降低示范迁移难度，但轮式底盘和柔顺夹爪限制了楼梯及精细操作范围。", "sources": [{"label": "Pixel预印本", "url": "https://arxiv.org/abs/2611.03648"}]}, {"title": "海外研究｜在遮挡下识别按压与滑动：PanoTac", "date": "2026-11-02 UTC提交；11-03 arXiv列表", "body": "PanoTac预印本由纽约大学、纽约市立大学和哥伦比亚大学团队提出，融合压阻与磁信号，估计指尖按压力和切向滑动。在取试管、舀谷物、倒盐三个真机任务中，每任务每策略测试20次；触觉加视觉成功率91.7%，同任务纯视觉为45%。", "analysis": "同任务对照显示触觉在遮挡操作中的增益，但样本较小，尚无工业长时耐久验证。", "sources": [{"label": "PanoTac预印本", "url": "https://arxiv.org/abs/2611.03520"}]}], "followups": ["继续跟踪小米与李宁现场：若披露连续运行时长、人工干预记录和买方验收结果，再判断是否具备扩站条件。", "智元G2便利店已公布挑战成绩；接下来核对各岗位总尝试数、人工接管和停机原始记录，避免把混合任务计数当成功率。", "双足方向继续核对Anchor 1与单目躲球研究的真机样本、失效条件及恢复动作，取得全文和实验记录后再作专题比较。"], "coverage": "主检索窗口为11月3日10:40至11月4日10:10（UTC+8）。补入此前未收录的近期产品与研究并标注实际日期；部分公众号原文和视频存在访问缺口，相关内容仅按已核验报道表述。"}, {"date": "2026-11-03", "edition": "8条 · 产品产业6条／研究2条 · 智元专项补充", "updated": "15:22", "intro": "智元把六台机器人放进营业便利店完成24小时挑战，公布1730项任务成绩；相较单项演示，验证延伸到了多岗位协作与长时运行，但仍需分岗位成功率和人工支持数据判断可复制性。Tutor的按时收费服务、Thinker-Sim与Intrinsic Core工具、触觉模组送样，则分别推进运维、开发和供应链环节。Movens-Zero与ROOF关注动作数据和受阻起身，仍须区分仿真、真机演示与完整任务能力。", "items": [{"title": "国内产业｜智元六台G2完成24小时便利店挑战，公布1730项任务成绩", "date": "2026-11-02至03", "body": "11月3日，智元六台精灵G2结束24小时便利店作业挑战，覆盖迎宾、商品取送、咖啡、早餐、补货巡检和清洁。人民财讯报道，厂商公布累计完成1730项任务。相比单项动作演示，这次测试把多机协作和不同岗位放进真实营业流程，持续观察高峰与夜间作业。", "analysis": "1730项是不同岗位的混合计数，并非订单量或成功率；现有报道未提供总尝试数、人工接管、停机与成本明细。", "sources": [{"label": "人民财讯／东方财富", "url": "https://finance.eastmoney.com/a/202611033919935933.html"}, {"label": "现场视频｜小羊biubiu呀，11月2日探店（非完整直播回放）", "url": "https://www.bilibili.com/video/BV1KP4A6HEF7/"}]}, {"title": "海外产业｜Tutor把机器人、远程协助与按小时收费打包进入工厂", "date": "2026-11-02", "body": "a16z宣布领投Tutor Intelligence B轮，并介绍Cassie单臂整箱拣选码垛及Sonny双臂单品拣选。投资方称机器人已进入制造物流现场，由远程操作员协助并积累训练数据，服务按小时收费；2027年底超过1000台处于签约状态只是未来目标，并非当前部署量。", "analysis": "一体化计费有助于验证客户付费意愿，但接管比例、收费单价及客户运行统计尚未披露。", "sources": [{"label": "a16z", "url": "https://www.a16z.news/p/investing-in-tutor-intelligence"}, {"label": "Tutor Intelligence", "url": "https://tutorintelligence.com/"}]}, {"title": "国内产业｜零售机器人走访揭示值守、补货与异常处理成本", "date": "2026-11-01转载；走访日期未披露（近期补充）", "body": "署名量子位的采访走访北京中关村零售仓和便利店。工作人员称，营业仍需人员值守、补货、充电和报修，商品也须提前摆放整齐；出现放歪或缺货时，机器人可能等待人工处理。观察仅来自少数门店，不能推广到整个行业，也不是智元本次挑战结果。", "analysis": "零售方案评估不能只看标准取货演示，还需核算商品覆盖、异常频率和现场人力占用。", "sources": [{"label": "量子位／新浪转载", "url": "https://news.sina.cn/ai/2026-11-01/detail-inixfkxt6584008.d.html"}]}, {"title": "国内产业｜优必选推出Thinker-Sim，串联场景重建、数据合成与评测", "date": "2026-11-02（近期补充）", "body": "优必选推出Thinker-Sim软件平台，覆盖实景重建、仿真数据合成和机器人评测，并提供可视化编排及自然语言配置。公司称配备八张GPU的节点每日可合成390小时仿真数据，但芯片型号、统一预算对照及真机收益未核验；价格、外部开放和第三方接入条件也未明确。", "analysis": "平台试图减少具身数据工具链的拼装工作，但仿真产量不能直接换算为真实经验或部署降本。", "sources": [{"label": "新浪科技", "url": "https://finance.sina.com.cn/tech/shenji/2026-11-02/doc-inixicic0524615.shtml"}, {"label": "盖世汽车", "url": "https://auto.gasgoo.com/news/202611/2I70476583C601.shtml"}]}, {"title": "国内产业｜灵枢智肤推进离子聚合物触觉模组送样与材料中试", "date": "2026-11-02（近期补充）", "body": "灵枢智肤创始人贾炜介绍，公司在聚合物中加入离子，利用材料变化产生传感信号，已推出手指以及指尖加掌心触觉模组，面向灵巧手和采集手套，并正建设材料中试线、推进客户送样。", "analysis": "进展仍处于材料、器件和送样阶段；批量一致性、漂移及买方验证将决定能否转入供货。", "sources": [{"label": "36氪硬氪", "url": "https://www.36kr.com/p/4051972607530113"}]}, {"title": "海外产业｜Intrinsic Core开放机器人实时控制与运动规划栈", "date": "2026-11-02社区介绍；此前ROSCon已发布", "body": "Intrinsic员工11月2日在ROS社区介绍数周前已于ROSCon发布的Intrinsic Core，并非当天首次开源。代码采用Apache 2.0许可，包含本地运行栈、实时控制、运动规划、视觉及机器人操作系统接口，并附数控机床上下料参考方案；仓库声明其并非Google正式支持产品。", "analysis": "开放栈有望减少机械臂、夹爪和感知软件的重复集成，但本次未运行复现，不能推断服务保障。", "sources": [{"label": "Open Robotics社区", "url": "https://discourse.openrobotics.org/t/intrinsic-core-released-open-source-ros-compatible-real-time-control-motion-planning-and-more/59457"}, {"label": "Intrinsic Core代码仓库", "url": "https://github.com/intrinsic-ai/intrinsic-core"}]}, {"title": "国内研究｜让人形从网络视频学习连续动作：Movens-Zero预印本", "date": "2026-10-30 UTC提交，11-02进入cs.RO列表（近期研究补充）", "body": "浙大、宇树等团队提出Movens-Zero，从网络人体视频恢复动作，再修正映射到人形机器人并进行仿真跟踪。Movens-5M包含500万条人形动作序列，模型可按文字、语音、音乐和视频生成连续动作，并展示G1真机效果；该数据量不是500万次真机采集或成功验证。", "analysis": "方法面向动作生成与跟踪，不代表通用家务能力；脚地接触、关节限制及同预算真机对比仍待验证。", "sources": [{"label": "arXiv预印本", "url": "https://arxiv.org/abs/2610.41877"}, {"label": "Movens-Zero代码仓库", "url": "https://github.com/wendell0218/Movens-Zero"}]}, {"title": "国内研究｜帮助倒地人形在障碍中建立支撑：ROOF预印本", "date": "2026-10-30 UTC提交，11-02进入cs.RO列表（近期研究补充）", "body": "港大与中科院团队提出ROOF，让倒在桌子或障碍下的人形先腾出空间、建立支撑再起身；部署仅使用本体感知，几何信息用于训练。论文表V报告G1七类障碍95次成功、共150次，但引言写为74次成功、共132次，内部统计冲突，仍待作者澄清。", "analysis": "木板加梯子场景仍可能机械卡住；仿真结果不能当作真机成功率，更不构成安全认证。", "sources": [{"label": "ROOF论文", "url": "https://arxiv.org/pdf/2610.42097"}, {"label": "ROOF项目页", "url": "https://lu-yidan.github.io/ROOF/"}]}], "followups": ["继续核验智元各岗位的总尝试分母、人工接管、停机、异常恢复、成本及完整回放；1730项仍按混合任务计数，不改写为订单或成功率。", "等待ROOF作者澄清表V的95/150与引言74/132为何不一致，并复查后续论文版本。", "跟踪Tutor的实际部署规模、远程接管比例和收费口径，以及Thinker-Sim外部开放、定价与真机收益证据。"], "coverage": "基础检索截至11月3日10:40（UTC+8），智元专项补充核验至15:22。基础资讯沿用上午核验资料，下午补入挑战收官报道及第三方探店视频。保留真实事件日期；视频不是官方完整直播回放。"}, {"date": "2026-11-02", "edition": "9条 · 产品产业6条／研究3条 · 周末回溯", "updated": "11:45", "intro": "K15进入两家咖啡门店、C1披露小批量交付，应用进展比演示更具体，但仍缺持续运行和买方验收数据。奥比中光万台协议针对采集设备，不能等同整机销量。CEL与DexSafe分别探索共享经验和降低掉落风险，前者仍需人工参与，后者存在安全与成功率取舍。", "items": [{"title": "国内产业｜K15进入两家七鲜咖啡门店，千店复制仍是未来目标", "date": "2026-10-31", "body": "无界动力公告称，K15已在七鲜咖啡西宸里、长楹天街两家门店上岗，并与自动化产线配合工作。报道提到的1000余店复制及10亿元合作规模均为未来目标，不代表已经部署、付款或完成客户验收。", "analysis": "两店运营是场景落地增量，但尚不足以证明规模复制，应继续核对营业稳定性、人工接管和单店经济性。", "sources": [{"label": "IT之家转述无界动力公告", "url": "https://www.ithome.com/1/020/598.htm"}]}, {"title": "国内产业｜SynDexy C1披露首批小批量交付，面向精密装配", "date": "2026-10-30（近期补充）", "body": "雷峰网报道，SynDexy C1已完成首批小批量交付，目标场景为消费电子精密装配；产品配备22自由度灵巧手，M1模型结合视觉、触觉与力觉。报道未披露客户名称、交付台数、验收标准及持续工作表现。", "analysis": "交付阶段较单纯演示前进一步，但缺少买方确认和运行结果，暂不能判断复制速度及实际良率收益。", "sources": [{"label": "雷峰网行业报道", "url": "https://m.leiphone.com/category/industrynews/CLO1sIKJzw59DmrI.html"}]}, {"title": "国内产业｜Bubbo1巴布正式开售，定价9499元切入家庭陪伴", "date": "2026-10-29（近期补充）", "body": "财闻记者现场报道，曾于9月预售的Bubbo1巴布在10月29日正式开售，售价9499元。该家庭陪伴机器人支持自主移动、自动回充、拍照和交互，定位不等同通用家务机器人；实际交付数量及长期家庭表现尚未披露。", "analysis": "正式开售是相较预售的新阶段，后续判断重点应是履约规模、家庭环境故障率和用户持续使用情况。", "sources": [{"label": "财闻现场报道／新浪财经分发", "url": "https://finance.sina.com.cn/jjxw/2026-10-30/doc-iniwziiq2230072.shtml"}]}, {"title": "国内产业｜奥比中光签署万台战略采购协议，供货对象为采集设备", "date": "2026-10-29（近期补充）", "body": "奥比中光披露与大晓及合作伙伴签署万台战略采购协议，将提供深度及RGB相机、EGO、UMI、WristCam、Hub等采集硬件和定制软件。公司称项目进入产品交付阶段，但未公布已交数量、合同金额或验收进度。", "analysis": "协议显示机器人数据采集硬件需求扩大，但万台指设备和部件，并非万台整机，也不能视为全部履约。", "sources": [{"label": "奥比中光官方披露", "url": "https://orbbec.com.cn/index.php/index/News/info.html?cate=31&id=388"}]}, {"title": "海外产业｜Meta被曝与傅利叶开发内部人形原型Max", "date": "2026-11-01（UTC+8）", "body": "TNW引述The Information报道称，Meta正与傅利叶开发内部人形机器人原型Max并推进后续版本；相关演示发生时间更早，本次增量是媒体披露。据原报道，Meta回应称项目用于内部研究、没有销售计划，TNW也注明未独立验证原报道。", "analysis": "这更接近技术储备而非商业产品信号；性能、家务能力与商用时间均缺少官方公开证据，不宜外推。", "sources": [{"label": "The Next Web转述报道", "url": "https://thenextweb.com/news/meta-humanoid-robot-fourier-max"}]}, {"title": "国内产业｜杭行二号在杭州马拉松四个点位参与交通辅助", "date": "2026-11-01", "body": "云深处署名信息显示，基于DR02的杭行二号在杭州马拉松黄龙体育中心周边四个重点点位参与交通辅助，执行语音提示、手势、巡逻和问询，受阻时可安全待机。四个点位不代表四台机器人，连续运行及接管数据未披露。", "analysis": "公共活动提供了开放环境验证机会，但没有警方独立验收，不能据此称其取代交警决策或无人值守。", "sources": [{"label": "云深处署名发布／同花顺分发", "url": "https://news.10jqka.com.cn/20261101/c681326597.shtml"}]}, {"title": "国内研究｜CEL让机群共享成功经验，减少新增纠正示范", "date": "2026-10-30（v3；v1为10-19）", "body": "10月30日更新的CEL预印本通过共享成功片段修正失败，并异步调度执行与训练，减少新增专家纠正示范。手机包装实验中，96台机器人机群的成功率由79.2%升至98.3%；扩大机群也增加了采集数据，并非固定预算对照。", "analysis": "方法展示了机群数据闭环价值，但仍需初始专家示范、人工结果标签和环境复位，尚非长期客户部署。", "sources": [{"label": "arXiv摘要页", "url": "https://arxiv.org/abs/2610.25736"}, {"label": "arXiv v3全文", "url": "https://arxiv.org/html/2610.25736v3"}]}, {"title": "海外研究｜DexSafe降低灵巧手转物掉落，但安全过滤带来成功率损失", "date": "2026-10-27 UTC（近期补充）", "body": "DexSafe在仿真中为LEAP灵巧手按物体分别训练策略，通过校准仿真与实机差异、过滤危险动作来减少掉落。四物体状态输入评测中，过滤后掉落减少75%，目标到达率为91.5%，低于未过滤策略，呈现安全与完成度的取舍。", "analysis": "状态输入依赖动作捕捉，腕部相机表现较弱，机械臂部分也采用脚本控制，因此不能视为通用操作方案。", "sources": [{"label": "arXiv论文页", "url": "https://arxiv.org/abs/2610.37652"}, {"label": "DexSafe项目页", "url": "https://ian-chuang.github.io/dexsafe/"}]}, {"title": "国内研究｜启元发布PrimeSim并预告开源，技术指标待原始资料核验", "date": "2026-10-30", "body": "机器之心署名分发报道，启元发布面向机器人策略训练的世界模型仿真器PrimeSim，并预告开放模型权重、推理及训练代码。本期未取得原始论文、官方项目页或完整可下载代码，因此不采用报道中的排名、速度和成功率数据。", "analysis": "开源落地后才便于检查复现成本和适用边界；当前未核到真实机器人训练收益，不能从仿真器发布推定已解决真机训练。", "sources": [{"label": "机器之心署名分发／新浪财经", "url": "https://finance.sina.com.cn/roll/2026-10-30/doc-iniwzazv4642955.shtml"}]}], "followups": ["智元6台G2于11月2日10时启动便利店24小时挑战，计划11月3日10时结束；结果出来后核对各机任务分母、人工接管、停机时长及失败恢复，不以直播片段代替完成度。来源：https://www.jiemian.com/article/15280357.html", "K15、SynDexy C1及奥比中光协议若出现买方验收、实际交付数量或连续运行数据，重新评估商业化阶段。", "PrimeSim取得原始论文、可下载代码和真机验证后，再比较训练收益、资源成本及独立复现情况。"], "coverage": "检索窗口：10月30日10:45—11月2日11:45（UTC+8），包含周末；窗口外条目标近期补充。本机11:31恢复执行，本期延迟发送。部分公众号原文不可访问或索引滞后，研究列表为抽样扫描，仍有覆盖缺口。"}, {"date": "2026-10-30", "edition": "6条 · 产品产业4条／研究2条", "updated": "10:45", "intro": "智元创新日把硬件、末端执行器、操作系统与模型一起更新，选型需进一步核对接口兼容、开放范围和持续运行表现。Otto的退货机器人项目将先测试10套再决定扩展，说明客户已参与验证，但仍缺吞吐和成本结果。上纬新材财报则提醒：9月底的收入确认与10月开始交付属于不同时间口径，不能混为一谈。", "items": [{"title": "国内新品｜智元发布AHA3、OmniHand 3与灵渠OS", "date": "2026-10-29", "body": "智元发布第三代人形硬件架构AHA3，将运动、交互和作业硬件统一，并推出面向持续运行的新关节液冷方案。同期发布OmniHand 3系列灵巧手、OmniPicker 3触觉夹爪及Link-U OS 1.0；OS目前由部分伙伴试用，全面开源计划定在2026年底。", "analysis": "这次增量覆盖本体底层、末端执行器和软件接口，可能减少不同模块的集成工作。不过，IP67仅适用于所述专用关节，不能外推至整机；价格、交付时间、完整系统下载及独立耐久数据本次均未核验。", "sources": [{"label": "智元官方发布", "url": "https://www.agibot.com/article/231/detail/131.html"}]}, {"title": "国内产业｜上纬新材三季报呈现机器人投入与收入确认的时间差", "date": "2026-10-29", "body": "上纬新材三季报披露，2026年前三季度归母净亏损约4.22亿元。第一财经和新华财经援引季报称，报告期内机器人业务尚未确认收入；Q1、T1于9月20日开售，10月开始交付。报告期截至9月底，不能据此判断10月底的交付或收入情况。", "analysis": "现有证据反映的是研发投入、开售交付与会计确认之间的时间差，不代表产品没有开始交付，也不能由集团营收反推机器人销量。四季度收入、实际验收、退换货及交付口径将更能说明商业化质量。", "sources": [{"label": "上纬新材2026年三季报PDF", "url": "https://pdf.dfcfw.com/pdf/H2_AN202610291831183574_1.pdf"}, {"label": "第一财经", "url": "https://www.yicai.com/news/103416254.html"}]}, {"title": "海外项目｜Otto与Sereact计划测试双臂退货机器人", "date": "2026-10-28 · 72小时补充", "body": "Otto与Sereact计划在波兰物流中心分阶段测试退货商品的抓取、识别、评估和分拣，首期拟部署10套双臂系统，并根据初期结果决定是否扩至最多25套。系统采用机器人即服务模式，由Sereact运营维护，人员继续负责异常和质量检查。", "analysis": "形态多变的退货比标准箱件更能检验感知和抓取泛化，客户参与联合公告也增强了项目真实性。但25套只是扩展上限，并非已投入生产；吞吐、单件成本、人工接管率、付款金额和验收标准均未知。", "sources": [{"label": "Otto与Sereact联合新闻稿", "url": "https://www.globenewswire.com/news-release/2026/10/28/3389884/0/en/otto-group-and-sereact-bring-nvidia-powered-physical-ai-to-returns-processing.html"}]}, {"title": "海外产业｜LG公布家庭人形、数据工厂与执行器路线", "date": "2026-10-28 · 72小时补充", "body": "据Edaily对LG三季度电话会的报道，LG计划在2030年前后进入家庭人形机器人市场，重点考虑消费者可承担价格及与家电的适配。首尔LG Data Factory计划2026年第四季度全面运行，并到2027年累计形成约50万小时真实与虚拟训练数据。", "analysis": "LG当前披露的重点仍是数据基础设施和执行器准备：昌原试验线已于2026年上半年建成，公司称正准备量产并争取客户订单。这不等于已经批量供货或获得订单；售价、家用机交期和订单数量尚未核验，相关计划来自电话会媒体报道。", "sources": [{"label": "Edaily电话会报道", "url": "https://en.edaily.co.kr/news/eda202610285759/"}]}, {"title": "算法研究｜国内｜GO-3 Preview把结果预测接入行动闭环", "date": "2026-10-29", "body": "智元发布GO-3 Preview，其世界推理动作模型WRAM将推理、结果预测和动作连接，核心思路是在执行前判断可能结果，再利用真实执行反馈继续学习。官方展示包含零样本和少样本任务；煎饼任务使用少量演示，乐高任务还需要微调及智能体编排。", "analysis": "这一方案强调“预测后果再行动”，可能改善长流程操作中的纠错。但当前证据主要是官方演示和公司材料，不能推导为所有任务零样本完成；公开权重、独立同预算评测及商用可靠性均未核验。", "sources": [{"label": "智元官方发布", "url": "https://www.agibot.com/article/231/detail/131.html"}, {"label": "IT之家转载官方材料", "url": "https://www.ithome.com/1/019/806.htm"}]}, {"title": "算法研究｜海外｜ThinkWorld用视频中的动作后果辅助训练", "date": "2026-10-27 UTC提交（北京时间28日）· 72小时补充", "body": "NVIDIA与KAIST在预印本中提出ThinkWorld，针对带动作标签机器人数据稀缺的问题，先学习人类与机器人共享的动作表示，再预测动作后果，并比较预测与视频实际结果来训练，使普通无动作标签视频也能提供学习信号。论文于北京时间10月28日提交arXiv。", "analysis": "该方法把大量视频转化为机器人学习材料，想象推理主要用于训练，部署时不运行完整链路。在YAM双臂配色、挂杯和分类三项任务中，物体或场景变化条件下完成52/60；实验只有单一训练种子且需任务微调，尚不能外推到任意新任务。", "sources": [{"label": "论文HTML全文", "url": "https://arxiv.org/html/2610.37666v1"}, {"label": "ThinkWorld项目页", "url": "https://thinkworld-project.github.io/"}]}], "followups": ["核验智元CEL在10月30日排期后的正式结果，并在11月2日至3日六台G2便利店直播中观察人工接管、失败恢复和单机有效工作时间：https://www.agibot.com.cn/article/315/detail/250.html", "ROBOTIS于10月28日公开GPT-6 Astra经动作工具和ROS 2控制AI Worker的实验；后续核验延迟、重复成功率与接管，暂不能据此判断替代VLA。来源：https://discourse.openrobotics.org/t/gpt-6-astra-meets-the-real-world/59268", "Otto项目出现客户验收或扩至第二阶段、LG披露数据工厂实际运行或执行器订单后复查；在此之前不把部署和量产计划写成既成成果。"], "coverage": "覆盖2026-10-29 10:45至2026-10-30 10:45（UTC+8）；另补入10月28日海外项目与研究。重点公众号存在原文访问与索引滞后缺口，未全量订阅微信。"}, {"date": "2026-10-29", "edition": "5条 · 产品产业3条／研究2条", "updated": "10:45", "intro": "宇树第三季度营收同比增长69.93%，但归母净利润同比下降17.37%，研发投入同时明显增加，说明业务扩张与研发投入、利润压力并存；本条核验的财务指标未给出交付台数，不能据此推算机器人出货。新品与工具链继续向具体工作流延伸：Sagi尝试把移动、操作和人工协助结合，Tsing-Ego PRO瞄准工业数据采集，Genie Sim则补充柔性物体仿真与评测，但三者目前都缺少独立、连续运行证据。", "items": [{"title": "国内产业｜宇树单季营收增长，利润同比下降", "date": "2026-10-28晚披露，10月29日公告", "body": "宇树科技未经审计的三季报显示，2026年第三季度营业收入6.65亿元，同比增长69.93%；归母净利润1.13亿元，同比下降17.37%。同期研发投入同比增长249.58%。收入扩张、利润回落与研发加码同时出现，是本期财报最明确的变化。", "analysis": "研发增长可能影响短期利润，但仅凭财务数据无法拆分具体原因，也不能判断机器人自主作业成熟度。收入包含的产品及业务结构、交付台数均未在本条证据中披露，因此不从营收反推整机销量。", "sources": [{"label": "巨潮资讯：宇树科技三季度报告", "url": "https://static.cninfo.com.cn/finalpage/2026-10-29/1225637442.PDF"}, {"label": "上海证券报财报报道", "url": "https://paper.cnstock.com/html/2026-10/29/content_2282956.htm"}]}, {"title": "国内新品｜PHYMI发布四轮腿行动伙伴Sagi", "date": "2026-10-28", "body": "PHYMI发布首款Physical Agent行动伙伴Sagi，以四轮腿、拟人上身和小货箱组合移动与操作能力。发布影片展示搬运露营装备、准备办公室文件和会议物品、协作处理社区快递等场景。创始人刘念秋称，LINK机制会在系统需要信息或判断时引入人类协助。", "analysis": "产品形态强调日常任务中的移动、载物与操作协同，并把人工介入设计成系统组成部分。不过现有证据主要是发布影片和创始人采访，售价、交付时间、任务成功率及人工介入比例均未核验，不能据此认定已经商用或可连续无人运行。", "sources": [{"label": "凤凰财经：新品发布报道", "url": "https://finance.ifeng.com/c/8xaTaH7MHtq"}, {"label": "极客公园采访转载", "url": "https://www.aitntnews.com/newDetail.html?newId=30705"}]}, {"title": "国内工具链｜Tsing-Ego PRO发布并开启预订", "date": "2026-10-27展会发布；10月28日报道", "body": "清研精准在SAECCE 2026展示工业第一视角多视角同步采集产品Tsing-Ego PRO，并开启预订。厂商称产品支持轻量穿戴、端侧质检及抗环境干扰；官网介绍其通过多摄像头与激光对齐，采集视觉、空间和人类动作数据。配套Robot-in-the-Loop中试方案用于复刻工位机构、接口与流程，在进厂前测试后再到真实场景验收。", "analysis": "这一路线试图把数据采集和进厂前集成验证前置，有望减少现场调试的不确定性，但降低集成风险仍是分析而非已验证结果。预订不等于交付，价格、重量、续航及同步误差尚未核验，“车规级”也仅属于厂商口径。", "sources": [{"label": "具身智能之家转载清研精准发布材料", "url": "https://www.jushenhome.com/news/2159"}, {"label": "清研精准官方产品页", "url": "https://www.tsingstandard.com/products.html"}]}, {"title": "算法研究｜海外｜SuperMimic尝试降低全身动作训练成本", "date": "2026-10-20 UTC提交预印本（北京时间10月21日）；近期漏报补入", "body": "SuperMimic先从仿真数据学会预测动作后果，再利用这个世界模型指导动作策略更新。作者报告单张H100训练3小时超过已发布SONIC检查点的回报，并展示同一策略运行于宇树G1真机。作者项目页标注CoRL 2026。", "analysis": "这可能降低全身动作训练门槛，但评测使用训练动作，不能证明未见动作泛化；对照硬件和数据不同，不是同预算效率比较。训练耗时包含模型拟合与策略更新、不含评测，也不是生产任务可靠性验证。", "sources": [{"label": "作者项目与实验口径", "url": "https://supermimic.github.io/"}, {"label": "arXiv论文", "url": "https://arxiv.org/abs/2610.28480"}]}, {"title": "算法研究｜国内｜Genie Sim增强柔性物体仿真与模型评测", "date": "2026-10-28", "body": "智元升级Genie Sim，增加柔性物体仿真、模型评测和强化学习后训练功能。据公司披露，系统在4款机器人本体、22项任务中的仿真与真机任务得分相关性为96.7%；代码计划在GitHub更新，资产和数据集也计划开放。", "analysis": "96.7%是任务得分相关性，不是成功率，也不能解释为误差仅3.3%。结果来自公司自测，尚未证明复杂接触都能准确复现；本次代码是否已可下载也未核验，因此现阶段更适合作为仿真筛选能力线索，而非工业部署证据。", "sources": [{"label": "泰伯转载界面：升级及测试口径", "url": "https://www.taibo.cn/newsflashes/31616488"}, {"label": "证券时报人民财讯报道转载", "url": "https://stock.stockstar.com/IG2026102800027734.shtml"}]}], "followups": ["跟踪Google DeepMind于10月27日发布的Genie 4：目前是面向可信测试者的研究预览，机器人训练环境只是未来应用方向，尚无真机收益证据；后续关注开放测试、动作接口及机器人验证。它与智元Genie Sim不是同一产品。来源：https://deepmind.google/blog/genie-4-a-new-generation-of-world-simulation/", "等待智元10月29日基座模型的正式材料，核对模型角色、支持本体、真机任务和人工介入口径；同时关注11月2日G2便利店24小时直播中的接管次数、失败类型及恢复方式。", "继续核验Sagi和Tsing-Ego PRO的价格、交付安排及可重复运行数据；若出现客户确认、独立评测或明确交付数量，再更新商业化阶段判断。"], "coverage": "覆盖2026-10-28 10:37至2026-10-29 10:45（UTC+8）；SuperMimic为此前漏报补入。重点公众号存在原文访问与索引滞后缺口，未完整订阅微信。"}, {"date": "2026-10-28", "edition": "6条 · 产品产业4条／研究2条", "updated": "10:37", "intro": "H2-X官网现列出16.9万元含税起价和基础款／EDU版差异，比此前价格未披露更便于采购评估；基础款不支持二次开发，选型需核对版本。小米灵巧手与Luxonis视觉载板分别补充操作和感知硬件，但参数不能替代长期作业验证。研究方面，Genie Master与EgoForesight尝试利用执行反馈和含噪示范改进学习，证据仍限于公司验证及小规模真机实验。", "items": [{"title": "新品规格｜国内｜H2-X官网列出16.9万元起价与版本差异", "date": "10月21日发布；10月28日核验官网，页面更新时间未注明", "body": "官网显示H2-X基础款含税16.9万元，EDU版需联系销售；整机31自由度、含双电池重65公斤以上，标称静态续航约8小时、持续行走约4小时。基础款不支持二次开发，EDU版支持，并可选高算力模组及灵巧手。", "analysis": "价格公开降低了初步选型门槛，但续航、负载均为厂商口径，交付日期、带载工况和客户验收尚未核验。", "sources": [{"label": "宇树H2-X官方规格与价格", "url": "https://www.unitree.com/cn/mobile/H2-X/"}]}, {"title": "灵巧手｜国内｜小米披露21自由度工业仿生灵巧手", "date": "2026-10-27", "body": "据IT之家直接引述小米技术官微，新仿生手采用21自由度、26电机混合驱动和1500点全掌触觉，并引入腱绳张力控制、散热优化及模块化维护。团队从汽车工厂典型流程采集分析作业数据，并以真实工具和零件制作数字资产进行仿真抓握验证。", "analysis": "其工程方向贴近汽车制造，但尚无独立真机成功率、循环寿命、售价及量产交付信息，数据覆盖不能等同于完成相应工序。", "sources": [{"label": "IT之家引述小米技术", "url": "https://www.ithome.com/1/018/345.htm"}]}, {"title": "视觉硬件｜海外｜Luxonis发布五路相机视觉载板OAK 4 FFC", "date": "2026-10-27", "body": "70×53毫米的OAK 4 FFC最多连接五路摄像头，可在板端完成同步、深度、目标检测和神经网络推理，并利用自然场景特征动态校正相机相对位置。开发套件定价849美元并标注现发货；730美元裸板计划2027年第一季度推出，摄像头需另购。", "analysis": "该模块可分担机器人主计算机的视觉处理和校准工作，但不能替代全部主算力，现货状态也不等于客户已收货。", "sources": [{"label": "Luxonis官方产品与价格", "url": "https://www.luxonis.com/oak4-ffc"}, {"label": "Humanoids Daily发布报道", "url": "https://www.humanoidsdaily.com/news/luxonis-oak-4-ffc-humanoid-vision-computer"}]}, {"title": "产业整合｜海外｜FFR完成FFAI机器人业务及资产收购", "date": "2026-10-23交割；2026-10-26公告", "body": "FFR公告称，已于23日完成收购FFAI机器人业务及资产，以普通股和无投票权可转优先股支付对价，并将统一智能平台更名为FF OmniMind。公司给出被收购业务全年销售及出货约2000台指引，包含交割前期间；合并报表仅从23日起计入。", "analysis": "股权交易完成不代表产品能力已经验证，销售及出货的混合指引也不能视为付费客户实际部署数量。", "sources": [{"label": "FFR公司交割公告", "url": "https://www.prnewswire.com/news-releases/ff-eai-robotics-ecosystem-ffr-completes-acquisition-of-ffai-robotics-business-establishing-a-nasdaq-listed-humanoid-and-bionic-robotics-platform-october-robot-sales-expected-to-exceed-300-units-unveils-ff-omnimind-a-unified-a-302919898.html"}]}, {"title": "算法研究｜国内｜Genie Master让机器人从执行失败处继续改进", "date": "2026-10-27", "body": "智元发布Genie Master，以具身执行协议连接任务判断、执行和反馈，受阻后保留进度并重新规划。一层把成败经验整理为提示与长期记忆，另一层将失败、调整和结果用于动作策略训练。公司称G2已在便利店打包、取货及补货任务中验证。", "analysis": "框架强调跨任务持续改进，但无人在环和自主进化仍属公司主张，完整成功率、接管率与连续运行数据尚未披露。", "sources": [{"label": "新浪科技发布报道", "url": "https://finance.sina.com.cn/jjxw/2026-10-27/doc-iniwrzht4610342.shtml"}, {"label": "PChome框架与验证边界", "url": "https://article.pchome.net/news/16488.html"}]}, {"title": "算法研究｜海外｜EgoForesight降低含噪人类示范对机器人训练的干扰", "date": "2026-10-22预印本；近期研究补充", "body": "EgoForesight降低含噪第一视角动作标签的训练权重，并用示范实际结果塑造动作表征，部署时无需未来信息。Galaxea R1 Pro在四项双臂双手任务中各用100条遥操作示范、测试20次，平均成功率63.8%；代码已公开。", "analysis": "结果来自小规模真机实验且预训练私有数据未开放，尚不能外推到全身移动操作或通用生产任务。", "sources": [{"label": "arXiv论文", "url": "https://arxiv.org/abs/2610.31845"}, {"label": "作者代码仓库", "url": "https://github.com/LinShan-Bin/EgoForesight"}]}], "followups": ["11月2日复查智元六台G2的24小时直播，重点记录失败次数、人工接管、每班任务量；Genie Sim及29日基座模型出现正式材料后再评估。", "等待小米披露真机循环寿命和任务成功率，并核对Luxonis多路相机独立时延、完整配置价格及实际到货情况，避免以硬件参数替代作业表现。", "FFR披露月末实际销售出货及后续财务报表、EgoForesight出现公开数据或独立复现时更新判断；公司预测不计作已部署数量。"], "coverage": "覆盖2026-10-27 10:35至2026-10-28 10:37（UTC+8）；EgoForesight为10月22日近期研究补充。重点公众号存在索引滞后与访问缺口。"}, {"date": "2026-10-27", "edition": "6条 · 产品产业4条／研究2条", "updated": "10:35", "intro": "昨日预告中的智元G2 Max已有正式发布材料，工业选型可以进一步核对负载与作业边界；睿尔曼GEN62和Realbotix Echo也分别明确了轻载操作、社交交互的产品定位。GXO与Agility把既有合作扩展到两个新站点，意味着客户愿意继续推进，但新增部署仍是2027年计划。CO01和LogLook分别尝试用失败经验、按需视觉记忆减少重复学习与上下文开销，结果仍需区分企业真机自测和仿真。", "items": [{"title": "国内新品｜智元正式发布G2 Max，补充重载作业数据", "date": "2026-10-26", "body": "G2 Max曾在7月WAIC亮相，本次于AI WAVE正式发布，面向拆码垛、物料转运和产线供料。厂商披露单臂负载20kg、双臂额定40kg、峰值50kg，手臂重复定位精度≤±0.5mm；价格、交付规模和独立长时测试尚未公布。", "analysis": "本次正式材料为工业选型提供依据；参数仍属厂商口径，需结合客户验收、接管率和长时运行验证，“安规级”不代表本次已核验第三方认证。", "sources": [{"label": "IT之家发布报道", "url": "https://www.ithome.com/1/017/951.htm"}, {"label": "盖世具身智能", "url": "https://auto.gasgoo.com/news/202610/26I70475937C601.shtml"}]}, {"title": "海外部署｜GXO与Agility把Digit合作扩展至两个美国站点", "date": "2026-10-26", "body": "双方计划在北卡罗来纳州Statesville和田纳西州Lebanon站点新增部署，预计2027年初先采用Digit 4，待Digit 5商业可用后迁移。双方2024年已在佐治亚州开展机器人即服务合作，公司称累计搬运超过10万个料箱，但新增站点尚未上线。", "analysis": "合作范围从既有单站走向多站复制是积极信号，但新增机器人数量、合同金额、单次成本和人工接管率未披露，暂时无法判断复制效率。", "sources": [{"label": "Agility官方公告", "url": "https://www.agilityrobotics.com/content/gxo-and-agility-robotics-expand-partnership-to-accelerate-deployment-of-humanoids-in-u-s-operations"}]}, {"title": "国内新品｜睿尔曼推出GEN62桌面级六轴机械臂", "date": "2026-10-26报道，具体发布日未披露", "body": "据智东西转述发布资料，GEN62面向轻载自动化、具身研发与教学，自重3.5kg、额定负载2kg，工作半径660mm，重复定位精度±0.1mm。产品采用全谐波传动，可选控制器底座集成或分体方案，沿用同平台软件与开发接口，价格仅称万元级。", "analysis": "较低自重和统一开发接口有利于桌面集成，但全臂展最大负载3.5kg不能替代额定负载口径，交期、精确报价、持续负载与耐久性仍待验证。", "sources": [{"label": "智东西原文", "url": "https://zhidx.com/news/43264.html"}]}, {"title": "海外新品｜Realbotix发布Echo社交机器人并开放预订", "date": "2026-10-26", "body": "Echo提供桌面版和全身版，整机价格分别为11950美元和59950美元，199美元只是订金；操作管理服务月费19.99美元起。公司计划2027年下半年首批交付225台桌面版和25台全身版，主要定位陪伴、教育及社交交互，并非自主家务机器人。", "analysis": "机价之外还需计入必需订阅和选配费用；目前仍是预订，调用云服务时必要内容可能传给服务商，不能把本地存储表述理解为全部数据不出设备。", "sources": [{"label": "Realbotix公告", "url": "https://realbotix.ai/news/realbotix-launches-echo-humanoid-robot-line"}, {"label": "BusinessWire厂商通稿全文", "url": "https://www.tmcnet.com/usubmit/-realbotix-launches-echo-humanoid-robot-line-/2026/10/26/10469405.htm"}]}, {"title": "国内研究｜CO01尝试让机器人从本轮失败中即时调整", "date": "2026-10-26报道；官方博客标注2026年10月", "body": "可可矩阵CO01把示范、失败记录和即时指导直接放入上下文，由上层模块挑选经验、动作模型决定下一步，无需为当前任务重新更新权重。厂商真机测试选取首次易失败的任务，每项最多尝试5次，保留自身历史累计成功84%，无历史56%；这不是单次成功率。", "analysis": "这可能帮助现场纠错，但任务数、总试次和可下载代码尚未核验完整；长任务仍会积累误差，示范可能选错，上下文内新技能也不会自动保存到模型权重。", "sources": [{"label": "COCO Matrix技术博客", "url": "https://www.ccmtrx.com/research/co01"}, {"label": "机器之心署名分发", "url": "https://m.sohu.com/a/1092998070_129720"}]}, {"title": "算法研究｜LogLook按需查看历史，减少机器人记忆开销", "date": "2026-10-23预印本；近期研究", "body": "LogLook让系统保留执行日志和旧笔记，由GPT-6 Astra选择要看的图像。RoboMME仿真基准含16项桌面任务、共800测试回合；相同提示、预算和运动规划器下，相比反复重写笔记，成功率相近，模型处理的token（词元）减少43%，图片不到一半。", "analysis": "模型输出路点仍由运动规划器执行，依赖深度和相机标定；调用期间仿真暂停，尚无真机验证，不能把词元节省等同实际时延改善或取代视觉—语言—动作模型。", "sources": [{"label": "arXiv预印本", "url": "https://arxiv.org/abs/2610.32348"}, {"label": "论文实验与限制", "url": "https://arxiv.org/html/2610.32348v1"}]}], "followups": ["待G2 Max披露客户验收、价格、接管率和长时运行数据后复查；Genie Master仅在出现正式材料后纳入。", "跟踪GXO新增站点首批验收，以及Echo正式销售条款和首批交付，核对部署数量、选配费用与完整使用成本。", "待CO01公布完整任务规模或代码、LogLook出现真机和延迟复现后，再按相同任务与预算比较改进幅度。"], "coverage": "覆盖2026-10-26 11:27至2026-10-27 10:35（UTC+8）；LogLook补入10月23日近期研究，保留原始日期。重点公众号公开入口仍有滞后与访问缺口，不代表完整订阅。"}, {"date": "2026-10-26", "edition": "6条 · 产品产业4条／研究2条 · 延迟发送", "updated": "11:27", "intro": "NEURA新一代本体已进入训练设施，智元把训练、任务编排与多机运营整合为平台；相较此前的规划公告，本期出现了设施启用和平台正式发布。启元新增开发者计划与广州体验中心试营业。我们的判断是，竞争正在扩展到任务开发和用户触达，但试运营、研究演示仍不能代替长期成本和可靠性验证。", "items": [{"title": "海外新品｜NEURA推出4NE1 Gen 4，并启用逾2300平方米机器人训练设施", "date": "2026-10-22（近期重要补漏）", "body": "NEURA与慕尼黑工业大学在慕尼黑机场附近启用超过2300平方米的RoboGym，并发布4NE1 Gen 4。厂商称新机较前代轻20%，采用更纤细的结构、织物外皮和支持局部反射控制的Smart Limbs；Neuron AI融合视觉、触觉、力、声音及本体状态。新机已在该设施运行，量产仍在准备中。", "analysis": "训练设施与本体同步推出，有望缩短采数和迭代周期；绝对重量、价格、客户交期及长期任务数据尚未披露，量产准备不等于批量交付。", "sources": [{"label": "NEURA Robotics官方新闻页", "url": "https://neura-robotics.com/tum-robogym-munich-4ne1-gen4-launch/"}]}, {"title": "国内平台｜智元正式发布Genie Studio 2.0，打通任务开发与多机运营", "date": "2026-10-23", "body": "Genie Studio 2.0是一体化具身任务平台：Flywheel覆盖数据、训练、仿真和评测，Agent编排导航定位、推理及业务逻辑，Monitor负责多机状态、调度、告警和远程干预，并将异常数据回流训练。公司案例称，常州六台数控机床上下料项目从需求到产线验证用时14天。", "analysis": "统一平台可能减少交付中的工具拼接工作；14天案例为厂商自述，尚缺独立的成本、接管率和持续运行数据。", "sources": [{"label": "42HOW报道", "url": "https://test.42how.com/en/article/1631d33f-fed8-49b3-bf6a-6599275adc57"}]}, {"title": "国内生态｜启元开放开发者计划，广州金融城体验中心试营业", "date": "2026-10-24至25日；周末重要进展", "body": "启元24日发布“物理AI启仔计划”，提供开发平台、工具和算力支持，征集技能、交互人设及场景方案，开发者社区已上线。新浪财经25日报道，其位于尚品宅配广州金融城总部的体验中心开始试营业，展厅约800平方米，展示Q1、T1并提供改装与编程体验。", "analysis": "开发者供给与线下体验同步扩展，可能帮助验证家庭用户需求；算力额度、收费及许可尚不明确，试营业也不等于新增交付或家庭任务已可稳定自主完成。", "sources": [{"label": "新浪财经快讯", "url": "https://finance.sina.com.cn/7x24/2026-10-24/doc-iniwhxpq8097529.shtml"}, {"label": "金融城体验中心试营业报道", "url": "https://finance.sina.com.cn/roll/2026-10-25/doc-iniwmxsn2967156.shtml"}]}, {"title": "海外供应链｜FANUC将人形机器人零部件列入需求驱动因素", "date": "2026-10-23", "body": "FANUC截至9月30日的半年业绩说明显示，工厂自动化需求受到中国市场带动，中国机床需求强劲；人形机器人零部件与人工智能数据中心、半导体及新能源汽车一道，被列为需求驱动因素。这是供应链景气度的公司层面信号，并非人形整机产品发布。", "analysis": "披露说明人形机器人需求已进入头部自动化厂商的经营观察范围，但公司未单列相关收入、订单或终端装机量，不能把集团增长整体归因于人形机器人。", "sources": [{"label": "FANUC官方半年业绩说明", "url": "https://www.fanuc.co.jp/en/ir/announce/pdf/2026/reference202609_e.pdf"}]}, {"title": "国内研究｜λ0用人类示范训练机器人边走边操作", "date": "10月13日预印本、21日修订；近期研究", "body": "阿里巴巴Token Hub与高德团队提出λ0，将人类第一视角视频与全身、手部运动数据进行视角和动作对齐，用于训练人形机器人的全身移动操作；最后阶段仍加入原生机器人演示和任务对齐数据。在宇树G1四项真机任务中，每种方法合计测试40次，λ0完成率为62.5%，π0.5为40%。", "analysis": "这一路径可能降低全身操作数据完全依赖机器人遥操作的成本，但样本量有限，且仍依赖身体控制器和机器人后训练，不能解读为仅凭人类视频即可直接部署。", "sources": [{"label": "arXiv论文", "url": "https://arxiv.org/abs/2610.18950"}, {"label": "λ0项目页", "url": "https://lambdahumanoid.github.io/"}]}, {"title": "国内研究｜HandsOn检验灵巧操作，仿真任务仍有明显失败", "date": "10月19日预印本；10月26日报道，近期研究", "body": "清华等团队发布HandsOn仿真平台，包含66项人工验证任务和1.8万条仿真遥操作示范，并区分有示范的Core-50与无目标任务训练示范的Transfer-16。最佳受训多任务策略在Core-50成功率为29.1%；未经基准微调的GPT-6通过move_eef工具控制手掌和手指，在同组任务中成功率为5.2%。", "analysis": "该基准可定位接触、双手配合与目标保持中的失败；模型训练条件不同，结果不构成同预算比较。这里测的是仿真，真机仅有定性演示，不能外推实际部署或替代关系。", "sources": [{"label": "arXiv论文", "url": "https://arxiv.org/abs/2610.26765"}, {"label": "HandsOn官方代码库", "url": "https://github.com/TsinghuaC3I/HandsOn"}]}], "followups": ["G2 Max正式材料出现后核对新增能力、价格和交付；H2-X有完整演示原片或厂商回应后再核验事故原因与可靠性。", "NEURA与Genie Studio披露客户验收或长时运行数据时，复查接管率、任务成本和连续稳定性。", "启元公布开发者许可、算力额度及门店成交/交付数据时，复查开放范围与实际家庭使用反馈。"], "coverage": "覆盖2026-10-23 10:45至2026-10-26 11:27（UTC+8），完整回溯周末；补入10月22日NEURA新品及两项近期研究，保留真实事件日期。重点公众号公开入口存在滞后和访问缺口，不代表完整订阅。今日延迟发送。"}, {"date": "2026-10-23", "edition": "9条 · 产品产业6条／研究3条", "updated": "10:45", "intro": "宇树H2-X是一次新型号发布，本期补入10月21日的重要进展；现有展示仍不能代替实际作业和交付验证。MaxLoop、Humanoid机载整合及Cosmos巡检数据流程，分别推进采集反馈、设备集成和训练准备；我们的判断是，这些配套环节值得关注，但仍需用真实任务成本与接管率验证收益。", "items": [{"title": "国内新品｜宇树发布H2-X，展示新型号运动能力", "date": "2026-10-21；近期重要补漏", "body": "中国证券报报道，宇树通过“功夫传奇”视频正式发布H2-X，展示从4米平台落地、武术动作以及安保和救援场景。厂商称其站立工况续航约8小时，但未披露售价、交期及独立重复测试结果；该指标也不代表连续作业时长。", "analysis": "新型号扩大了运动能力展示范围；安保、救援仍属视频场景，实际自主程度、动作重复性和负载工况续航还需验证。", "sources": [{"label": "中国证券报报道", "url": "https://finance.eastmoney.com/a/202610213902709325.html"}]}, {"title": "海外采数｜Maxinsights推出MaxLoop，研发触觉采集手套", "date": "2026-10-22", "body": "Maxinsights发布MaxLoop质量反馈平台，称可把采数评分与纠正反馈缩短至同日。公司披露累计采集逾200万小时，其中150万小时已整理为训练可用数据，并与Genesis AI联合开发MaxGlove触觉手套；后者目前仍处研发阶段。", "analysis": "同日反馈可能缩短数据返工周期，但采集量不等于交付量，独立训练收益和成本仍待验证。", "sources": [{"label": "Maxinsights公司新闻稿", "url": "https://www.businesswire.com/news/home/20261022672609/en/"}, {"label": "量子位报道", "url": "https://www.qbitai.com/2026/10/504800.html"}]}, {"title": "海外硬件｜Humanoid把两台机载计算机整合为一台Thor", "date": "2026-10-21；近期进展", "body": "Humanoid宣布扩大与NVIDIA合作，下一代机器人架构将原有两台机载计算机整合为一台Jetson Thor，厂商称可维持原有计算能力。方案同时结合Isaac OS与Holoscan传感器数据链路，以减少中央处理器和图形处理器之间的数据复制。", "analysis": "硬件整合有望降低系统复杂度，但公告没有整机功耗、端到端时延及任务成功率对比，也不代表已经量产供货。", "sources": [{"label": "Humanoid官方公告", "url": "https://thehumanoid.ai/humanoid-expands-collaboration-with-nvidia-to-power-its-next-generation-of-humanoid-robots/"}]}, {"title": "海外设施｜Generative Bionics规划意大利机器人训练基地", "date": "2026-10-21；近期进展", "body": "Generative Bionics与AMD合作规划三个机器人训练基地。首个意大利基地计划占地5000平方米，目标于2027年第四季度启用，将GENE.01真实工业操作、数字孪生和AMD算力结合，先在基地训练，再进入客户环境验证。", "analysis": "集中训练设施可能加快工业任务迭代，但当前仍是建设计划；投资额、机器人数量及另外两处基地信息均未披露。", "sources": [{"label": "Generative Bionics官方公告", "url": "https://news.gbionics.ai/?article=data-factory&lang=en"}]}, {"title": "国内供应链｜图达通与伽利略合作开发机器人感知系统", "date": "2026-10-21；近期进展", "body": "图达通与伽利略签署战略合作协议，计划把激光雷达感知能力与机器人平台结合，目标场景包括电力巡检、安防、末端配送及应急救援。伽利略提供的平台覆盖可变构型、四足和人形机器人，但公告未列出具体雷达型号。", "analysis": "合作扩大了激光雷达面向机器人场景的验证入口，但战略协议不等于供货订单，采购数量、收入和验收结果均未知。", "sources": [{"label": "图达通署名合作公告", "url": "https://www.ne-time.cn/web/article/40080"}]}, {"title": "海外工具｜Cosmos增加数据生产流程，ANYbotics用于巡检训练", "date": "2026-10-21；近期进展", "body": "NVIDIA为Cosmos增加训练工具、仿真检查点和Data Factory蓝图。ANYbotics已用相关流程生成超过1500段合成视频，并通过Encord验证输出，用于训练工业巡检机器人识别液体泄漏等环境变化；这些片段并非真实部署工时。", "analysis": "工具链开始进入具体巡检训练流程，但实际误报率、训练成本及现场收益未披露，合成数据规模不能替代业务验证。", "sources": [{"label": "NVIDIA官方工具与应用说明", "url": "https://blogs.nvidia.com/blog/cosmos-open-train-evaluate-deploy-world-models/"}]}, {"title": "国内研究｜智元第四期数据集增加任务推理过程", "date": "2026-10-22", "body": "AGIBOT WORLD 2026第四期Physical Reasoning发布，覆盖9类推理和3档难度，增加数量、遮挡、位置占用及任务进度变化，例如补货前统计已有物品、寻找物体时记录已检查抽屉。官方数据仓库已出现对应目录。", "analysis": "增加任务状态变化，有助于研究何时采取哪种动作；尚无统一下游成功率增益，仓库采用CC-BY-NC-SA非商用许可。", "sources": [{"label": "文汇报发布报道", "url": "https://www.jfdaily.com/staticsg/res/html/web/newsDetail.html?id=1199086"}, {"label": "官方数据目录与许可", "url": "https://huggingface.co/datasets/agibot-world/AgiBotWorld2026/tree/main/PhysicalReasoning"}]}, {"title": "国内研究｜CEL让机器人从同伴成功操作中改进", "date": "论文2026-10-19首发、10-21修订；10-22报道", "body": "清华、智元等的CEL预印本先用专家数据初始化策略，再由失败场景检索机器人群中的成功片段来更新。96台机器人参与手机包装训练后，在未参与采集的机器人上测试120次，成功率由79.2%提升至98.3%。", "analysis": "群体经验可帮助修复失败，但仍需人工标记成败、重置环境；实验限于同一平台，增加机器人也增加总数据，并非同预算比较。", "sources": [{"label": "CEL预印本v2", "url": "https://arxiv.org/abs/2610.25736"}]}, {"title": "海外研究｜OpenTac用可定制触觉皮肤改善接触操作", "date": "2026-10-22预印本；10-23索引", "body": "OpenTac提出可定制电阻式触觉皮肤，通过凸起结构感知压力和剪切，并开放设计、读出硬件和软件。SO-101真机在无视觉插头插入任务中，各条件使用100次示范、测试50次；触觉加关节信息成功率为62%，仅关节基线为36%。", "analysis": "触觉改善了接触操作，但凸起也改变接触力学，增益不能全归于剪切信号；材料存在漂移与迟滞，长期工业寿命尚未验证。", "sources": [{"label": "OpenTac预印本", "url": "https://arxiv.org/abs/2610.31661"}, {"label": "实验与代码入口", "url": "https://opentac.github.io/results/"}, {"label": "OpenTac代码", "url": "https://github.com/opentac/opentac"}]}], "followups": ["H2-X公布售价、交期或独立测试时，复查重复动作、负载下续航及自主程度。", "智元Genie Studio 2.0正式发布后核对能力与开放范围；数据集须进一步检查文件完整性和使用许可。", "训练基地启用、感知合作落单及巡检现场测试出现时，核对采购量、验收结果、误报与接管成本。"], "coverage": "检索覆盖2026-10-22 10:39至2026-10-23 10:45（UTC+8），并补入10月21日未报重要进展及近期CEL研究。公众号公开入口存在滞后与访问缺口，未声称完整订阅。"}, {"date": "2026-10-22", "edition": "7条 · 产品产业6条／研究1条", "updated": "10:39", "intro": "墨宝正式开放预订，特斯拉披露Optimus开始产线生产，但两者分别仍缺交期和爬坡产量，不能等同于批量交付。武汉零售仓已有运营订单；判断这类项目能否复制，还需要接管与维护成本。Isaac工具更新、S1采数手套和Flora标注模型分别补足开发、采集和整理环节，显示机器人产品之外的配套工具也在持续推出。", "items": [{"title": "国内新品｜墨宝正式发布，面向家庭陪伴开启预订", "date": "2026-10-21", "body": "墨甲在芜湖发布0.9米、22个自由度的墨宝并开启全球预订，功能覆盖儿童识物问答、故事与英语互动、长辈陪聊提醒，以及家庭成员识别和记忆。现场35名天使用户获得一年免费体验，这不属于付费交付量；MoAgent演示了接收临时问询后继续执行任务。", "analysis": "家庭成员识别和长期记忆让产品定位更具体；后续需看真实家庭使用反馈、最终售价与交付安排，免费体验不代表已完成商业验证。", "sources": [{"label": "墨甲正式发布公告", "url": "https://www.prnasia.com/story/552626-1.shtml"}]}, {"title": "海外制造｜特斯拉称Optimus已在弗里蒙特产线开始生产", "date": "美国10月21日财报；北京时间10月22日", "body": "特斯拉第三季度官方更新称，弗里蒙特高产量设计产线已开始生产Optimus，产出的是公司首批生产级机器人。更新文件的产能表将加州Optimus状态列为“早期爬坡”，得州产线仍在建设中，两处均未填写机器人产能数字，硬件和制造流程还将继续迭代。", "analysis": "生产级机器人下线说明进入产线爬坡阶段，但不等于已经达产或客户批量交付。后续应核对实际产量、良率、单位成本和运行表现。", "sources": [{"label": "特斯拉Q3官方更新第5页", "url": "https://assets-ir.tesla.com/tesla-contents/IR/TSLA-Q3-2026-Update.pdf"}]}, {"title": "国内落地｜智元披露武汉江滩零售仓运营订单", "date": "10月20日披露；截至10月19日数据，近期重要补漏", "body": "智元、武汉文旅集团和中云微迅合作，在汉口江滩江遇桥墩电影营地部署远征A3 Ultra，承担零食饮品识别、抓取和交付。厂商披露，截至10月19日设备连续运营18天、每天约8小时，累计完成827单，覆盖十余款商品，抓取环节成功率超过97%。", "analysis": "连续订单比单次演示更接近真实运营，但抓取成功率不等于端到端履约率。人工接管、补货维护成本和利润均未披露，不能据此认定无人化。", "sources": [{"label": "投资界刊载项目披露", "url": "https://news.pedaily.cn/202610/570563.shtml"}]}, {"title": "海外平台｜Isaac更新开发工具，Agile ONE SN计划明年供货", "date": "2026-10-21", "body": "NVIDIA与Agile Robots公布Agile ONE SN参考人形机器人，设备预装Isaac GR00T并搭载Jetson Thor，试图把数据采集、仿真、训练和部署接入同一流程，计划于2027年初提供。同期，Isaac Lab 3.0正式可用，Isaac OS推出首个公开测试版。", "analysis": "平台整合有望减少开发者拼装工具的工作。软件已推出，参考整机则计划2027年初提供；价格、实际提效和安全集成效果仍待验证。", "sources": [{"label": "NVIDIA官方平台发布", "url": "https://blogs.nvidia.de/nvidia-advances-isaac-platform-for-general-purpose-robotics/"}]}, {"title": "海外应用｜Bear发布KINO-2，连接示范学习与搬运流程", "date": "2026-10-21", "body": "Bear发布KINO-2机器人学习平台，可把人类任务示范转成KR1操作技能，并支持自研模型和外部基础模型，当前用于超市退货及仓储料箱操作试点。公司称，经Isaac OS、TensorRT和量化联合优化，内部测试中的GR00T推理时间由未优化部署时约500毫秒降至约60毫秒。", "analysis": "推理时延下降可能改善动作响应，但数据仅对应特定内部系统，不能归因于单一软件。试点规模、人工接管率和端到端任务成功率尚未披露。", "sources": [{"label": "Bear产品与工程公告", "url": "https://fl.bearrobotics.ai/blog/bear-robotics-launches-kino-2"}]}, {"title": "海外采数｜Origami S1手套同步记录手指动作与触觉", "date": "2026-10-21发布", "body": "Origami S1手套以编码器记录20个手指关节角度，并同步采集指尖和手掌压力、腕部视频，在手指被遮挡时仍可保留动作数据。其关节结构与公司自研机器人手对应，软壳用于适配不同手型。公司称产品已开始量产，但使用前仍需针对每名采集者调整和校准。", "analysis": "动作与触觉同步可减少灵巧手数据对纯视觉的依赖，但人机指尖形状及接触压力仍有差异。售价、出货时间和跨用户耐久性尚未公布。", "sources": [{"label": "Origami技术与产品说明", "url": "https://www.origami-robotics.com/blog/a-million-hours-of-what"}]}, {"title": "海外研究｜Flora把操作视频转成可筛选、可评分的训练数据", "date": "10月20日对外介绍、10月21日报道；模型卡标注10月15日，近期研究", "body": "NVIDIA Flora把操作视频切成动作片段、生成说明并评价执行质量，供数据筛选和强化学习使用，输出是标注而非机器人动作。团队称512张GB300每天可标注20万小时视频，这是处理吞吐；与GPT-6 Astra比较仅针对机器人标注，指标互有胜负。", "analysis": "方法可能降低大规模视频整理成本，但结果仍来自团队基准，尚无独立生产任务收益验证。Captioner和Rewarder模型卡限定为非商用研究开发用途。", "sources": [{"label": "NVIDIA研究项目与论文入口", "url": "https://research.nvidia.com/labs/gear/flora/"}, {"label": "Captioner模型卡与许可", "url": "https://huggingface.co/nvidia/Flora-Captioner"}]}], "followups": ["跟踪墨宝最终零售价、付费订单和实际交付时间；复查武汉零售仓端到端履约率、人工接管频次及补货维护成本。", "跟踪Optimus早期爬坡的实际产量、制造良率、单位成本和对外交付证据；在官方披露前不把产线启动写成规模达产。", "等待智元自10月22日起七个工作日内的新品系列正式结果，并核验11月2日至3日六台G2便利店24小时直播的完整记录、接管情况和失败类型，不把计划写成已发生。"], "coverage": "检索覆盖2026-10-21 10:33至2026-10-22 10:39（UTC+8）；另补入10月20日披露的武汉运营数据及近期Flora研究。重点公众号公开入口存在索引滞后，未声称完整订阅。"}, {"date": "2026-10-21", "edition": "6条 · 产品产业4条／研究2条", "updated": "10:33", "intro": "制造端出现两种不同进度：舍弗勒已让6台人形机器人进入关节组件工厂，AGCO则把Digit试点安排到2027年，但两者均未披露接管率或效率验收结果。家庭机器人开始用可退款预约测试需求，不过Voxel计划2028年交付，现阶段仍属开发原型。两项研究都尝试降低机器人适配新本体或接触任务的门槛，但证据分别受本体条件和纯仿真验证限制。", "items": [{"title": "国内落地｜舍弗勒太仓工厂让人形机器人组装关节", "date": "2026-10-20公告", "body": "舍弗勒宣布启用太仓约7500平方米人形机器人灯塔工厂，涵盖零部件制造、训练采数和数字孪生。6台人形机器人已在5个工位参与备料分拣、装配、检测及包装，工厂开始量产直线和旋转执行器等关节组件；这不是完整人形机器人整机制造。", "analysis": "机器人参与生产自身上游组件，为工艺和训练数据闭环提供了真实场景；但节拍、良率、人工接管率及回本周期均未披露，不能据此判断无人化或效率提升。", "sources": [{"label": "舍弗勒公告", "url": "https://www.schaeffler.de/en/news_media/press_releases/press_releases_detail.jsp?id=88222851"}]}, {"title": "海外落地｜AGCO签约引入Digit，2027年开始工厂试点", "date": "2026-10-20", "body": "农机制造商AGCO与Agility Robotics签署商业协议，计划2027年在美国堪萨斯州Hesston工厂试点Digit。初期任务包括零件分拣堆叠和料箱存放，公告同时介绍了配套的Arc车队管理平台。应用范围是农机制造厂内部，并非让人形机器人进入田间作业。", "analysis": "协议把Digit扩展至农机制造场景，但台数、金额和试点周期尚未公布；减轻劳动负担、提高效率仍是项目目标，而非已经通过验收的结果。", "sources": [{"label": "Agility与AGCO公告", "url": "https://www.agilityrobotics.com/content/agco-and-agility-robotics-advance-smart-manufacturing-with-humanoid-robot-pilot-in-hesston-kansas-facility"}]}, {"title": "海外新品｜Voxel开启家庭机器人预约", "date": "2026-10-20发布；2026-10-21核验官网", "body": "Tuesday Labs发布双足家庭机器人Voxel，定位收拾和查找物品、取物及照料植物。美国用户可支付200美元预约，正式下单前可退款；预计整机2万美元，最终价未定，计划2028年起交付。预约协议明确：当前仍是开发原型，交付前可能大幅改版，时间也可能延后。", "analysis": "可退款预约更接近需求测试，而非现货销售或量产证明。跨家庭环境成功率、人工辅助比例，以及儿童宠物安全、隐私处理等关键指标仍未披露。", "sources": [{"label": "产品官网", "url": "https://tuesdaylabs.com/robot"}, {"label": "预约与产品阶段条款", "url": "https://tuesdaylabs.com/reservation-terms"}]}, {"title": "国内供应链｜智微智能披露Thor控制器新增智元客户", "date": "2026-10-20投资者活动记录", "body": "智微智能在投资者活动记录中称，智擎Thor机器人大脑控制器新增智元合作客户，并进入其首批A链供应商，同时与优必选联合开发。公司产品覆盖大脑、小脑及大小脑一体控制器，并表示一体化方案有助于降低成本、缩小设备体积。", "analysis": "披露显示控制器供应商正争取整机客户协同开发，但目前仅有上市公司单方陈述；订单金额、出货规模和实际降本比例均未公开，客户关系仍待交叉确认。", "sources": [{"label": "智微智能投资者活动记录原文", "url": "https://vip.stock.finance.sina.com.cn/corp/view/vCB_AllBulletinDetail.php?id=12650680&stockid=001339"}]}, {"title": "海外研究｜Dream-1尝试把操作能力复用到新机器人", "date": "2026-10-19海外发布；近期重要补漏", "body": "Dream Labs发布Dream-1世界动作模型并开放应用程序接口，起价为每小时3美元。模型联合预测视频和动作，给出夹爪目标位置及开合状态，再由各机器人自身的逆运动学求解器转换为关节动作。厂商展示了27种未见仿真本体和4种真实本体的零样本评测。", "analysis": "对双臂平行夹爪，这种接口可能减少适配成本；但依赖本体求解器，末端目标不保证整臂绕障路径可行。每小时起价也不是每次任务成功的总成本。", "sources": [{"label": "Dream Labs技术说明与API入口", "url": "https://dreamlabs.ai/research/dream-1/"}]}, {"title": "国内研究｜TacTalent把触觉变成图像，测试Astra接触操作", "date": "10月19日UTC提交，预印本；近期补漏", "body": "清华与高德作者把视觉式触觉图像输入Astra，用少量成功演示引导操作。两套基准共19项任务，每种输入设置采样210个仿真场景，多数任务仅10次。UniVTAC视触觉平均成功率93.8%，纯视觉76.3%；尚未验证真机，不能直接推论全面超过专用策略。", "analysis": "该方法可能让通用模型利用接触信息，但视触觉完整接口响应中位14秒，含等待、不含仿真执行；一轮可给多个动作，仍需验证真实接触与控制延迟。", "sources": [{"label": "论文全文", "url": "https://arxiv.org/html/2610.26846v1"}, {"label": "作者代码", "url": "https://github.com/ccyydd/TacTalent"}]}], "followups": ["核验墨宝2026-10-21发布活动的正式结果，重点记录产品形态、价格、交付时间及演示是否为真机连续运行。", "补看NEURA在GTC的完整演示，区分模型直接输出动作、调用预制技能与人工遥控，并确认本体和任务条件。", "持续追踪舍弗勒、AGCO等工厂项目的人工接管率、任务节拍、良率及连续运行时长；任一指标公开后复查商业化判断。"], "coverage": "检索覆盖2026-10-20 10:33至2026-10-21 10:33（UTC+8）；另补入Dream-1和TacTalent近期重要研究，均非今日新发布。公众号公开入口存在更新滞后，未声称完整订阅。"}, {"date": "2026-10-20", "edition": "6条 · 产品产业4条／研究2条 · 延迟补发", "updated": "10:33", "intro": "本期延迟补发，新闻检索截止于今日10:33（UTC+8）。乐聚与兆丰的15台机器人上料项目提供了产线应用证据，但30多秒节拍与未来15秒目标仍需分清；这是此前漏收的重要进展。Figure转向长时行走压力测试，通用模型研究则暴露精密接触与耗时限制：判断可用性，需要把任务表现、人工介入和连续作业条件一起看。", "items": [{"title": "国内落地｜乐聚与兆丰将15台夸父用于产线上料", "date": "2026-10-15发布，10月16日报道；近期重要补漏", "body": "兆丰官网确认与乐聚发布小件上料方案并揭牌示范基地，向OpenLET社区捐赠真机在环数据。第一财经记者在厂内看到15台夸父分布于不同工位，单次动作需30多秒；报道给出的98%作业成功率属于报道及项目方口径。兆丰董事长称，抓零件曾做约1.5万次训练。", "analysis": "半年至一年压缩至15秒只是目标。缺少失败、接管和长期验收日志，现阶段不能推导回本周期或全面替代人工。", "sources": [{"label": "兆丰官方公告", "url": "https://www.hzfb.com/news/newsinfo/379.html"}, {"label": "第一财经现场采访", "url": "https://www.yicai.com/news/103397266.html"}]}, {"title": "国内新品｜PhyHand全直驱灵巧手亮相广交会", "date": "2026-10-15至19日广交会一期；10月18日现场报道", "body": "界面新闻现场报道，动易科技首发PhyHand系列全直驱拟人灵巧手，配置23个主动自由度，现场演示石头剪刀布；公司还展示PHYBOT D工业巡防方案。其市场负责人称，海外采购商更希望获得综合解决方案，而不只是观看机器人本体动作。", "analysis": "23自由度是结构规格，手势演示也不能证明精密装配能力。定价、交付期、抓力、触觉与耐久数据均未核验。", "sources": [{"label": "界面新闻现场报道", "url": "https://www.jiemian.com/article/15203405.html"}]}, {"title": "海外本体｜Figure 03披露九天行走压力测试", "date": "2026-10-19厂商更新及媒体报道", "body": "Humanoids Daily与Interesting Engineering转述Figure创始人Brett Adcock称，Figure 03在跑步机上的行走测试已持续9天，累计348英里、约560公里和120万步，发布消息时测试仍在继续。测试目的为通过重复行走暴露潜在硬件故障。", "analysis": "数据属于媒体转述厂商自述，并非独立耐久验证；协议、维护、供电和人工介入均未披露，也不代表单次充电运行九天。", "sources": [{"label": "Humanoids Daily转述厂商更新", "url": "https://www.humanoidsdaily.com/news/figure-03-nine-day-treadmill-million-steps"}, {"label": "Interesting Engineering报道", "url": "https://interestingengineering.com/ai-robotics/figure-03-humanoid-robot-treadmill-test"}]}, {"title": "海外市场｜FR-NIA以可定制表情切入陪伴机器人", "date": "2026-10-19报道；官网计划10月20日启动众筹", "body": "Figurobot官网展示FR-NIA表情陪伴机器人，头部共10个自由度，包括颈部3个、面部7个；配套应用支持录制动作、调整关键帧和自定义表情。截至检索时，官网仍处预约阶段：支付20美元可锁定699美元众筹价，支付1美元对应799美元。", "analysis": "预约不等于购买或交付，产品款和运费仍需另付。长期互动记忆、任务效果及最终交付时间尚无可核验证据。", "sources": [{"label": "Figurobot官方规格与预约条款", "url": "https://us.figurobot.com/"}]}, {"title": "国内研究｜会抓取仍难插装：Astra真机评测呈现任务差异", "date": "2026-10-15 UTC提交；近期专题补漏，预印本", "body": "《Has GPT-6-Astra Achieved Embodied Intelligence?》覆盖12项基准和8种真机配置。真机实验中，刚性抓放18次、成功17次；三个平台的插头插入合计11次、成功0次。Astra负责慢速高层判断并经控制接口输出动作，没有替代底层实时控制。", "analysis": "真机有人工编写的工具与安全上下文，操作者全程持急停；仿真还允许读取演示并延长步数。样本较小，不能据此作同预算胜过专用策略的结论。", "sources": [{"label": "论文全文及真机实验", "url": "https://arxiv.org/html/2610.22471v1"}]}, {"title": "海外研究｜把探索保存为程序：RAX减少重复决策开销", "date": "2026-10-15 UTC提交；近期专题补漏，预印本", "body": "《Scaling Online Exploration for Robot Agents》让冻结的编程智能体通过控制与视觉接口探索，再写成程序和可复用技能，无需遥操作动作演示或策略训练。Franka操作空气炸锅的案例中，编译后程序计算耗时18秒，机器人动作耗时2.5分钟；18秒并非完整任务时间。", "analysis": "探索期曾撞相机触发安全停止，也有操作员重置与调整物体。程序复用可能减少重复计算，但需验证布局变化和异常恢复，不能称全程无人。", "sources": [{"label": "论文全文（表9及附录14.2）", "url": "https://arxiv.org/html/2610.22496v1"}, {"label": "作者公开代码", "url": "https://github.com/robot-agent-exploration/rax"}]}], "followups": ["跟踪乐聚与兆丰方案的实际节拍、换型时间、接管频率及长期验收数据；出现独立运行日志后复查商业可行性。", "核验FR-NIA正式众筹价格、交付承诺，并跟进10月21日墨宝发布；预约或预告不作为上市、交付结果。", "继续观察Astra与RAX在不暂停环境中的接触验证、端到端总耗时、布局变化适应及人工恢复次数。"], "coverage": "覆盖窗口为2026-10-19 11:10至10月20日10:33 UTC+8，并补回乐聚与兆丰、PhyHand及两篇10月15日提交的重要研究。具身智能之心公开入口可见内容更新至9月30日，存在滞后；新智元公开流不足以确认完整覆盖；量子位相关赛事原文存在访问缺口。启元金融城店尚无新开业证据，未把旧预告写成结果。"}, {"date": "2026-10-19", "edition": "6条 · 产品产业5条／研究1条 · 周末回溯", "updated": "11:10", "intro": "本期延迟发送，汇总周末进展并补入两条此前未收录的重要消息。UniUni和RP1分别把表演编队与机器人研发的工具链做得更完整，采购时仍需验证现场稳定性和可复现程度。Plim、墨宝与FF Nova呈现家务陪伴、交互陪伴和开发教育三种定位，当前不能用功能展示代替交付与任务表现。", "items": [{"title": "国内产品｜宇树发布UniUni集群控制工具", "date": "2026-10-16发布｜周末回溯", "body": "据宇树产品资料，UniUni支持G1、H2及Windows、macOS，可绘制二维和三维轨迹、按时间线编排动作，并提供点云建图定位、温度异常监测、急停、动作库和自然语言编排。运营者可把编队设计与现场设备监控放在同一桌面工具中。", "analysis": "这有望减少编队表演的准备工作，但仍需现场验证同步误差、断网恢复和实际人力节省；不能推定它已支持任意工业多机任务。", "sources": [{"label": "宇树官方产品页", "url": "https://uniuni.unitree.com/"}, {"label": "新浪科技发布日期", "url": "https://finance.sina.com.cn/jjxw/2026-10-16/doc-inivmazq1643049.shtml"}]}, {"title": "国内产品｜RP1公开从硬件到训练部署的开发栈", "date": "2026-10-16发布材料｜周末回溯", "body": "RP1曾于9月28日在IROS亮相，本次增量是发布开源平台与公开仓库。总仓列出机械CAD、电路PCB与物料清单、装配文档、关节固件、机器人模型及训练部署子仓入口，并支持24、28、30和42自由度配置。", "analysis": "分层资料便于团队审查和修改研发平台；本次未逐文件复现，各子仓版本、许可及硬件配置需分别核对，价格与交付也不能从开源推定。", "sources": [{"label": "RoboParty官方仓库", "url": "https://github.com/Roboparty/RP1"}, {"label": "公司发布材料", "url": "https://www.europapress.es/comunicados/internacional-00907/noticia-comunicado-acabaron-cajas-negras-roboparty-lanza-rp1-codigo-abierto-pila-completa-20261016110143.html"}]}, {"title": "海外新品｜Plim把自主家务与远程陪伴放进同一产品", "date": "2026-10-17报道｜周末重要进展", "body": "慕尼黑Devanthro已确认更名为Plim Robotics。Plim产品页展示自主家务和Step-in远程操作两种模式，远程模式可呈现操作者的面孔、声音与动作；机器人采用三轮全向底盘和两指夹爪，厂商标称续航两小时并可自动回充。", "analysis": "远程操作提供亲友或护理人员参与的入口，但目前仅登记意向，售价、交付日期、任务成功率和人工接管频次均未披露。", "sources": [{"label": "Plim官方产品页", "url": "https://plim.com/meet-plim"}, {"label": "公司更名公告", "url": "https://www.devanthro.com/devanthro-is-now-plim-robotics/"}]}, {"title": "国内预告｜墨宝预告10月21日首发并开启预订", "date": "2026-10-16公告｜10月21日待发布", "body": "奇瑞墨甲公告将于10月21日在芜湖发布家庭陪伴人形机器人墨宝并开启预订。发布内容预计涉及语言交互、视觉识物、日程提醒、长时记忆和MoAgent；这些仍是功能预告，售价、正式参数及交付计划尚未给出。", "analysis": "产品定位从商用接待延伸到家庭陪伴，但现有材料不能证明其具备家务操作能力，也不能把开启预订等同于现货交付。", "sources": [{"label": "墨甲公司新闻稿", "url": "https://www.prnasia.com/story/552003-1.shtml"}]}, {"title": "海外新品｜FF Nova以2490美元切入开发与教育市场", "date": "2026-10-15公告｜近期补漏", "body": "FF投资者官网列出FF Nova与Nova Mini联合发布。Nova官方商店标价2490美元，具备20个自由度，双足本体约2.8千克并配可拆卸移动底座，同时提供Python软件开发工具包和从仿真到真机的工作流。", "analysis": "其规格和价格更接近科研教育平台而非全尺寸家务机器人；标价不代表包含服务和部署的总成本，实际交付量与任务成功率也未核验。", "sources": [{"label": "FF Nova官方规格与价格", "url": "https://shop.ff.com/products/ff-nova"}, {"label": "FF公司公告目录", "url": "https://investors.ffai.com/press-releases/"}]}, {"title": "海外研究｜让模型记住前序操作：Astra在RoboMME上的能力与边界", "date": "2026-10-12 UTC提交｜近期专题补漏，预印本", "body": "研究使用冻结的GPT-6 Astra直接输出末端路点和夹爪指令，不针对RoboMME训练，并保留完整操作历史。在16项仿真任务、800回合中成功率为92.1%；每次调用平均耗时18.3秒，主要失败包括提前宣告完成及按键时机错误或误按。", "analysis": "该结果提示通用模型可承担部分依赖历史的操作流程，但模拟器会暂停等待调用；不暂停的真机环境下，成功率、成本和安全性仍需重新验证。", "sources": [{"label": "论文全文", "url": "https://arxiv.org/html/2610.17350v1"}, {"label": "作者代码和日志", "url": "https://github.com/jackbjed/embodied-astra-robomme"}]}], "followups": ["10月21日墨宝发布后核对价格、交付安排和功能边界；启元金融城店10月15日试营业目前仍只有旧预告，继续寻找实际开业及交付证据。", "Plim与FF出现实际交付或独立测试后，复查任务成功率、人工接管次数、续航和包含部署服务的总成本。", "UniUni后续重点验证现场网络异常、同步误差与急停机制；Astra研究重点验证环境不暂停时的成功率和动作时延。"], "coverage": "检索覆盖2026-10-16 11:06至2026-10-19 11:10（UTC+8），包含整个周末；另补入10月15日FF产品和10月12日UTC提交的Astra研究，均非今日新发布。重点公众号公开索引有滞后与访问缺口，启元金融城店实际开业和新增交付未获核验。"}, {"date": "2026-10-16", "edition": "6条 · 产品产业4条／研究2条", "updated": "11:06", "intro": "本期延迟发送，合并昨天未发送期间的重要进展。Digit 5确认快充电池技术供应商，把续航竞争延伸到补能停机时间；NOVA21与TOMO则分别瞄准灵巧操作研发和教育互动。两项研究尝试解决接触时让步与移动取物站位问题，仍需区分小规模真机验证和可持续部署。", "items": [{"title": "国内新品｜万拿NOVA21灵巧手", "date": "10月15日发布", "body": "万拿在香港秋季电子产品展发布面向科研开发的NOVA21灵巧手。厂商材料称其具有21个全主动旋转直驱自由度和16个力传感器，覆盖指尖、指腹三维触觉与掌心法向力，并支持力控、反驱、快换手腕及多种控制接口。", "analysis": "较完整的触觉与控制接口有利于科研集成，但现有来源属于商讯转载，价格、耐久性和量产交付均未获独立验证。", "sources": [{"label": "厂商发布材料／界面商讯", "url": "https://www.jiemian.com/article/15194944.html"}]}, {"title": "海外供应链｜Digit 5选择Nyobolt快充电池", "date": "10月15日公告", "body": "Agility宣布为Digit 5选择Nyobolt快充电池技术，目标续航90分钟、充电9分钟，并将运行与充电时间比由Digit 4的2:1提高至10:1。采用该电池的早期客户版本预计2027年上半年可用，随后6至9个月扩大供应。", "analysis": "快充若能在真实负载下成立可明显提升设备利用率，但每日工作时长仍是公司目标，温升、循环衰减和自动回充耗时尚待实测。", "sources": [{"label": "Agility官方公告", "url": "https://www.agilityrobotics.com/content/agility-robotics-selects-nyobolt-as-its-ultra-fast-charging-battery-technology-partner-for-digit-5"}]}, {"title": "国内新品｜Rice Robotics推出教育机器人TOMO", "date": "10月15日发布", "body": "Rice Robotics HK发布轮式人形机器人TOMO，配备表情面部、胸前互动屏和两指平行夹爪，定位互动阅读、科学技术工程数学教育、编程及有人监督的机器人探索。Rice Robotics HK同时加入FLAIR平台，合作探索教育与制造场景的训练验证。", "analysis": "这是一款面向互动教学与受监督探索的产品，实际采用仍需核验学校交付、售价及儿童接触安全，不能据发布材料推定可无人值守。", "sources": [{"label": "Axonex公司新闻稿", "url": "https://rss.globenewswire.com/news-release/2026/10/15/3381644/0/en/axonex-ai-group-joins-flair-s-embodied-ai-international-applications-hub-and-launches-education-humanoid-tomo.html"}]}, {"title": "中外合作｜Cerence与吉利将座舱语音能力用于服务机器人", "date": "10月15日公告", "body": "Cerence宣布与吉利把既有智能座舱合作扩展至机器人，并在巴黎车展演示人形机器人的多语言交互，语音识别可同时支持法语、英语和普通话。此次增量主要是将座舱交互技术迁移至服务机器人，而非运动策略或自主操作升级。", "analysis": "成熟座舱语音栈可能缩短多语言交互开发周期，但噪声识别率、端到端时延、动作执行成功率及规模交付均未公布。", "sources": [{"label": "Cerence官方新闻稿", "url": "https://www.globenewswire.com/news-release/2026/10/15/3381290/0/en/cerence-ai-and-geely-advance-human-machine-interaction-through-robotics-technology-services-partnership.html"}]}, {"title": "海外研究｜C-GMT：机器人跟随动作时也能顺着外力让步", "date": "10月16日arXiv新列表｜预印本", "body": "C-GMT冻结预训练通用动作跟踪器，在参考动作前加入小型适配模块，根据本体感知历史修正动作，使机器人被拉住或接触物体时能够顺势让步。作者展示了仿真及Unitree G1上的遥操作、舞蹈、插入和开门实验。", "analysis": "这类方法有望使全身运动更适合接触环境，但不等于安全认证；项目页代码仍标注即将开放，跟踪精度、柔顺性与失稳边界需要进一步验证。", "sources": [{"label": "作者项目页及真机演示", "url": "https://venki1899.github.io/c-gmt/"}]}, {"title": "海外研究｜MoCaP：从人类视频找到移动取物的站位", "date": "10月14日UTC提交，10月15日北京时间｜预印本", "body": "MoCaP从日常人类视频提取物体空间记忆和接近姿态线索，再结合机器人当前观测，调用既有感知、运动与执行工具，寻找底盘可停且机械臂能够触及目标的位置。作者在同一室内环境完成两个移动操作任务的真机验证。", "analysis": "视频中的站位经验可辅助移动操作规划，但验证任务和环境有限，且依赖现成工具链，不能视为跨家庭通用或直接视频模仿。", "sources": [{"label": "arXiv作者摘要", "url": "https://arxiv.org/abs/2610.20998"}]}], "followups": ["复查Digit 5在真实任务负载下的连续工作时间、自动回充占用、温升，以及高频快充后的电池循环老化。", "跟踪NOVA21灵巧手的实际交付时间与价格，并核验TOMO在儿童接触、夹持和有人监督场景中的安全测试。", "核验启元10月15日金融城店是否实际开业，以及门店展示、销售和交付分别达到何种阶段。"], "coverage": "覆盖2026-10-14 18:02至2026-10-16 11:06（UTC+8）。重点公众号公开索引存在滞后与访问缺口；启元金融城店实际开业和交付尚待核验。Astra未获得窗口内新的可核验真机结果，未重复旧回顾。"}, {"date": "2026-10-14", "edition": "6条 · 产品产业5条／研究1条 · 延迟补发", "updated": "18:02", "intro": "本期延迟补发，合并昨天漏发期间的重要进展。爱仕达推出科研本体及制造服务，Physical Intelligence开放模型微调与推理API，机器人开发正增加可直接采购或调用的基础能力。京东的零部件采购平台与ABB的示范学习工具链，则分别尝试降低供应链匹配和现场部署成本；实际效果仍需交付与连续运行数据验证。", "items": [{"title": "国内新品｜爱仕达ASD-S2", "date": "2026-10-13", "body": "爱仕达在上海生态伙伴大会揭牌具身智能创新中心，并发布面向科研及具身算法验证的ASD-S2。公司披露该机型具有31个自由度、单臂负载5公斤，同时提出覆盖核心部件、装配测试和批量交付的OEM、ODM制造服务。", "analysis": "从单一本体延伸至制造服务有助于承接外部方案，但现有资料未核验批量交付能力、连续运行成功率及实际客户采用情况。", "sources": [{"label": "证券时报", "url": "https://www.stcn.com/article/detail/4215143.html"}]}, {"title": "海外产品｜Physical Intelligence API beta", "date": "2026-10-13", "body": "Physical Intelligence开放API测试版，合作伙伴可上传机器人数据，使用其托管算力微调模型，再经托管网关执行推理。官方案例分布于日本、瑞士和美国，展示采集演示、训练测试以及补充失败数据后继续迭代的流程。", "analysis": "托管服务有望降低自建训练基础设施的门槛，但多数案例依赖云端推理，官方也指出连接挑战；选用前仍需核验端到端时延、断网处理、价格与本体适配。", "sources": [{"label": "Physical Intelligence官方", "url": "https://www.pi.website/blog/api-beta"}]}, {"title": "国内供应链｜京东工业采购平台", "date": "2026-10-13", "body": "京东工业在工博会发布机器人零部件一站式采购平台及产业联盟第二期，称平台聚合超过1600家整机原厂、零部件企业、代工厂及代理经销商，可提供标准件、定制部件、一站式BOM物料清单和整机代工服务。", "analysis": "平台可能减少多供应商寻源和物料匹配成本，但1600家属于平台口径，不代表行业份额，也不能直接证明库存深度、质量一致性或交期。", "sources": [{"label": "快科技企业动态", "url": "https://news.mydrivers.com/1/1157/1157160.htm"}]}, {"title": "海外企业在华｜ABB示范学习与AI工具链", "date": "2026-10-12", "body": "ABB在工博会展示GoFa协作机器人通过示范学习获取手冲咖啡的运动轨迹和注水流程，由智能体规划器拆分步骤，EyeMotion完成识别定位；EyeMotion还与AI Robot Trainer连接，形成视觉、训练与执行工具链。", "analysis": "该方案展示了示范学习与流程规划的组合方式，但目前是厂商现场演示，未公开连续试验成功率、人工介入程度或批量部署证据。", "sources": [{"label": "ABB署名发布稿／国际工业自动化网", "url": "https://www.iianews.com/ca/_01-ABC00000000000375989.shtml"}]}, {"title": "海外产业｜Agility上市流程及Digit5订单条件", "date": "2026-10-13", "body": "Agility公告称相关S-4注册声明已于10月13日生效，拟于11月2日进行股东表决，业务合并仍需满足条件。公告重申Digit 5拥有超过3亿美元承诺订单，但订单附带合同里程碑、产品功能或规格条件，早期客户使用目标为2027年初。", "analysis": "资本安排可为生产和交付提供资金，但当前不能写成已经上市，附条件订单也不等于已确认收入或确定交付量。", "sources": [{"label": "Agility Robotics官方公告", "url": "https://www.agilityrobotics.com/content/agility-robotics-and-churchill-capital-corp-xi-s-4-registration-statement-declared-effective-by-sec-in-connection-with-proposed-business-combination"}]}, {"title": "海外研究｜ChunkAct减少机器人重复调用大模型", "date": "2026-10-13 UTC提交，10月14日新论文列表", "body": "ChunkAct把既有操作经验离线整理成可执行步骤串，在线阶段一次调用执行一段，并在各阶段检查结果；失败时返回具体原因，再由大模型决定后续动作。LIBERO-Pro仿真中，同用GPT-5.6-sol高推理设置及相同视觉、动作和记忆模块，成功率由78.8%升至83.8%，平均调用由24.2次降至8.3次。", "analysis": "结果表明分段执行可能降低模型调用成本并改善纠错，但实验仅限仿真，仍依赖动作库、感知和失败检测，不能外推为真机提速或商用效果。", "sources": [{"label": "arXiv预印本原文表1、2", "url": "https://arxiv.org/html/2610.18874v1"}]}], "followups": ["继续核验Physical Intelligence API的端到端网络延迟、断网或弱网处理机制，以及测试版和后续正式服务的定价。", "跟踪ASD-S2是否出现可核验的客户交付、连续运行数据，并核对京东平台所列部件及整机代工服务的实际库存与交期。", "在Agility 11月2日股东表决后复查合并结果；核验启元10月15日门店进展及实际交付，不以开店或展示替代用户收货证据。"], "coverage": "检索窗口2026-10-12 11:04至2026-10-14 18:02（UTC+8），覆盖昨天漏发期间。重点公众号及公开索引存在访问缺口；Astra仿真开发演示的原帖未能核验，本期不据二手描述推导真机进展。"}, {"date": "2026-10-12", "edition": "6条 · 产品产业4条／研究与研发工具2条", "updated": "11:04", "intro": "本期延迟补发，回溯周末重要进展。WR1把双机协作与柔性物整理放进同一演示，接下来要看完整任务能否稳定重复。鹿明与面壁的合作、自变量对关节及触觉企业的投资，将竞争延伸到模型和关键部件协作，但尚不能当作订单兑现。Genesis与Chronos分别处理接触仿真和系统时延，提示验收应覆盖动态工况。", "items": [{"title": "国内｜西湖机器人WR1展示双机协作叠裤与连续家务", "date": "10月9日报道，10月10日新智元跟进｜72小时补充，非当日首发", "body": "机器之心报道的公司演示显示，WR1驱动的人形机器人完成冰箱取物、转身收纳和整理床铺等连续家务，并由两台机器人协作完成取裤、承托、转移、铺展及灵巧手折叠。现有材料能够证明演示涵盖多步任务和双机配合，但未提供可用于评估此次演示的连续试验成功率或人工介入情况，也不能将旧机械臂实验的时间和成功率套用于此次人形双机演示。", "analysis": "增量在于把移动、双机协同和柔性物操作串成较完整流程。判断其可复用性仍需观看未经剪辑的重复试验，并核验失败恢复、协作同步、单次耗时及人工接管。", "sources": [{"label": "机器之心／新浪署名稿", "url": "https://finance.sina.com.cn/roll/2026-10-09/doc-iniurmnm7886282.shtml"}]}, {"title": "国内｜鹿明机器人与面壁智能合作推进数据、模型和场景应用", "date": "10月10日宣布，10月11日报道｜周末重要进展", "body": "鹿明机器人10月10日宣布与面壁智能建立战略合作，合作范围包括数据采集、模型训练和场景应用，计划结合面壁智能的基座大模型与鹿明的机器人本体能力。报道未披露具体订单、部署数量、任务指标、运行时延、成本或客户验收结果。", "analysis": "这项合作覆盖从数据到场景的链条，但当前仍处于合作承诺层面。后续判断重点是双方能否形成明确的动作接口、闭环数据回流和可复现任务结果，以及是否出现客户部署与验收证据。", "sources": [{"label": "观点网", "url": "https://www.guandian.cn/m/show/611587"}]}, {"title": "国内供应链｜自变量同日参与关节模组与柔性触觉企业融资", "date": "10月10日融资官宣，10月11日采访报道｜周末重要进展", "body": "科创板日报报道，无锡巨蟹智能和墨现科技10月10日官宣融资，自变量机器人同时出现在两家企业的投资名单中。前者面向一体化关节模组，后者聚焦柔性触觉传感器，分别对应机器人驱动与感知环节。投资加强了合作联系，但不能由此推导出独家供货关系、已兑现订单或已建成产能。", "analysis": "同日本体企业布局关节与触觉，反映其希望加强关键部件协作和技术连接。实际供应链价值仍取决于批量交付一致性、良率、成本、版本迭代速度，以及这些部件是否进入自变量的正式产品。", "sources": [{"label": "科创板日报记者报道", "url": "https://api3.cls.cn/share/article/2501589?app=stib&os=ios&sv=218"}]}, {"title": "海外供应链｜Misumi高管谈人形量产瓶颈：执行器和精密制造", "date": "10月10日采访｜周末重要进展", "body": "Misumi Americas高管Steve Ricketts在采访中认为，人形机器人扩产时，执行器可能成为主要压力点，其中涉及精密齿轮、轴承和编码器；精密加工与检测能力会影响规模生产的一致性。他建议在设计尚未稳定时保留柔性工艺，待子组件成熟后再使用硬模具，并通过标准化和减少零件降低成本。", "analysis": "这是供应商观点，并非全行业产能普查、缺货统计或采购报价。其可操作价值在于提醒团队把批次良率、交期和版本管理纳入量产评估，避免在设计频繁变化阶段过早固化工装。", "sources": [{"label": "Robotics & Automation News原始访谈", "url": "https://roboticsandautomationnews.com/2026/10/10/interview-humanoid-robots-are-advancing-fast-manufacturing-them-at-scale-is-the-next-challenge/105812/"}]}, {"title": "研发工具｜Genesis v1.4.4更新GPU仿真与接触稳定性", "date": "10月11日UTC发布，10月12日北京时间", "body": "Genesis官方发布v1.4.4，更新图形处理器（GPU）刚体仿真速度及扰动条件下多接触的稳健性，修复凸体接触深度、法向和位置问题以及GPU非确定性，并减少异构实体内存占用与重复编译。版本说明没有披露统一倍速或真机任务提升数据。", "analysis": "更新主要影响机器人训练和仿真工程，不能据此推断真机成功率提高。升级后应在同一任务上回归吞吐量、结果可重复性和接触轨迹，尤其检查旧训练数据与新版本的兼容性。", "sources": [{"label": "Genesis官方版本说明", "url": "https://github.com/Genesis-Embodied-AI/genesis-world/releases/tag/v1.4.4"}]}, {"title": "海外研究｜Chronos Policy：让机器人知道看到和行动之间隔了多久", "date": "10月9日UTC提交，10月12日arXiv新列表｜预印本", "body": "斯坦福团队为观测和执行动作附加物理时间信息，并在训练中随机改变观测采样与动作开始时刻，以适应传感器异步和推理延迟。在把杯子放到移动碟子的真机任务中，叠加感知与推理时延扰动后，Chronos完成5/10次完整成功、1次部分成功；作为对照的扩散策略为3/10次完整成功、无部分成功。", "analysis": "结果表明显式建模时间可能改善动态操作，但样本仅10次，属于预印本和小规模真机实验，不能称为消除延迟或产线验证。更直接的应用是把时延、抖动和丢帧纳入机器人验收，而非只测静态任务。", "sources": [{"label": "论文及真机结果表7", "url": "https://arxiv.org/html/2610.13929v1"}]}], "followups": ["WR1公布连续试验和人工介入信息时复查；面壁智能与鹿明机器人出现首个联合部署及验收结果后更新。", "跟踪关节模组与柔性触觉企业的交付、良率和报价，继续区分投资关系与实际供货。", "湖北项目公示截至10月12日，结束后复查正式中标结果；启元10月15日门店开业及交付量待核验。"], "coverage": "检索窗口2026-10-10 14:16至2026-10-12 11:04（UTC+8），覆盖周末，并补充72小时内未报内容。具身智能之心、新智元、量子位已分别检索，公众号与公开索引存在缺口。Astra未核验到窗口内新增真机结果，未重复旧演示。"}, {"date": "2026-10-10", "edition": "7条 · 产业与竞品5条／研究2条", "updated": "14:16", "intro": "调休工作日补发。今日观察：①Ultra的按月服务与加速进化的日本代理，显示商业竞争正延伸到交付和运营支持。②零组件出货与研发采购提供更具体的产业信号，但须分清部件、整机、候选报价和正式合同。③两篇研究分别处理执行风险与训练效率，真机验证边界仍比单一高分更有判断价值。", "items": [{"title": "海外｜Ultra获5000万美元A轮，继续扩张仓库机器人服务", "date": "10月9日披露", "body": "Ultra官网宣布5000万美元A轮融资。Humanoids Daily报道，公司与Physical Intelligence深化合作，采用前期集成费加月度软硬件支持费的服务模式；OP1面向包装、分拣和配套作业，公司称累计包装超过50万单。", "analysis": "这类固定工位双臂方案把竞争点落在单均成本和持续产出。累计订单为公司披露，未给出统一接管率与服务毛利；融资额也不能当作设备订单。", "sources": [{"label": "Ultra官网", "url": "https://ultra.tech/"}, {"label": "Humanoids Daily", "url": "https://www.humanoidsdaily.com/news/ultra-50-million-series-a-warehouse-robots-physical-intelligence"}]}, {"title": "国内出海｜加速进化K1、T2进入ELSA日本销售渠道", "date": "10月8日官方公告｜72小时补充", "body": "ELSA Japan宣布与Booster Robotics签订日本销售代理协议，提供研究教育向K1及旗舰T2，计划11月出货，售价需询价。官方列明K1约95厘米、19.5公斤，T2约140厘米、42公斤；T2可选Jetson Thor计算配置。", "analysis": "增量是日本本地渠道和交货计划，不是两款机器人的首次发布。对海外客户，采购、调试及售后可获得性同样影响选型；仍需核验各版本到货和支持范围。", "sources": [{"label": "ELSA Japan官方公告", "url": "https://www.elsa-jp.co.jp/newsrelease/booster-robotics-partnership/"}]}, {"title": "国内｜比亚迪人形机器人外观专利曝光", "date": "10月9日报道", "body": "CnEVPost报道，国家知识产权局10月9日公开比亚迪具身智能机器人的外观专利，配图呈现双臂双足与关节手指。报道同时指出，截至当日公司尚未正式发布该产品；本期尚未取得可直接访问的专利登记原页。", "analysis": "这是汽车企业进入机器人市场的新公开线索，但外观不提供负载、续航或量产证据。竞争判断应等待正式配置、定价与首批应用场景，而不是从专利图片推算产品成熟度。", "sources": [{"label": "CnEVPost报道及专利配图", "url": "https://cnevpost.com/2026/10/09/byd-humanoid-robot-design-emerges/"}]}, {"title": "国内｜长盈精密称前八个月交付超110万件机器人零组件", "date": "10月8日披露｜72小时补充", "body": "格隆汇转述公司互动平台答复：2026年1—8月交付超过110万件人形机器人精密零组件，与国内外多家头部品牌合作，并根据客户需求扩产；公司称三、四季度订单相比上半年增速更快。", "analysis": "零部件出货给出了比概念合作更具体的供应链信号，但“件”不能换算为机器人台数。客户结构、单机价值量与机器人业务收入未在快讯披露，四季度说法仍包含前瞻判断。", "sources": [{"label": "格隆汇转述公司答复", "url": "https://www.gelonghui.com/live/2701879"}]}, {"title": "国内｜湖北具身大模型研发项目公示评标结果", "date": "10月9日官方公示", "body": "湖北人形机器人创新中心委托的研发项目公布评标结果，北京大学武汉人工智能研究院排名第一，投标报价1985万元；公示期为10月9日至12日。另两家候选报价分别为2000万元和1800万元。", "analysis": "这是研发采购推进的证据，尚不能计作最终合同、付款或交付。后续需看正式中标及验收条款，才能判断购买的是哪些能力、是否形成可复用的平台。", "sources": [{"label": "湖北省成套招标公示", "url": "https://www.hubeibidding.com/view/53024.html"}]}, {"title": "算法研究｜CSF：同一个动作，换了对象就要重新判断风险", "date": "10月8日UTC提交，10月9日北京时间｜预印本", "body": "CSF给动作生成器增加按场景触发的过滤层：对物体允许的挥击，场景中出现人时应改成安全动作。四个生成器、2688段对照动作测试中，作者定义的危险事件率最多相对下降90%；另在宇树G1展示了人在执行途中进入视野时的动作中断。", "analysis": "它补上了只检查文字指令的盲区；90%是离线动作指标，不是真机事故率。人的识别、规则覆盖及长时间交互仍需验证，不能据此认定已满足商业安全要求。", "sources": [{"label": "论文原文与试验设置", "url": "https://arxiv.org/html/2610.12467v1"}]}, {"title": "算法研究｜SGS：让机器人多练“差一点就能成功”的任务", "date": "10月8日UTC提交，10月9日北京时间｜论文公开版", "body": "华盛顿大学团队按当前成功率调整训练题目，减少反复练习已掌握或暂时太难的情况。仿真训练后迁移到UR5e：齿轮插入成功47/50次，螺母螺栓装配为18/48次；后者在仿真中约90%，真机只有37.5%。", "analysis": "方法提供了提升训练资源利用率的思路，也暴露不同装配任务的迁移差距。选型应同时看首次成功率、重试次数和单位时间产出，不能只拿仿真最高分估算产线节拍。", "sources": [{"label": "论文及真机结果表2", "url": "https://arxiv.org/html/2610.12465v1"}]}], "followups": ["10月12日后复查湖北项目最终中标；11月核验K1/T2日本实际出货及服务范围。", "等待比亚迪正式发布与长盈后续财报，再更新产品配置、整机对应价值量与收入判断。", "今后按中国大陆实际工作日11:00发送，调休补班照常；10月11日休息，下一期回溯本期截止后的周末重要消息。"], "coverage": "截止2026-10-10 14:16（UTC+8）。以10月9日11:06后新增披露为主，补充72小时内未报内容。具身智能之心、新智元、量子位已分别检索；公开索引和公众号访问存在缺口。Astra仿真开发报道与昨日重复，本期不重复收录。"}, {"date": "2026-10-09", "edition": "8条 · 新品／落地／供应链／论文", "updated": "11:06", "intro": "延迟发送：本期核验与编写未能在11:00前完成。今日判断：①正行与优必选把目标落到补货、巡检和厂内物流，验收应跟着具体任务走。②CRIS-0和DreamTrue都在处理“看起来完成、实际失败”的问题，研发应单列结果核验与失败恢复。③Astra的新进展是辅助构建和调试仿真，不能把开发工具能力与真机策略成绩混为一谈。", "items": [{"title": "国内｜新品：正行创新发布H1、C1与零售运营方案", "date": "10月8日APRCE发布", "body": "量子位刊载发布信息：正行创新推出双足人形H1、窄体轮臂C1及统一管理平台M1，面向补货、搬运、盘点和巡检，平台支持人工接管。商业服务计划2027年启动，可采购或订阅；现阶段将与连锁零售伙伴开展测试。", "analysis": "“24/7”是目标场景，不是已证明全年无故障；99%自主完成的宣传缺少公开测试分母，需用店内任务节拍和接管率验收。", "sources": [{"label": "量子位发布报道", "url": "https://www.qbitai.com/2026/10/502035.html"}]}, {"title": "国内｜工厂落地：优必选与一汽大众推进物流场景", "date": "10月8日披露｜72小时补充", "body": "第一财经转述优必选消息称，双方近日达成战略合作，将共同开发、测试具身机器人物流应用，并构建示范场景。增量是物流任务开发与测试安排；公开快讯未给出采购数量、金额、部署车型或稳定运行成绩。", "analysis": "应跟踪首个可验收工位、节拍和接管记录；合作协议不能计作已交付订单，也不宜当作双方首次接触。", "sources": [{"label": "第一财经", "url": "https://www.yicai.com/brief/103385313.html"}]}, {"title": "海外｜模型系统：Aether发布带阶段核验的CRIS-0", "date": "10月8日官方技术报告", "body": "CRIS-0把任务拆成可核验阶段，结合因果世界模型、学习策略、规则函数与导航工具；执行后检查结果，失败可重试、退回阶段或修正工具。官方展示真实机器人家务任务，但没有在页面给出统一完整任务成功率和独立测试。", "analysis": "相比只看动作是否执行，阶段结果核验更适合长流程；仍需统计漏检、误判与恢复成本，不能把演示当作家庭安全认证。", "sources": [{"label": "Aether官方技术报告", "url": "https://aetherlabs.ai/articles/real-world-autonomous-robotic-system-with-causality-driven-agent-and-world-model"}]}, {"title": "海外｜Astra×机器人：NVIDIA展示代理辅助仿真开发", "date": "10月8日官方发布", "body": "NVIDIA介绍开发者用GPT-6 Astra连接Omniverse物理、渲染和场景库，搭建仓库人形仿真、设计拆装工具并迭代控制器。G1跨栏示例在100次仿真试验中成功64次；全过程由开发者提出需求、检查结果和引导修改。", "analysis": "这里Astra主要承担研发工具与控制器开发，成绩属于仿真；下一步应对照人工开发耗时、物理误差和真机迁移，而非宣称机器人已自主学会跨栏。", "sources": [{"label": "NVIDIA官方案例", "url": "https://blogs.nvidia.com/blog/developers-simulation-frontier-ai-agents/"}]}, {"title": "国内｜供应链：中科摩通披露机器人部件装配测试方案", "date": "10月8日官网披露；峰会具体日期未列", "body": "中科摩通称已研发面向减速器、丝杠、灵巧手、电机和关节模组的制造设备，将汽车领域压装、拧紧、焊接及测试工艺迁移至机器人部件，覆盖单工序至整线和出厂终测。公告展示方案，未披露新增客户订单与实测良率。", "analysis": "量产判断应把部件设计与装配一致性分开；需要验收节拍、良率、换型成本，不能从展示直接推算人形产能。", "sources": [{"label": "中科摩通官方公告", "url": "https://casmt.com/newsinfo/394.html"}]}, {"title": "国内｜融资与数据：厘清智能完成两轮数亿元融资", "date": "10月8日宣布", "body": "投资界报道，厘清智能完成天使轮及天使+轮数亿元融资，蚂蚁集团连续投资并领投天使+轮。资金拟用于数据、模型、物理仿真、评测和跨本体部署；公司已推出T1数采手套及Ego采集设备，具体各轮金额未披露。", "analysis": "资金流向从本体扩展到数据与适配服务；平台价值仍要由付费客户、数据质量及跨设备复用效果证明，融资不等于技术验收。", "sources": [{"label": "投资界原始报道", "url": "https://news.pedaily.cn/202610/569895.shtml"}]}, {"title": "海外合作｜新论文：Dex-One2Many从单视频学习灵巧操作", "date": "10月8日提交预印本，10月9日arXiv列表收录", "body": "方法把人类演示转为分阶段场景关系图，用于仿真强化学习的初始状态与奖励，再零样本部署到UR3及20自由度Wuji手。五类任务中，每方法每任务测10次已见、20次未见配置；作者报告未见配置平均成功率75%。", "analysis": "单视频不等于免训练：仍需大规模仿真及物体位姿估计。接触误差、几何偏差会影响真机，有限任务结果不能外推任意工具。", "sources": [{"label": "论文与试验口径", "url": "https://arxiv.org/html/2610.12470v1"}, {"label": "作者项目页", "url": "https://dex-one2many.github.io/"}]}, {"title": "国内｜新论文：DreamTrue减少世界模型对失败的误判", "date": "10月8日提交预印本，10月9日arXiv列表收录", "body": "中科院自动化所与高德团队用几何校准、反事实动作及视频奖励后训练改进预测。三类双臂仿真任务、四种VLA、240条动作轨迹构成24组条件；预测成功率的平均绝对误差从12.92降至7.08个百分点。", "analysis": "价值在于让失败抓取也被预测为失败；这是世界模型评估准确度，不是机器人成功率提升。未见场景和长时接触仍需外部验证。", "sources": [{"label": "论文原文", "url": "https://arxiv.org/html/2610.12468v1"}, {"label": "作者仓库入口（未实跑）", "url": "https://github.com/brave-eai/DreamTrue"}]}], "followups": ["零售与物流：出现首店／首工位报告时，复查任务分母、连续运行、接管率与成本；正行2027商业化安排持续跟踪。", "算法：对同一失败任务检查核验误报、恢复耗时和总成本；DreamTrue先验证排名与失败预测，再用于策略选型。", "周末停发：10月10日虽调休补班也不推送；下一工作日报回溯自本期截止时间，合并周末大新闻。"], "coverage": "截止2026-10-09 11:06（UTC+8），以昨日成功日报截止10月8日11:47后的新增信息为主，必要补充72小时内未报内容。逐一检索具身智能之心、新智元、量子位；量子位新品原文可读，具身智能之心公开索引滞后，微信公众号覆盖仍有缺口。"}, {"date": "2026-10-08", "edition": "9条 · 节后汇总 · 延迟补发", "updated": "11:47", "intro": "延迟补发｜节后汇总。①启元从发售进入首批交付，爱宝也披露活动数据，商业判断应转向履约量与接管率。②Dyna和德塔强调跨动作连续执行，选型需测试交接、平衡与失败恢复。③两篇Astra新论文提示，接口和技能库会显著影响表现，应固定模型、任务与预算再比较；上述为本期研究判断。", "items": [{"title": "国内｜交付：启元首批产品到用户手中", "date": "10月1日｜假期重要进展", "body": "上观号授权稿经新浪转载披露，启元授权体验店在上海、深圳、杭州同步开启首批交付，彭志辉到场向用户颁发交付证书。这补上了此前“10月1日起交付”的待核查结果；报道未披露交付台数、订单履约比例或长期使用数据。", "analysis": "首批交付证据比发售预告更进一步，下一步应看持续履约与用户故障反馈，不能从仪式推算销量。", "sources": [{"label": "上观号授权稿／新浪", "url": "https://finance.sina.com.cn/jjxw/2026-10-01/doc-inittvfv5083565.shtml"}]}, {"title": "国内｜模型：德塔Delta-0连接全身控制与操作", "date": "9月下旬发布；9月29日新智元报道｜停发期间进展", "body": "德塔官方报告将69自由度全身控制器与世界—动作模型结合，展示铺床、开洗碗机等任务。长流程接受阶段指令；公司还称用Astra辅助重建仿真资产。镜像厨房内部试验中，加入人工纠正与强化学习后，洗碗机任务从4/20成功提高至13/20。", "analysis": "重点是控制、数据与纠错接口协同；这是公司内部试验，阶段指令与人工训练纠正不能省略为“完全自主通用家政”。", "sources": [{"label": "德塔技术报告", "url": "https://deltai.com/en/blog/delta-0"}, {"label": "新智元／新浪", "url": "https://finance.sina.com.cn/stock/t/2026-09-29/doc-initnfqc7871973.shtml"}]}, {"title": "海外｜新品：Dyna用Taku串起一小时洗衣流程", "date": "9月29日｜停发期间进展", "body": "Dyna推出轮式半人形Taku和Dyna-2.1，官方提供称为自主、未剪辑的一小时洗衣流程演示，覆盖洗涤、烘干、折叠及上架。Taku以双7自由度手臂、可折叠下身和四个转向轮跨工位作业，系统结合操作策略与流程决策。", "analysis": "验收应从单次折叠转向跨工位交接和失败恢复；公司演示尚不能代表客户现场跨班次可靠性。", "sources": [{"label": "Dyna官方技术报告", "url": "https://www.dyna.co/dyna-2.1"}]}, {"title": "海外发布｜供应链：Sharpa同时推出本体、灵巧手与采集手套", "date": "9月28日美东公告，UTC+8为9月29日｜停发期间进展", "body": "Sharpa在IROS公布D01机器人、W02灵巧手和AE01数据手套。公司披露W02具21个主动自由度、重量低于750克，并将触觉覆盖扩展到手指和手掌；AE01采用22自由度采集结构，配合反馈支持操作数据采集。", "analysis": "一体配套可能降低本体与采集系统适配工作量；具体报价、批量供货和独立耐久测试仍需核验。", "sources": [{"label": "Sharpa公司公告／美通社", "url": "https://www.prnewswire.com/news-releases/sharpa-unveils-three-flagship-products-d01-robot-w02-dexterous-hand-and-ae01-data-glove-at-iros-2026-302892129.html"}]}, {"title": "海外｜灵巧操作：Atlas新手增至13自由度", "date": "10月1日报道｜假期重要进展", "body": "Boston Dynamics官方介绍Atlas新一代四指手：从7提升至13自由度，采用关节直接驱动和触觉感知，面向手内调整、工具操作及高保真仿真训练。公司解释，少一根手指可减少执行器、体积和潜在故障点；展示视频包含遥操作片段。", "analysis": "可比较自由度与可维护性的取舍，不能把演示动作全部算作自主完成，也不能只按指头数量评优劣。", "sources": [{"label": "Boston Dynamics技术说明", "url": "https://bostondynamics.com/blog/robot-hands-for-modern-ai-and-real-work"}]}, {"title": "国内／国际合作｜论文：PyRUA-Lean优化Astra机器人调用", "date": "10月1日提交预印本｜假期重要进展", "body": "作者在700个仿真任务实例中，以相同Astra规划器、动作能力和调用预算比较代码执行与逐项工具调用：成功率由63.1%升至71.7%。双方都成功的实例上，输入token减少65%；方法把条件检查、重试和选择性观察合并进代码。", "analysis": "增益来自接口组织，不能称为新模型战胜VLA；节省口径只限共同成功样本，也不等于真机耗时降低65%。", "sources": [{"label": "论文原文", "url": "https://arxiv.org/html/2610.01939v1"}, {"label": "作者代码（已核验入口，未实跑）", "url": "https://github.com/DAGroup-PKU/PyRUA-Lean"}]}, {"title": "学术｜论文：Skill2Real将仿真技能迁移到真机", "date": "10月2日提交预印本｜假期重要进展", "body": "Skill2Real在仿真中学习并冻结分层可执行技能，再经统一接口用于真机。固定Astra和接口，UR5e四类任务、每方法每类20次试验中，平均完成率从无技能库的27.50%升至78.75%；抽屉任务仍仅50%。", "analysis": "这支持单独评估技能库的贡献；四类桌面任务和有限样本不代表人形全身作业能力，本次未核验可运行代码。", "sources": [{"label": "论文与真机实验表", "url": "https://arxiv.org/html/2610.02788v1"}]}, {"title": "海外｜安全供应链：Agility与FORT扩展Digit安全接口", "date": "10月1日｜假期重要进展", "body": "双方签署合作备忘录，计划深化Digit 5的三部分安全架构：安全手持终端、机器人端通信，以及连接外部安全系统的接口。官方说明手持终端用于设置、维护或异常时的独立人工覆盖，补充机器人机载安全能力。", "analysis": "车间接入和急停链路是部署成本的一部分；备忘录不等于完成认证，也不是新增客户订单。", "sources": [{"label": "Agility官方公告", "url": "https://www.agilityrobotics.com/content/agility-and-fort-robotics-announce-strategic-partnership-to-advance-humanoid-robot-safety"}]}, {"title": "国内｜落地追踪：爱宝门店活动披露首日数据", "date": "9月28日活动、9月29日报道｜上期预告后续", "body": "财联社刊载的活动稿披露，9月28日三店直播采集到10小时运行展示、4299次人机交互，并说明机器人轮换上岗。此次有了实际活动结果，但接管次数、停机、独立用户数和转化分母未披露，不能视为单机连续自主运行十小时。", "analysis": "下一轮应索取分机时长和人工介入记录，才能判断热闹的互动是否能复制为稳定服务。", "sources": [{"label": "财联社刊载活动稿", "url": "https://m.cls.cn/detail/2495303"}]}], "followups": ["启元：继续核验交付数量、用户持续使用反馈及10月15日广州金融城店计划；有实际开业或履约数据时更新。", "算法：复现PyRUA-Lean和Skill2Real时固定任务、模型与预算，同时记录总尝试成本、耗时和失败；两篇成绩不能直接横比。", "落地：跟踪Taku客户现场跨班次表现、爱宝分机接管率，以及新灵巧手供货与耐久测试。"], "coverage": "回溯2026-09-28 11:15至2026-10-08 11:47（UTC+8），包含国庆假期及此前未成功发送区间。逐一检索具身智能之心、新智元、量子位并扩展行业媒体；具身智能之心公开转载索引滞后，微信公众号覆盖不完整，不承诺无遗漏。"}, {"date": "2026-09-28", "edition": "5条 · 延迟补发 · 物理评测、运控开源与落地", "updated": "11:15", "intro": "延迟补发：本机任务恢复后执行，本期未能在11:00准点发送。今日判断：①美梦空间将物理参数扰动列为模型评测对象，提示选型应增加质量、摩擦变化测试，不能只看视觉泛化分数。②Asimov公开运控训练框架，研发团队可以检查PPO与AMP配置；但代码可用不等于真机可靠性已验证。③爱仕达预告披露门店运行数据，HD现代则计划在自身装配线训练，商业验证应转向连续运行、人工接管和任务节拍。以上为基于本期证据的研究判断。", "items": [{"title": "国内｜模型发布／评测：美梦空间推出Physical-WAM与物理扰动基准", "date": "9月26日数贸会发布；相关基准预印本9月22日提交。", "body": "美梦空间供稿、量子位转载称，Physical-WAM通过物理表征连接感知、预测与动作。配套RoboTwin-Phys论文在双臂仿真中引入13类参数变化，并提供逾5000条带物理参数的专家示范；受测模型在物理扰动下明显退化。论文属预印本，不能把基准结果当作新模型已获真机验证。", "analysis": "新增价值是把摩擦、质量等变化纳入验收；论文对照部分引用既有公开成绩，仍需统一环境复现。本次未核验可运行的官方代码入口。", "sources": [{"label": "美梦空间供稿／量子位", "url": "https://www.qbitai.com/2026/09/498478.html"}, {"label": "基准论文与实验口径", "url": "https://arxiv.org/html/2609.26292v1"}]}, {"title": "国内｜商业落地预告：爱仕达计划连续三天公开爱宝门店作业", "date": "9月27日晚报道；活动计划9月28—30日。", "body": "财联社报道的活动安排显示，爱宝拟在温岭炊具旗舰店上岗，并联动上海、无锡门店，执行迎宾、导购、带路和发券。公司计划公布运行时长、接待人数、互动频次与扫码转化次数。本期核验的是活动计划，尚未取得当天完整运行成绩及人工接管记录。", "analysis": "比单次舞台演示更可检验，但接待量不等于自主完成率；应把机器人独立作业、人工协助及商业转化分别统计。", "sources": [{"label": "财联社／东方财富", "url": "https://finance.eastmoney.com/a/202609273884511065.html"}]}, {"title": "海外｜运控开源：Asimov开放PPO与AMP训练框架", "date": "9月25日发布消息，9月26日报道；72小时补充。", "body": "Menlo Research的Asimov 1官方仓库已提供基于Isaac Lab的运动策略训练与评估代码，包含普通PPO基线和推荐的AMP配置，支持单卡、多卡训练及策略导出。仓库明确列出环境与显卡要求；已核验训练入口，未实跑，也未核验可直接下载的预训练权重。", "analysis": "适合作为比较奖励设计、动作先验与sim-to-real配置的工程样本；真机迁移仍需核对本体参数、执行器和实测稳定性。", "sources": [{"label": "官方训练代码", "url": "https://github.com/menloresearch/isaac_asimov/"}, {"label": "发布日期与开放范围报道", "url": "https://www.humanoidsdaily.com/news/asimov-open-source-locomotion-policy-training"}]}, {"title": "海外｜制造业：HD现代拟把人形机器人AI复用到既有产品线", "date": "9月27日CTO书面采访。", "body": "HD Hyundai Robotics CTO在首尔经济日报采访中表示，人形项目处于原型、操作任务训练与验证阶段，计划进入自身控制器装配线采集数据。感知、精细操作、力触觉控制和任务规划能力拟复用到工业及协作机器人。采访未给出人形量产上市日期或稳定作业成绩。", "analysis": "这提供了以现有工业客户与产线承接具身技术的路径；目前是研发路线，不能把协作机器人销售目标算成人形机器人订单。", "sources": [{"label": "首尔经济日报原始采访（英文译文）", "url": "https://en.sedaily.com/finance/2026/09/27/hd-hyundai-robotics-to-extend-humanoid-ai-tech-to"}]}, {"title": "海外｜供应链：Seyond在IROS展示面向机器人近场感知的激光雷达", "date": "9月25日官方公告；72小时补充，非首次发布产品。", "body": "Seyond宣布在IROS展示机器人传感方案，覆盖人形、物流及配送平台。官方列出Hummingbird D1R的紧凑设计、140°×100°视场和近距检测，并称继续开发更小、更轻、更低功耗方案。公告没有披露人形客户订单、机器人领域出货量或新的产品价格。", "analysis": "选型可关注安装空间与近场盲区，但全业务累计交付百万传感器不等于人形订单；供货与成本判断仍需具体客户和报价。", "sources": [{"label": "Seyond官方公告", "url": "https://seyond.com/from-warehouses-to-sidewalks-seyond-scales-lidar-for-the-next-generation-of-robotics/"}]}], "followups": ["爱宝：9月28日晚至30日公布成绩后复查运行时长、停机和接管次数；只有完整分母才能判断是否具备复制条件。", "物理评测与运控：待RoboTwin-Phys可运行代码、独立复现或Asimov真机连续运行结果出现，再比较同任务成功率、耗时和失败类型。", "用户点名主线：启元继续核实10月1日起真实交付，9月27日门店报道另提10月15日广州金融城店试营业；Astra继续等待可核验的原始实速视频、同预算评测与成本数据。"], "coverage": "逐一检索具身智能之心、新智元、量子位；量子位本次原文可读，具身智能之心转载索引滞后。Astra实速演示的作者原帖访问受限，未将转载结论作为已核实新闻；9月24日K1预印本已核验但超出72小时窗口，留作专题跟踪。本期只选5条，不用旧闻凑数。"}, {"date": "2026-09-22", "edition": "6条 · 新品、落地与模型评测", "updated": "10:37", "intro": "今日判断：①宇树公开灵巧手售价，Atlas启用工厂训练中心，硬件竞争正接受成本与现场可靠性的检验。②RPent提供可复用的“大模型规划＋专用策略执行”框架，但加速有成功率代价；评估时应同时看时延与失败恢复。③Light-O1的人类动作预训练与RoboHarm的拒绝测试提示：动作能力、跨本体迁移和安全必须分别测量。以上为基于本期证据的研究判断。", "items": [{"title": "国内｜新品／供应链：宇树发布Dex5-S，单手3.99万元起", "date": "9月21日晚发布。", "body": "据证券时报、中国基金报报道，宇树发布真手1:1尺寸的Dex5-S，单手22自由度，售价3.99万元起。发布演示涵盖拿勺、剪纸和动态抓握；中国基金报转述单手最大负载2公斤、持续负载1公斤。上述为发布参数与演示，尚非独立耐久性或成功率测试。", "analysis": "这为灵巧手选型提供新的公开价格参照；需进一步核对触觉版本、接口、寿命和交期，不能仅以自由度判断整机操作能力。", "sources": [{"label": "证券时报／东方财富", "url": "https://finance.eastmoney.com/a/202609213880222695.html"}, {"label": "中国基金报／新浪", "url": "https://finance.sina.com.cn/jjxw/2026-09-21/doc-inisqzxv7591986.shtml"}]}, {"title": "海外｜工业落地：Atlas工厂训练中心在现代美国工厂启用", "date": "9月21日官方公告。", "body": "Boston Dynamics宣布RMAC首期已在现代美国工厂园区投入运行，Atlas正在练习汽车零部件物流、排序与装配前摆放。公司计划2027年迁入约十倍规模设施，2030年扩展至部件装配；本次公告未给出现场节拍、错误率或已部署机器人数量。", "analysis": "增量是生产现场训练基础设施落地。未来部署量和规划产能仍是目标，不应当作当前订单兑现或稳定量产。", "sources": [{"label": "Boston Dynamics官方", "url": "https://bostondynamics.com/news/boston-dynamics-opens-robotics-metaplant-application-center-to-train-humanoid-robots-for-manufacturing-tasks/"}]}, {"title": "国内｜商业试运营：大晓机器人进入中国石油便利店履约流程", "date": "9月21日报道；合作及试运营发生于近日。", "body": "中国证券报向大晓机器人获悉，其与中国石油上海销售合作，首店振兴店昆仑好客已试运营。公司披露，美团订单经石油数智平台进入作业系统，机器人在75厘米通道、2米货架条件下拣选、搬运、打包并更新订单状态；尚未披露连续运营效率、人工接管率与项目金额。", "analysis": "从展示抓取转向真实订单闭环是有价值的验证；能否扩店，应以峰值订单履约、故障恢复和运营成本衡量。", "sources": [{"label": "中国证券报采访", "url": "https://www.cs.com.cn/ssgs/01/2026/09/21/detail_2026092110040700.html"}]}, {"title": "国内｜算法／开源：RPent连接Astra规划与VLA执行", "date": "9月21日正式发布；量子位线索，已核验官方与代码。", "body": "清华、无问芯穹、正行创新开源RPent，将通用模型规划、专用策略、工具和记忆连接起来。官方报告Astra配置在LIBERO-Pro仿真达92.63%；另一组LIBERO Object的200次评测中，任务卡模式将平均执行时间从283.6秒降至40.9秒，成功率下降3.5个百分点。", "analysis": "可测试重复任务能否通过经验复用减少推理开销；这两组指标不可拼成同一实验，也不是“真机92.6%成功率”或全面替代VLA。", "sources": [{"label": "官方发布与实验口径", "url": "https://www.infinigence-ai.com/news-updates/239.html"}, {"label": "官方代码", "url": "https://github.com/RLinf/RPent"}]}, {"title": "国内｜技术报告／模型：Light-O1以人类动作预训练扩展全身智能", "date": "9月21日发布；公司技术报告，非已核验的同行评审论文。", "body": "亮源新创发布Light-O1及Preview。官方报告完整模型在RoboCasa GR-1的24项仿真桌面任务上，按每项50次评估取得79.3%宏平均成功率。开源Preview接收文字并输出统一人体动作表示；G1示例通过GEAR-SONIC控制器执行，仓库提供的是MuJoCo仿真示例。", "analysis": "值得验证人类动作先验对运控与跨本体适配的价值；开源Preview不等于完整视觉移动操作系统，仿真成绩和真机展示须分开看。", "sources": [{"label": "官方技术报告", "url": "https://www.lightorigins.cn/en/blog/light-o1"}, {"label": "代码与开放范围", "url": "https://github.com/lightorigins/Light-O1"}]}, {"title": "海外｜Astra安全专题：RoboHarm要求把“会做”和“该做”分开评测", "date": "9月18日原始评测；9月21日新智元、量子位集中报道，本期专题补充。", "body": "Robocurve在同一双臂YAM平台测试3种策略、5类危险指令，每格20次，共300次。原文记录Astra因安全原因拒绝2/100次，Fable为20/100；MolmoAct2没有原生拒绝机制，低完成率不能说明更安全。研究限于固定措辞和五个场景，代码并非冻结的完整结果数据集。", "analysis": "接入真实设备时应单列拒绝、权限边界和人工接管测试；不把单台实验推广成所有场景结论，也不照搬媒体混用的完成率分母。", "sources": [{"label": "原始评测与限制", "url": "https://robocurve.org/roboharm/"}, {"label": "开源工具及复现边界", "url": "https://github.com/robocurve/roboharm"}]}], "followups": ["Dex5-S：获得正式规格、交期或第三方寿命测试时复查；把持续负载、触觉配置与热稳定性列为选型条件。", "Atlas与便利店试点：披露连续运营小时、任务节拍、人工接管率或扩店订单后更新；启元仍按10月1日起实际交付跟踪。", "RPent与Light-O1：出现独立复现时检查同任务、同预算的成功率／耗时／成本；先区分模型、控制器和公开材料范围。"], "coverage": "已逐项检索具身智能之心、新智元、量子位；部分公众号原文及量子位页面访问失败，具身智能之心公开转载索引明显滞后，已通过署名报道和一手源补查，不能视为完整覆盖。"}, {"date": "2026-09-21", "edition": "修订版 · 8 条", "updated": "14:06", "intro": "启元新品开始接受价格、开发生态与实际交付的检验。通用模型进入机器人，应评估与专用策略和控制器的分工；供应链判断仍需落到真实订单和部署效果。本期补入近期Astra研究，明确其原始时间与验证边界。", "items": [{"title": "国内｜新品首条补报：启元 Q1 与 T1 正式发售", "date": "9 月 20 日发布；本次补入首条。", "body": "启元发布 Q1、T1 两款个人机器人，基础版均为 19999 元，Q1 探索版 26999 元，T1 Pro 29999 元。新智元报道：探索版开放 SDK／HDK，T1 Pro 增加 Orin Nano 及回充等功能；公司披露每 2.5 分钟下线一台，并公布运控、跟随、交互模型与技能生态。报道正文写明 10 月 1 日起按订单顺序发货，不能将“发售即发货”标题理解为当前全部现货交付。", "analysis": "从价格、开发接口和消费场景判断，这是昨天应优先收录的新品事件；下一步看真实交付、安全与留存，产线节拍不能换算成销量。", "sources": [{"label": "新智元／新浪分发", "url": "https://finance.sina.com.cn/wm/2026-09-20/doc-inisnssr1349676.shtml"}, {"label": "证券时报采访", "url": "https://egs.stcn.com/news/detail/2343387.html"}]}, {"title": "国内｜产业与融资：智身科技完成数亿元 B 轮融资", "date": "9 月 20 日披露。", "body": "据第一财经转引公司消息，本轮由阿联酋 Stone Venture 领投，洪山资本及多家产业投资方参与，资金用于本体、具身大小脑和任务作业能力。新京报明确其披露的累计量产超过 1.5 万台是行业级四足机器人口径，尚未披露人形机器人量产情况，不能将这个数字当作人形机器人销量。", "analysis": "值得跟踪能源、安防等场景中的付费部署与复购，以及成熟四足平台能力向人形平台迁移的实际进度。", "sources": [{"label": "第一财经", "url": "https://www.yicai.com/brief/103371070.html"}, {"label": "新京报", "url": "https://www.bjnews.com.cn/detail/1789881689129881.html"}]}, {"title": "国内｜上游供应链：千觉机器人连续完成两轮数亿元战略融资", "date": "9 月 19 日报道。", "body": "科创板日报报道称，千觉近期连续完成两轮数亿元战略融资，资金投向高精度视触觉传感器迭代与规模交付，并建设真实交互数据采集、触觉仿真和数据集，研发触觉具身模型及世界模型。报道未给出两轮各自的精确金额，不作拆分估算。", "analysis": "触觉供应商的竞争正在延伸到数据与模型。选型时应把一致性、耐久性、标定成本和接触任务成功率一起考察。", "sources": [{"label": "科创板日报／东方财富", "url": "https://finance.eastmoney.com/a/202609193879237148.html"}]}, {"title": "国内／海外｜供应链核验：Optimus 审厂传闻尚未获一致确认", "date": "9 月 18 日 13:03 报道，约 72 小时内。", "body": "第一财经向相关公司核实审厂消息时，拓普接电人员称未接到相关审厂通知，同时介绍了执行器方面的合作；均胜以保密要求未作回应，三花人员称不清楚新一轮审厂情况。特斯拉截至该报道发稿时未回应。当前能够确认的是各方回应，不能据此确认新增订单、批量供货或量产时间表。", "analysis": "把正式订单、定点披露和可核验出货作为后续跟踪依据，避免将汽车客户关系直接等同于机器人供货关系。", "sources": [{"label": "第一财经原文", "url": "https://m.yicai.com/news/103369671.html"}]}, {"title": "算法专题｜GPT-6 Astra与机器人：混合策略与上下文学习", "date": "近期研究补充，非今日新发布；GPT-Policy预印本于9月16日提交。", "body": "《GPT 6 Astra as an Embodied Policy》作者主页披露：所选RoboDojo任务中，π0.5＋Astra混合策略成功率48%，直接控制26%，仅代表该组实验。另一项GPT-Policy研究连接上下文编译、VLM提出动作与受约束控制器；真机中人类示范视频有帮助，接触任务增加对齐动作参考进一步改善，但精确接触、结果核验和安全仍存在缺口。两项研究不能混为同一评测，也不能据此推论全面替代VLA。", "analysis": "建议在相同任务和预算下比较专用VLA、Astra工具调用与混合纠偏，同时记录耗时、费用、人工介入及失败恢复，以整体任务收益判断采用价值。", "sources": [{"label": "作者说明", "url": "https://shuyumo2003.github.io/"}, {"label": "策略代码", "url": "https://github.com/anonymous-report-421/GPT-as-Policy"}, {"label": "GPT-Policy论文", "url": "https://arxiv.org/abs/2609.19138"}]}, {"title": "算法／新论文：Coda 用末端纠正改善 VLA 推理效率", "date": "9 月 18 日提交，arXiv 预印本；较截止时间略超 72 小时。", "body": "《Fewer Steps, Better Actions》冻结原有策略，只训练轻量纠正器。在 50 个 RoboTwin Easy 仿真任务中，五步 Coda 成功率为 74.68%，对应五步基线为 71.64%；相对默认十步策略，模型前向延迟降低 30.2%。论文明确实验在仿真中进行，延迟不包含通信和机械执行，视觉随机化下也没有清晰的平均提升。", "analysis": "适合评估能否在不重训整套 VLA 的情况下缩短推理时间，但需要重新验证真机闭环表现。", "sources": [{"label": "论文及全文入口", "url": "https://arxiv.org/abs/2609.21216"}]}, {"title": "海外｜模型发布补充：Figure Helix 2.5 测试陌生住宅泛化", "date": "9 月 17 日官方发布，上周重要进展。", "body": "Figure 报告在 30 个未采集训练数据的住宅测试整理客厅、叠毛巾和铺床。其受控对比中，使用 Index 人类行为数据预训练后，完整任务成功率从 9% 提升到 56%。这些结果是公司披露，覆盖指定三类行为，尚不能推论机器人已能处理任意家务或达到消费级可靠性。", "analysis": "关注人类行为数据能否减少逐场景采集成本，并要求披露失败类型、人工干预与任务覆盖边界。", "sources": [{"label": "Figure 官方技术说明", "url": "https://www.figure.ai/news/helix-2-5-zero-shot-30-home-generalization"}]}, {"title": "海外｜论文补充：RoM-Nav 在宇树 G1 上验证跨楼层导航", "date": "9 月 16 日提交；预印本，项目页标注 ICRA 2027 在审。", "body": "加州理工等研究者先在简化动力学中学习导航，再迁移到完整人形系统，结合激光雷达和深度输入，并在策略输出端加入 Poisson 安全过滤器。项目展示 G1 在真实建筑中无地图跨楼层行走；两类分布外障碍各 10 次对比实验中，加入过滤器后均未观察到碰撞，但到达目标耗时增加。", "analysis": "导航训练与运动控制分层值得借鉴；小样本无碰撞不等于普遍安全保证，仍需测试感知盲区和人员混行。", "sources": [{"label": "论文", "url": "https://arxiv.org/abs/2609.19272"}, {"label": "作者项目与视频", "url": "https://wdc3iii.github.io/rom-nav/"}]}], "followups": ["启元 10 月 1 日起的实际交付、版本可用性及用户反馈。", "触觉传感器真实交付、寿命，以及对操作成功率的增益。", "Optimus 正式订单与量产披露，VLA 加速和住宅泛化能否在更多真机复现。"]}];